-- Refuse attachment to an existing business database.
DELIMITER $$
CREATE PROCEDURE assert_fresh_release_database()
BEGIN
 IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name<>'flyway_schema_history') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FRESH_RELEASE_REQUIRES_EMPTY_DATABASE';
 END IF;
END$$
DELIMITER ;
CALL assert_fresh_release_database();
DROP PROCEDURE assert_fresh_release_database;


-- EMPTY DATABASE ONLY: 178 final metadata + approved locked-source additions.

-- No reference business rows, credentials, Flyway history, or auto-increment watermarks.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE `ACT_EVT_LOG` (
  `LOG_NR_` bigint NOT NULL AUTO_INCREMENT,
  `TYPE_` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `PROC_DEF_ID_` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `PROC_INST_ID_` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `EXECUTION_ID_` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `TASK_ID_` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `TIME_STAMP_` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `USER_ID_` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `DATA_` longblob,
  `LOCK_OWNER_` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `LOCK_TIME_` timestamp(3) NULL DEFAULT NULL,
  `IS_PROCESSED_` tinyint DEFAULT '0',
  PRIMARY KEY (`LOG_NR_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

