  `actor_id` bigint NOT NULL,
  `device_id` bigint DEFAULT NULL,
  `request_key` varchar(180) NOT NULL,
  `log_key` varchar(180) NOT NULL,
  `log_received_at` datetime(3) NOT NULL,
  `parser_task_id` varchar(128) NOT NULL,
  `parser_version` varchar(128) DEFAULT NULL,
  `source_file_id` bigint DEFAULT NULL,
  `log_version` bigint DEFAULT NULL,
  `serial_number` varchar(128) DEFAULT NULL,
  `conp_version` varchar(255) DEFAULT NULL,
  `boot_version` varchar(255) DEFAULT NULL,
  `cpld_version` varchar(255) DEFAULT NULL,
  `pcb_version` varchar(255) DEFAULT NULL,
  `status` varchar(40) NOT NULL,
  `version_status` varchar(40) NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_device_log_parse_request` (`tenant_id`,`request_key`),
  KEY `idx_device_log_parse_history` (`tenant_id`,`device_id`,`log_received_at`,`id`)
