CREATE TABLE `ast_device_warranty_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '维保记录编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `warranty_start_date` date DEFAULT NULL COMMENT '维保开始日期',
  `warranty_end_date` date DEFAULT NULL COMMENT '维保结束日期',
  `warranty_months` int unsigned DEFAULT NULL COMMENT '维保期限月数',
  `warranty_grade` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保等级',
  `warranty_contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保合同编号',
  `extended` bit(1) DEFAULT NULL COMMENT '是否延保',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `combined_device_sn` text COLLATE utf8mb4_unicode_ci,
  `product_code` text COLLATE utf8mb4_unicode_ci,
  `product_name` text COLLATE utf8mb4_unicode_ci,
  `product_description` text COLLATE utf8mb4_unicode_ci,
  `grade_name` text COLLATE utf8mb4_unicode_ci,
  `shipment_time` datetime(3) DEFAULT NULL,
  `warranty_flag` text COLLATE utf8mb4_unicode_ci,
  `source_warranty_start_time` datetime(3) DEFAULT NULL,
  `source_warranty_end_time` datetime(3) DEFAULT NULL,
  `original_warranty_start_time` datetime(3) DEFAULT NULL,
  `original_warranty_end_time` datetime(3) DEFAULT NULL,
  `remaining_days_at_source` int DEFAULT NULL,
  `original_remaining_days_at_source` int DEFAULT NULL,
  `contract_type` text COLLATE utf8mb4_unicode_ci,
  `contract_type_name` text COLLATE utf8mb4_unicode_ci,
  `project_name` text COLLATE utf8mb4_unicode_ci,
  `customer_name` text COLLATE utf8mb4_unicode_ci,
  `final_customer_name` text COLLATE utf8mb4_unicode_ci,
  `agent_name` text COLLATE utf8mb4_unicode_ci,
  `office_code` text COLLATE utf8mb4_unicode_ci,
  `office_name` text COLLATE utf8mb4_unicode_ci,
  `market_code` text COLLATE utf8mb4_unicode_ci,
  `market_name` text COLLATE utf8mb4_unicode_ci,
  `system_code` text COLLATE utf8mb4_unicode_ci,
  `system_name` text COLLATE utf8mb4_unicode_ci,
  `secondary_sn` text COLLATE utf8mb4_unicode_ci,
  `secondary_item` text COLLATE utf8mb4_unicode_ci,
  `secondary_product_name` text COLLATE utf8mb4_unicode_ci,
  `secondary_product_description` text COLLATE utf8mb4_unicode_ci,
  `source_sync_time` datetime(3) DEFAULT NULL,
  `source_shipment_key` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_warranty_record_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_device_warranty_record_device` (`tenant_id`,`device_sn`,`warranty_start_date`,`id`),
  KEY `idx_ast_device_warranty_record_contract` (`tenant_id`,`warranty_contract_no`,`device_sn`),
  CONSTRAINT `fk_ast_device_warranty_record_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_warranty_record_dates` CHECK (((`warranty_end_date` is null) or (`warranty_start_date` is null) or (`warranty_end_date` >= `warranty_start_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备维保与续保记录';

CREATE TABLE `ast_device_warranty_registration` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `source_system` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
