CREATE TABLE `ast_device_warranty_renewal_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `device_sn` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号',
  `warranty_contract_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '续保合同号',
  `warranty_grade` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保等级编码',
  `warranty_start_date` date DEFAULT NULL COMMENT '实际开始日期',
  `warranty_end_date` date DEFAULT NULL COMMENT '实际结束日期',
  `warranty_months` int unsigned DEFAULT NULL COMMENT '参考月数，不据此重算实际日期',
  `extended` bit(1) DEFAULT NULL COMMENT '是否延保，NULL为未记录',
  `is_latest` bit(1) DEFAULT NULL COMMENT '原最新选择标记，不代表在保状态',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '续保备注',
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_renewal_device` (`tenant_id`,`device_sn`,`warranty_start_date`,`id`),
  KEY `idx_renewal_contract` (`tenant_id`,`warranty_contract_no`,`device_sn`),
  CONSTRAINT `ck_renewal_dates` CHECK (((`warranty_start_date` is null) or (`warranty_end_date` is null) or (`warranty_end_date` >= `warranty_start_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备续保记录';

