  `document_id` bigint DEFAULT NULL COMMENT '官方文档稳定引用',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `source_updated_at` datetime(3) DEFAULT NULL COMMENT '来源更新时间',
  `synced_at` datetime(3) DEFAULT NULL COMMENT '最近成功同步时间',
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_product_official_version_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_product_official_version_product` (`tenant_id`,`product_code`,`product_model`,`status`,`release_date`,`id`),
  KEY `idx_ast_product_official_version_conp` (`tenant_id`,`product_code`,`conp_version`,`id`),
  KEY `idx_ast_product_official_version_conp_parse` (`tenant_id`,`product_code`,`conp_type`,`conp_series`,`conp_mark`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST官网软件版本副本';

CREATE TABLE `ast_product_type` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` bit(1) NOT NULL DEFAULT b'1',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_updated_at` datetime(3) NOT NULL,
  `payload_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_sync_attempt_at` datetime(3) DEFAULT NULL,
  `synced_at` datetime(3) NOT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_product_type_tenant_code` (`tenant_id`,`type_code`),
  UNIQUE KEY `uk_ast_product_type_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_ast_product_type_tenant_id_code` (`tenant_id`,`id`,`type_code`),
  KEY `idx_ast_product_type_sync` (`tenant_id`,`sync_status`,`source_updated_at`,`id`),
  CONSTRAINT `chk_ast_product_type_code` CHECK ((`type_code` <> _utf8mb4'')),
  CONSTRAINT `chk_ast_product_type_name` CHECK ((`display_name` <> _utf8mb4'')),
  CONSTRAINT `chk_ast_product_type_sync_status` CHECK ((`sync_status` in (_utf8mb4'FRESH',_utf8mb4'STALE',_utf8mb4'FAILED',_utf8mb4'PENDING_MAPPING',_utf8mb4'NOT_AVAILABLE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ast_product_type_source_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_updated_at` datetime(3) NOT NULL,
  `payload_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_type_id` bigint DEFAULT NULL,
  `mapping_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `conflict_product_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conflict_source_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conflict_source_updated_at` datetime(3) DEFAULT NULL,
  `conflict_payload_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `synced_at` datetime(3) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_product_type_mapping_source` (`tenant_id`,`source_system`,`source_key`),
  UNIQUE KEY `uk_ast_product_type_mapping_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_ast_product_type_mapping_tenant_id_target` (`tenant_id`,`id`,`product_type_id`),
  KEY `idx_ast_product_type_mapping_target` (`tenant_id`,`product_type_id`,`id`),
  KEY `idx_ast_product_type_mapping_status` (`tenant_id`,`mapping_status`,`source_updated_at`,`id`),
  CONSTRAINT `fk_ast_product_type_mapping_target` FOREIGN KEY (`tenant_id`, `product_type_id`) REFERENCES `ast_product_type` (`tenant_id`, `id`),
  CONSTRAINT `chk_ast_product_type_mapping_conflict_evidence` CHECK ((((`mapping_status` = _utf8mb4'CONFLICT') and (`conflict_product_type_code` is not null) and (`conflict_source_version` is not null) and (`conflict_source_updated_at` is not null) and (`conflict_payload_hash` is not null)) or ((`mapping_status` <> _utf8mb4'CONFLICT') and (`conflict_product_type_code` is null) and (`conflict_source_version` is null) and (`conflict_source_updated_at` is null) and (`conflict_payload_hash` is null)))),
  CONSTRAINT `chk_ast_product_type_mapping_status` CHECK ((`mapping_status` in (_utf8mb4'RESOLVED',_utf8mb4'CONFLICT',_utf8mb4'UNRESOLVED'))),
  CONSTRAINT `chk_ast_product_type_mapping_target` CHECK ((((`mapping_status` = _utf8mb4'RESOLVED') and (`product_type_id` is not null)) or ((`mapping_status` = _utf8mb4'UNRESOLVED') and (`product_type_id` is null)) or (`mapping_status` = _utf8mb4'CONFLICT')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ast_site` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `code` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_id` bigint DEFAULT NULL,
  `address_id` bigint NOT NULL,
  `site_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint NOT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_site_code` (`tenant_id`,`code`,`deleted`),
  KEY `idx_ast_site_address` (`tenant_id`,`address_id`,`status`),
  KEY `idx_ast_site_customer` (`tenant_id`,`customer_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资产业务站点';

CREATE TABLE `ast_site_location` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `site_id` bigint NOT NULL,
  `parent_id` bigint DEFAULT NULL,
  `code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tree_path` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tree_depth` int unsigned NOT NULL DEFAULT '0',
  `tree_sort` int NOT NULL DEFAULT '0',
  `status` tinyint NOT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_site_location_code` (`tenant_id`,`site_id`,`code`,`deleted`),
  KEY `idx_ast_site_location_parent` (`tenant_id`,`site_id`,`parent_id`,`tree_sort`),
  KEY `idx_ast_site_location_path` (`tenant_id`,`site_id`,`tree_path`(255))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站点内部任意深度位置树';

CREATE TABLE `bpm_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类编号',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '分类名',
  `code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '分类标志',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '分类描述',
  `status` tinyint DEFAULT NULL COMMENT '分类状态',
  `sort` int DEFAULT NULL COMMENT '分类排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='BPM 流程分类';

CREATE TABLE `bpm_form` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
