CREATE TABLE `com_authority_candidate` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '权威候选编号',
  `tenant_id` bigint NOT NULL,
  `object_type` varchar(32) NOT NULL,
  `candidate_source_system` varchar(32) NOT NULL,
  `candidate_source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `candidate_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `candidate_payload` json NOT NULL,
  `evidence_reference` json NOT NULL,
  `candidate_status` varchar(32) NOT NULL,
  `matched_owner_type` varchar(32) DEFAULT NULL,
  `matched_owner_id` bigint DEFAULT NULL,
  `matched_owner_source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `decision_reason` varchar(512) DEFAULT NULL,
  `submitted_by` bigint NOT NULL,
  `submitted_at` datetime(3) NOT NULL,
  `decided_by` bigint DEFAULT NULL,
  `decided_at` datetime(3) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_authority_candidate_source` (`tenant_id`,`object_type`,`candidate_source_system`,`candidate_source_key`,`candidate_version`),
  CONSTRAINT `chk_authority_candidate_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_authority_candidate_object` CHECK ((`object_type` in (_utf8mb4'CONTRACT',_utf8mb4'SALES_ORDER',_utf8mb4'ORDER_LINE'))),
  CONSTRAINT `chk_authority_candidate_source` CHECK ((`candidate_source_system` = _utf8mb4'PLATFORM_MANUAL')),
  CONSTRAINT `chk_authority_candidate_status` CHECK ((`candidate_status` in (_utf8mb4'PENDING_RECONCILIATION',_utf8mb4'MATCHED',_utf8mb4'REJECTED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人工权威候选及对账历史';

CREATE TABLE `com_contract` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '合同编号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `company_id` bigint DEFAULT NULL COMMENT '签约公司ID',
  `company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '签约公司编码',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签约公司名称',
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同编号',
  `master_source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主档来源系统',
  `master_source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '主档来源记录键',
  `master_source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `contract_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同类型编码',
  `customer_id` bigint DEFAULT NULL COMMENT '客户ID',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编码',
  `customer_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `contract_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同名称',
  `contract_amount` decimal(20,2) DEFAULT NULL,
  `currency_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '币种编码',
  `currency_name` varchar(32) DEFAULT NULL COMMENT '币种名称',
  `contract_create_time` datetime(3) DEFAULT NULL COMMENT '合同创建时间',
  `authority_status` varchar(32) NOT NULL DEFAULT 'CONFIRMED',
  `source_lifecycle_status` varchar(32) DEFAULT NULL,
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `expiry_date` date DEFAULT NULL COMMENT '失效日期',
  `project_name` varchar(512) DEFAULT NULL COMMENT '项目名称',
  `project_code` varchar(80) DEFAULT NULL COMMENT '项目编码',
  `market_code` varchar(64) DEFAULT NULL COMMENT '市场部编码',
  `market_name` varchar(128) DEFAULT NULL COMMENT '市场部名称',
  `department_code` varchar(64) DEFAULT NULL COMMENT '办事处编码',
  `department_name` varchar(128) DEFAULT NULL COMMENT '办事处名称',
  `system_code` varchar(64) DEFAULT NULL COMMENT '系统部编码',
  `system_name` varchar(255) DEFAULT NULL COMMENT '系统部名称',
  `expend_code` varchar(64) DEFAULT NULL COMMENT '拓展部编码',
  `expend_name` varchar(255) DEFAULT NULL COMMENT '拓展部名称',
  `industry_code` varchar(64) DEFAULT NULL COMMENT '行业编码',
  `industry_name` varchar(128) DEFAULT NULL COMMENT '行业名称',
  `marketing_representative_code` varchar(64) DEFAULT NULL COMMENT '市场代表编码',
  `marketing_representative_name` varchar(128) DEFAULT NULL COMMENT '市场代表名称',
  `secondary_representative_code` varchar(64) DEFAULT NULL COMMENT '辅助代表编码',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `source_updated_at` datetime(3) DEFAULT NULL,
  `status` varchar(32) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_contract_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_contract_business` (`tenant_id`,`company_code`,`contract_no`),
  UNIQUE KEY `uk_contract_master_source` (`tenant_id`,`master_source_system`,`master_source_record_key`),
  KEY `idx_contract_company` (`tenant_id`,`company_id`,`status`,`contract_no`),
  KEY `idx_contract_customer` (`tenant_id`,`customer_id`,`status`),
  KEY `idx_contract_no` (`tenant_id`,`contract_no`,`company_code`),
  CONSTRAINT `chk_contract_authority_status` CHECK ((`authority_status` in (_utf8mb4'PENDING_AUTHORITY',_utf8mb4'CONFIRMED'))),
  CONSTRAINT `chk_contract_dates` CHECK (((`expiry_date` is null) or (`effective_date` is null) or (`expiry_date` >= `effective_date`))),
  CONSTRAINT `chk_contract_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_contract_source_lifecycle` CHECK ((`source_lifecycle_status` in (_utf8mb4'ACTIVE',_utf8mb4'CANCELLED',_utf8mb4'RETURNED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='合同主档';

CREATE TABLE `com_contract_collection_plan` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `contract_id` bigint DEFAULT NULL,
  `contract_no` varchar(64) DEFAULT NULL,
  `batch_code` varchar(32) DEFAULT NULL,
  `collection_item_name` varchar(64) DEFAULT NULL,
  `reference_event_name` varchar(64) DEFAULT NULL,
  `event_planned_at` datetime(3) DEFAULT NULL,
  `after_days` int DEFAULT NULL,
  `event_actual_finished_at` datetime(3) DEFAULT NULL,
  `marketing_feedback` varchar(2000) DEFAULT NULL,
  `data_source` varchar(25) DEFAULT NULL,
  `effective_from` datetime(3) DEFAULT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) DEFAULT NULL,
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) DEFAULT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_contract` (`tenant_id`,`contract_id`,`deleted`),
  KEY `idx_collection_plan_cache_contract` (`tenant_id`,`contract_no`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='合同回款计划';

CREATE TABLE `com_contract_receivable` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `contract_id` bigint DEFAULT NULL COMMENT '合同ID',
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同编号',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司编码',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `company_resolution_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司解析来源',
  `mapping_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_COMPANY' COMMENT '映射状态',
  `project_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `source_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源订单编号',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编码',
  `customer_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `contract_amount` decimal(20,2) NOT NULL COMMENT '合同金额',
  `delivered_amount` decimal(20,2) NOT NULL COMMENT '已发货金额',
  `collected_amount` decimal(20,2) NOT NULL COMMENT '已收金额',
  `collected_ratio` decimal(18,6) DEFAULT NULL COMMENT '已收比例',
  `receivable_amount` decimal(20,2) DEFAULT NULL COMMENT '应收金额',
  `overdue_amount` decimal(20,2) DEFAULT NULL COMMENT '逾期金额',
  `currency_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '币种名称',
  `market_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场部编码',
  `market_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场部名称',
  `department_id` bigint DEFAULT NULL COMMENT '办事处ID',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `department_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处名称',
  `industry_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业名称',
  `marketing_representative_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场代表名称',
  `source_batch_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源批次编码',
  `import_batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导入批次编号',
  `project_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目编码',
  `system_source_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部来源键',
  `system_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部编码',
  `system_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部名称',
  `industry_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业编码',
  `expend_source_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拓展部来源键',
  `expend_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拓展部编码',
  `expend_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拓展部名称',
  `marketing_representative_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场代表编码',
  `secondary_representative_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '辅助代表编码',
  `original_division_values` json DEFAULT NULL COMMENT '创建时行业划分原值JSON',
  `source_effective_from` datetime(3) DEFAULT NULL COMMENT '来源生效开始时间',
  `source_effective_to` datetime(3) DEFAULT NULL COMMENT '来源生效结束时间',
  `contract_create_time` datetime(3) DEFAULT NULL COMMENT '合同创建时间',
  `latest_ship_time` datetime(3) DEFAULT NULL COMMENT '最近发货时间',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源记录稳定唯一键',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_contract_receivable_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_contract_receivable_source` (`tenant_id`,`source_system`,`source_record_key`),
  KEY `idx_contract_receivable_business` (`tenant_id`,`contract_no`,`company_code`,`mapping_status`),
  KEY `idx_contract_receivable_contract` (`tenant_id`,`contract_id`,`source_sync_time`),
  KEY `idx_contract_receivable_company` (`tenant_id`,`company_id`,`mapping_status`,`contract_id`),
  CONSTRAINT `fk_contract_receivable_contract` FOREIGN KEY (`tenant_id`, `contract_id`) REFERENCES `com_contract` (`tenant_id`, `id`),
  CONSTRAINT `chk_contract_receivable_dates` CHECK (((`source_effective_to` is null) or (`source_effective_from` is null) or (`source_effective_to` >= `source_effective_from`))),
  CONSTRAINT `chk_contract_receivable_deleted` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SAP合同回款来源记录，保留公司待解析和一号多行证据';

CREATE TABLE `com_crm_execution_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '执行单编号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `source_system` varchar(32) NOT NULL DEFAULT 'CRM' COMMENT '来源系统',
  `execution_no` varchar(255) NOT NULL COMMENT '执行单编号',
  `project_code` varchar(255) DEFAULT NULL COMMENT '项目编码',
  `project_name` varchar(1024) DEFAULT NULL COMMENT '项目名称',
  `primary_project_id` bigint DEFAULT NULL COMMENT '主项目ID',
  `sales_rep_code` varchar(64) DEFAULT NULL COMMENT '销售代表编码',
  `sales_rep_name` varchar(128) DEFAULT NULL COMMENT '销售代表名称',
  `sales_rep_phone` varchar(300) DEFAULT NULL COMMENT '销售代表电话',
  `market_code` varchar(64) DEFAULT NULL COMMENT '市场部编码',
  `market_name` varchar(255) DEFAULT NULL COMMENT '市场部名称',
  `system_source_key` varchar(64) DEFAULT NULL COMMENT '系统部来源键',
  `system_code` varchar(64) DEFAULT NULL COMMENT '系统部编码',
  `system_name` varchar(255) DEFAULT NULL COMMENT '系统部名称',
  `expend_source_key` varchar(64) DEFAULT NULL COMMENT '拓展部来源键',
  `expend_code` varchar(64) DEFAULT NULL COMMENT '拓展部编码',
  `expend_name` varchar(255) DEFAULT NULL COMMENT '拓展部名称',
  `industry_code` varchar(64) DEFAULT NULL COMMENT '行业编码',
  `industry_name` varchar(255) DEFAULT NULL COMMENT '行业名称',
  `department_id` bigint DEFAULT NULL COMMENT '办事处ID',
  `department_code` varchar(64) DEFAULT NULL COMMENT '办事处编码',
  `department_name` varchar(128) DEFAULT NULL COMMENT '办事处名称',
  `service_type_name` varchar(128) DEFAULT NULL COMMENT '服务类型名称',
  `channel_name` varchar(1024) DEFAULT NULL COMMENT '渠道名称',
  `engineering_fee_raw` varchar(64) DEFAULT NULL COMMENT '工程费用原始',
  `engineering_fee` decimal(20,4) DEFAULT NULL COMMENT '工程费用',
  `source_object_id` varchar(64) DEFAULT NULL COMMENT '来源对象ID',
  `apply_type` varchar(64) DEFAULT NULL COMMENT '申请类型编码',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `company_code` varchar(64) DEFAULT NULL COMMENT '公司编码',
  `company_name` varchar(255) DEFAULT NULL COMMENT '公司名称',
  `customer_project_name` varchar(1024) DEFAULT NULL COMMENT '客户项目名称',
  `final_customer_name` varchar(1024) DEFAULT NULL COMMENT '最终客户名称',
  `agent_name` varchar(1024) DEFAULT NULL COMMENT '代理商名称',
  `project_manager_code` varchar(1024) DEFAULT NULL COMMENT '项目负责人编码',
  `project_manager_name` varchar(512) DEFAULT NULL COMMENT '项目负责人名称',
  `decision_path` varchar(1024) DEFAULT NULL COMMENT '决策路径',
  `required_in_date` date DEFAULT NULL COMMENT '要求入场日期',
  `receiver_name` varchar(512) DEFAULT NULL COMMENT '收件人名称',
  `receiver_contact` varchar(300) DEFAULT NULL COMMENT '收件人联系人',
  `receiver_address` varchar(1024) DEFAULT NULL COMMENT '收件人地址',
  `loan_reason` text COMMENT '借用原因',
  `project_type` varchar(32) DEFAULT NULL COMMENT '项目类型编码',
  `major_project_level` varchar(255) DEFAULT NULL COMMENT '重大项目级别',
  `project_amount` decimal(20,4) DEFAULT NULL COMMENT '项目金额',
  `af_project_amount` decimal(20,4) DEFAULT NULL COMMENT '安服项目金额',
  `submit_time` datetime(3) DEFAULT NULL COMMENT '提交时间',
  `predicted_bid_time` datetime(3) DEFAULT NULL COMMENT '预计中标时间',
  `contact_name` varchar(255) DEFAULT NULL COMMENT '联系人名称',
  `contact_phone` varchar(128) DEFAULT NULL COMMENT '联系人电话',
  `af_evidence_status` varchar(32) NOT NULL DEFAULT 'UNKNOWN' COMMENT '安服证据状态：CONFIRMED已确认，UNKNOWN未知',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `status` varchar(32) NOT NULL COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_crm_execution_order_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_crm_execution` (`tenant_id`,`source_system`,`execution_no`),
  KEY `idx_crm_execution_project` (`tenant_id`,`primary_project_id`,`status`),
  KEY `idx_crm_execution_source_project` (`tenant_id`,`project_code`,`execution_no`),
  KEY `idx_crm_execution_company_office` (`tenant_id`,`company_id`,`department_id`,`status`,`id`),
  KEY `idx_crm_execution_company_office_code` (`tenant_id`,`company_code`,`department_code`,`status`,`id`),
  CONSTRAINT `chk_crm_execution_deleted` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM执行单辅助主档，安服仅保存正向证据';

CREATE TABLE `com_delivery_scope` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '交付范围编号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `project_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目编码',
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `project_company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目公司编码',
  `project_company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目公司名称',
  `project_department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目部门编码',
  `project_department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目部门名称',
  `project_customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目客户编码',
  `project_customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目客户名称',
  `project_manager_employee_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目负责人工号',
  `project_manager_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目负责人姓名',
  `order_line_id` bigint NOT NULL COMMENT '订单行ID',
  `current_order_line_id` bigint GENERATED ALWAYS AS ((case when ((`allocation_confirmed` = 0x01) and (`deleted` = 0) and (`effective_to` is null)) then `order_line_id` else NULL end)) STORED,
  `order_source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单来源系统编码',
  `order_company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单公司编码',
  `order_company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单公司名称',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单类型编码',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `line_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单行号',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码/物料编码（订单行）',
  `product_desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品描述/物料描述',
  `allocated_qty` decimal(18,6) NOT NULL COMMENT '实施数量',
  `scope_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实施范围状态',
  `allocation_version` bigint NOT NULL,
  `allocation_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分配来源',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更原因',
  `department_id` bigint NOT NULL COMMENT '办事处ID',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处名称',
  `department_version` int unsigned DEFAULT NULL COMMENT '办事处版本',
  `source_evidence` varchar(255) DEFAULT NULL,
  `effective_from` datetime(3) NOT NULL COMMENT '生效开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '生效结束时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  `allocation_confirmed` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否确认占用订单分配数量',
  `delivered_quantity` decimal(18,6) DEFAULT NULL COMMENT '项目范围原已发货数量',
  `open_quantity` decimal(18,6) DEFAULT NULL COMMENT '项目范围原订单未交数量',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_order_line_scope_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_scope_current` (`tenant_id`,`project_id`,`current_order_line_id`),
  UNIQUE KEY `uk_scope_version` (`tenant_id`,((case when (`allocation_confirmed` = 0x01) then `order_line_id` else NULL end)),`project_id`,`allocation_version`),
  KEY `idx_scope_order_line` (`tenant_id`,`order_line_id`,`scope_status`,`project_id`),
  KEY `idx_scope_project` (`tenant_id`,`project_id`,`scope_status`,`order_line_id`),
  KEY `idx_scope_acceptance_lock` (`tenant_id`,`project_id`,`effective_to`,`id`),
  KEY `idx_scope_product` (`tenant_id`,`product_code`,`scope_status`,`project_id`),
  CONSTRAINT `chk_scope_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_scope_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_scope_quantity` CHECK ((`allocated_qty` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目对ERP订单行的权威实施范围';

CREATE TABLE `com_delivery_scope_detail` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `delivery_scope_id` bigint NOT NULL COMMENT '交付范围主ID',
  `detail_sequence` int unsigned NOT NULL COMMENT '交付范围明细序号',
  `serial_no` varchar(128) DEFAULT NULL,
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称快照',
  `device_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型编码',
  `device_type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型名称快照',
  `delivery_batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '交付批次编号',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '明细来源记录稳定键',
  `allocated_qty` decimal(18,6) NOT NULL COMMENT '分配数量',
  `detail_status` varchar(32) NOT NULL,
  `source_snapshot` json DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '交付范围明细备注',
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_delivery_scope_detail_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_delivery_scope_detail_sequence` (`tenant_id`,`delivery_scope_id`,`detail_sequence`),
  KEY `idx_delivery_scope_detail_product` (`tenant_id`,`product_code`,`device_type_code`,`delivery_scope_id`),
  KEY `idx_delivery_scope_detail_serial` (`tenant_id`,`serial_no`,`delivery_scope_id`),
  CONSTRAINT `fk_delivery_scope_detail_scope` FOREIGN KEY (`tenant_id`, `delivery_scope_id`) REFERENCES `com_delivery_scope` (`tenant_id`, `id`),
  CONSTRAINT `chk_delivery_scope_detail_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_delivery_scope_detail_quantity` CHECK ((`allocated_qty` > 0)),
  CONSTRAINT `chk_delivery_scope_detail_subject` CHECK (((`serial_no` is not null) or (`product_code` is not null) or (`device_type_code` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付范围主体明细';

CREATE TABLE `com_delivery_scope_project_version` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `scope_version` bigint unsigned NOT NULL,
  `payload_version` int unsigned NOT NULL,
  `last_change_type` varchar(32) NOT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_scope_project_version` (`tenant_id`,`project_id`),
  CONSTRAINT `chk_scope_project_version_deleted` CHECK ((`deleted` = 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目交付范围版本水位';

CREATE TABLE `com_order_contract_relation` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint NOT NULL COMMENT '订单ID',
  `contract_id` bigint NOT NULL COMMENT '合同ID',
  `relation_role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RELATED' COMMENT '关系角色编码',
  `relation_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系来源',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `sales_order_source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `contract_source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_evidence` json NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_contract_rel_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_order_contract` (`tenant_id`,`order_id`,`contract_id`,`relation_role`),
  UNIQUE KEY `uk_order_contract_source_pair` (`tenant_id`,`source_system`,`sales_order_source_key`,`contract_source_key`),
  KEY `idx_order_contract_reverse` (`tenant_id`,`contract_id`,`order_id`),
  CONSTRAINT `fk_order_contract_contract` FOREIGN KEY (`tenant_id`, `contract_id`) REFERENCES `com_contract` (`tenant_id`, `id`),
  CONSTRAINT `fk_order_contract_order` FOREIGN KEY (`tenant_id`, `order_id`) REFERENCES `com_sales_order` (`tenant_id`, `id`),
  CONSTRAINT `chk_order_contract_dates` CHECK (((`effective_to` is null) or (`effective_to` > `effective_from`))),
  CONSTRAINT `chk_order_contract_deleted` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售订单与合同关系';

CREATE TABLE `com_outbox_event` (
  `id` bigint NOT NULL,
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `aggregate_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `aggregate_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_version` bigint NOT NULL,
  `payload` json NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `occurred_at` datetime NOT NULL,
  `retry_count` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_com_outbox_event` (`tenant_id`,`event_id`),
  KEY `idx_com_outbox_dispatch` (`tenant_id`,`status`,`occurred_at`,`id`),
  CONSTRAINT `ck_com_outbox_status` CHECK ((`status` in (_utf8mb4'PENDING',_utf8mb4'PUBLISHED',_utf8mb4'FAILED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商务域事务Outbox';

CREATE TABLE `com_project_contract_relation` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `contract_id` bigint DEFAULT NULL COMMENT '合同ID',
  `contract_no` varchar(64) DEFAULT NULL COMMENT '原始合同号',
  `relation_role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RELATED' COMMENT '关系角色编码',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_table` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源系统物理表名',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源记录稳定唯一键',
  `effective_from` datetime(3) DEFAULT NULL COMMENT '生效开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '生效结束时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_contract_rel_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_project_contract` (`tenant_id`,`project_id`,`contract_id`,`relation_role`),
  KEY `idx_project_contract_reverse` (`tenant_id`,`contract_id`,`project_id`),
  CONSTRAINT `fk_project_contract_contract` FOREIGN KEY (`tenant_id`, `contract_id`) REFERENCES `com_contract` (`tenant_id`, `id`),
  CONSTRAINT `chk_project_contract_dates` CHECK (((`effective_to` is null) or (`effective_from` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_project_contract_deleted` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目与合同直接关系';

CREATE TABLE `com_sales_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '销售订单编号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公司编码',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单类型编码',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `sales_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '销售类型编码',
  `contract_no` varchar(64) DEFAULT NULL COMMENT '主合同号(快照来源订单头contractNo,对应合同主档业务键)',
  `execution_no` varchar(64) DEFAULT NULL COMMENT '主执行单号(快照来源订单头orderExecNumber)',
  `customer_id` bigint DEFAULT NULL COMMENT '客户ID',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编码',
  `customer_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `source_project_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源项目名称',
  `order_comment` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单说明',
  `order_amount` decimal(20,2) DEFAULT NULL,
  `currency_code` varchar(32) DEFAULT NULL,
  `authority_status` varchar(32) NOT NULL DEFAULT 'CONFIRMED',
  `source_lifecycle_status` varchar(32) NOT NULL DEFAULT 'ACTIVE',
  `order_create_time` datetime(3) DEFAULT NULL COMMENT '订单创建时间',
  `customer_required_time` datetime(3) DEFAULT NULL COMMENT '客户要求时间',
  `custom_info` json DEFAULT NULL COMMENT '来源customInfo原样同步',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `source_updated_at` datetime(3) DEFAULT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sales_order_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_sales_order_business` (`tenant_id`,`source_system`,`company_code`,`order_type`,`order_no`),
  UNIQUE KEY `uk_sales_order_source` (`tenant_id`,`source_system`,`source_record_key`),
  KEY `idx_sales_order_company` (`tenant_id`,`company_id`,`status`,`order_no`),
  KEY `idx_sales_order_customer` (`tenant_id`,`customer_code`,`status`),
  KEY `idx_sales_order_no` (`tenant_id`,`order_no`),
  KEY `idx_sales_order_time` (`tenant_id`,`order_create_time`,`status`),
  KEY `idx_sales_order_contract` (`tenant_id`,`contract_no`),
  KEY `idx_sales_order_execution` (`tenant_id`,`execution_no`),
  CONSTRAINT `chk_sales_order_authority_status` CHECK ((`authority_status` in (_utf8mb4'PENDING_AUTHORITY',_utf8mb4'CONFIRMED'))),
  CONSTRAINT `chk_sales_order_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_sales_order_source_lifecycle` CHECK ((`source_lifecycle_status` in (_utf8mb4'ACTIVE',_utf8mb4'CANCELLED',_utf8mb4'RETURNED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ERP销售订单主档';

CREATE TABLE `com_sales_order_line` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint DEFAULT NULL COMMENT '订单ID',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '父订单来源系统',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `company_id` bigint DEFAULT NULL COMMENT '父订单所属公司主档ID',
  `company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公司编码',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '父订单类型编码',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '父订单编号',
  `line_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行编号',
  `line_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行类型编码',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码/物料编码（ERP订单行）',
  `product_model` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品型号/物料型号（原model_code）',
  `product_desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品描述/物料描述（原item_desc）',
  `custom_info` json DEFAULT NULL COMMENT '来源customInfo原样同步',
  `product_id` bigint DEFAULT NULL COMMENT '产品ID',
  `bundle_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '套件编码',
  `profit_center` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '利润中心',
  `real_execution_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际执行单编号',
  `warranty_month` int DEFAULT NULL COMMENT '质保期限月数',
  `customer_id` bigint DEFAULT NULL COMMENT '父订单客户主档ID',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编码',
  `customer_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `order_qty` decimal(18,6) DEFAULT NULL COMMENT 'ERP订单行下单数量',
  `open_qty` decimal(18,6) DEFAULT NULL COMMENT 'ERP订单行当前未执行数量',
  `delivered_qty` decimal(18,6) DEFAULT NULL COMMENT 'ERP订单行当前累计发货数量',
  `unit_code` varchar(32) DEFAULT NULL,
  `unit_scale` tinyint unsigned NOT NULL,
  `quantity_status` varchar(32) NOT NULL,
  `source_lifecycle_status` varchar(32) NOT NULL DEFAULT 'ACTIVE',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `source_updated_at` datetime(3) DEFAULT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sales_order_line_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_sales_order_line_source` (`tenant_id`,`source_system`,`source_record_key`),
  UNIQUE KEY `uk_sales_order_line_business` (`tenant_id`,`source_system`,`company_code`,`line_type`,`order_no`,`line_no`),
  KEY `idx_sales_order_line_business` (`tenant_id`,`source_system`,`company_code`,`order_type`,`order_no`,`line_no`),
  KEY `idx_sales_order_line_customer` (`tenant_id`,`customer_code`,`status`,`id`),
  KEY `idx_sales_order_line_profit` (`tenant_id`,`profit_center`,`order_id`),
  KEY `idx_sales_order_line_product` (`tenant_id`,`product_code`),
  KEY `idx_sales_order_line_parent` (`tenant_id`,`order_id`),
  KEY `idx_sales_order_line_sync_lookup` (`tenant_id`,`order_no`,`line_no`,`product_code`),
  CONSTRAINT `fk_sales_order_line_order` FOREIGN KEY (`tenant_id`, `order_id`) REFERENCES `com_sales_order` (`tenant_id`, `id`),
  CONSTRAINT `chk_sales_order_line_authority` CHECK (((`quantity_status` <> _utf8mb4'CONFIRMED') or (`order_qty` is not null))),
  CONSTRAINT `chk_sales_order_line_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_sales_order_line_known_unit` CHECK (((`quantity_status` = _utf8mb4'PENDING_AUTHORITY') or (`unit_code` is not null))),
  CONSTRAINT `chk_sales_order_line_quantity_scale` CHECK ((((`order_qty` is null) or (round(`order_qty`,`unit_scale`) = `order_qty`)) and ((`open_qty` is null) or (round(`open_qty`,`unit_scale`) = `open_qty`)) and ((`delivered_qty` is null) or (round(`delivered_qty`,`unit_scale`) = `delivered_qty`)))),
  CONSTRAINT `chk_sales_order_line_source_lifecycle` CHECK ((`source_lifecycle_status` in (_utf8mb4'ACTIVE',_utf8mb4'CANCELLED',_utf8mb4'RETURNED'))),
  CONSTRAINT `chk_sales_order_line_unit_scale` CHECK ((`unit_scale` between 0 and 6))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ERP销售订单行及数量快照';

CREATE TABLE `com_shipment_contract_reference` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `contract_id` bigint DEFAULT NULL COMMENT '合同ID',
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `company_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司编码',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `department_id` bigint DEFAULT NULL COMMENT '办事处ID',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `department_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处名称',
  `contract_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同类型编码',
  `customer_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `project_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `market_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场部编码',
  `market_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场部名称',
  `system_source_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部来源键',
  `system_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部编码',
  `system_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部名称',
  `warranty_flag` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '质保标志：0否，1是',
  `remark` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `mapping_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_MAPPING' COMMENT '映射状态',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源记录稳定唯一键',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  `warranty_years` int DEFAULT NULL COMMENT '合同保修年数，原空白或NULL表示未知；不代表当前保修状态',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shipment_contract_ref_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_shipment_contract_ref_source` (`tenant_id`,`source_system`,`source_record_key`),
  KEY `idx_shipment_contract_ref_no` (`tenant_id`,`contract_no`,`company_code`,`mapping_status`),
  KEY `idx_shipment_contract_ref_contract` (`tenant_id`,`contract_id`,`mapping_status`),
  KEY `idx_shipment_contract_ref_company` (`tenant_id`,`company_id`,`mapping_status`,`contract_id`),
  CONSTRAINT `fk_shipment_contract_ref_contract` FOREIGN KEY (`tenant_id`, `contract_id`) REFERENCES `com_contract` (`tenant_id`, `id`),
  CONSTRAINT `chk_shipment_contract_ref_deleted` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='发货记录的合同归属，不作为合同主档';

CREATE TABLE `com_shipment_package` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `shipment_contract_ref_id` bigint DEFAULT NULL COMMENT '发货合同归属ID',
  `package_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '装箱单编号',
  `shipment_time` datetime(3) DEFAULT NULL COMMENT '发货时间',
  `warranty_start_time` datetime(3) DEFAULT NULL COMMENT '质保开始时间',
  `warranty_end_time` datetime(3) DEFAULT NULL COMMENT '质保结束时间',
  `receiver_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收件人名称',
  `express_no` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快递编号',
  `carrier_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承运商名称',
  `mapping_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_MAPPING' COMMENT '映射状态',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源记录稳定唯一键',
  `source_sync_time` datetime(3) DEFAULT NULL COMMENT '来源同步时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  `carrier_code` varchar(256) DEFAULT NULL,
  `shipment_contract_source_key` varchar(128) DEFAULT NULL COMMENT '原fb_shipment.con_id，保留精确父来源身份',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shipment_package_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_shipment_package_source` (`tenant_id`,`source_system`,`source_record_key`),
  UNIQUE KEY `uk_shipment_package_no` (`tenant_id`,`source_system`,`package_no`),
  KEY `idx_shipment_package_contract_ref` (`tenant_id`,`shipment_contract_ref_id`,`shipment_time`),
  CONSTRAINT `fk_shipment_package_contract_ref` FOREIGN KEY (`tenant_id`, `shipment_contract_ref_id`) REFERENCES `com_shipment_contract_reference` (`tenant_id`, `id`),
  CONSTRAINT `chk_shipment_package_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_shipment_package_warranty_dates` CHECK (((`warranty_end_time` is null) or (`warranty_start_time` is null) or (`warranty_end_time` >= `warranty_start_time`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='发货装箱单主档';

CREATE TABLE `cus_contact_history` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_contact_id` bigint NOT NULL,
  `project_relation_id` bigint DEFAULT NULL,
  `project_id` bigint DEFAULT NULL,
  `action_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `before_values` json DEFAULT NULL,
  `after_values` json DEFAULT NULL,
  `actor_user_id` bigint NOT NULL,
  `occurred_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cus_contact_history_master` (`tenant_id`,`customer_contact_id`,`id`),
  KEY `idx_cus_contact_history_project` (`tenant_id`,`project_id`,`project_relation_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `cus_customer_contact` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户联系人编号',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `department` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `primary_flag` bit(1) NOT NULL DEFAULT b'0',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `active_primary_customer_id` bigint GENERATED ALWAYS AS ((case when ((`deleted` = 0x00) and (`status` = 0) and (`primary_flag` = 0x01)) then `customer_id` else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_contact_primary` (`tenant_id`,`active_primary_customer_id`),
  KEY `idx_cus_contact_customer` (`tenant_id`,`customer_id`,`id`),
  CONSTRAINT `ck_cus_contact_status` CHECK ((`status` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `cus_customer_external_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '映射编号',
  `customer_id` bigint NOT NULL COMMENT '客户编号',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `effective_from` datetime NOT NULL COMMENT '生效时间',
  `effective_to` datetime DEFAULT NULL COMMENT '失效时间',
  `current_marker` tinyint GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0x00)) then 1 else NULL end)) STORED,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_customer_mapping_current_source` (`tenant_id`,`source_system`,`source_key`,`current_marker`),
  KEY `idx_cus_customer_mapping_customer` (`tenant_id`,`customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUS客户外部映射';

CREATE TABLE `cus_customer_field_history` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL,
  `field_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_owner` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `before_value_digest` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `after_value_digest` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `operator_id` bigint DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cus_customer_field_history_customer` (`tenant_id`,`customer_id`,`occurred_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUS客户字段历史';

CREATE TABLE `cus_customer_location_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL,
  `location_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_id` bigint NOT NULL,
  `source_version` int NOT NULL,
  `effective_from` datetime NOT NULL,
  `effective_to` datetime DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cus_customer_location_customer` (`tenant_id`,`customer_id`,`effective_to`),
  KEY `idx_cus_customer_location_target` (`tenant_id`,`location_type`,`location_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUS客户地点引用';

CREATE TABLE `cus_customer_master` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户主数据编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户内稳定客户编码',
  `erp_customer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM ERP客户编码',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户名称',
  `short_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户简称',
  `customer_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户级别字典值',
  `lifecycle_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT '生命周期状态',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_APPLICABLE' COMMENT '同步状态',
  `data_as_of` datetime NOT NULL COMMENT '数据截止时间',
  `reconciliation_pending` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否待对账',
  `temporary_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '临时客户原因',
  `contact_phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM联系电话副本',
  `contact_email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM邮箱副本',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属办事处统一部门编码',
  `department_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属办事处部门名称快照',
  `market_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场部编码',
  `market_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市场部名称',
  `system_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部编码',
  `system_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统部名称',
  `expend_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拓展部编码',
  `expend_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拓展部名称',
  `industry_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '子行业编码',
  `industry_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '子行业名称',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户地址快照（保存Address/Site地点引用时组装；无引用时为pms_customer.address遗留文本）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_customer_master_tenant_code` (`tenant_id`,`code`),
  KEY `idx_cus_customer_master_tenant_name` (`tenant_id`,`name`),
  KEY `idx_cus_customer_master_tenant_status` (`tenant_id`,`lifecycle_status`),
  KEY `idx_cus_customer_master_department` (`tenant_id`,`department_code`),
  KEY `idx_cus_customer_master_classification` (`tenant_id`,`market_code`,`system_code`,`expend_code`,`industry_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUS客户主档';

CREATE TABLE `cus_customer_scope_slice` (
  `id` bigint NOT NULL,
  `subject_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_id` bigint NOT NULL,
  `department_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `department_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `market_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `market_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `system_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `system_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `expend_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `expend_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `industry_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `industry_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `effective_from` datetime NOT NULL,
  `effective_to` datetime DEFAULT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cus_customer_scope_subject` (`tenant_id`,`subject_type`,`subject_id`,`status`,`effective_from`,`effective_to`),
  CONSTRAINT `ck_cus_customer_scope_department_mode` CHECK ((`department_mode` in (_utf8mb4'ALL',_utf8mb4'SELECTED',_utf8mb4'NONE'))),
  CONSTRAINT `ck_cus_customer_scope_expend_mode` CHECK ((`expend_mode` in (_utf8mb4'ALL',_utf8mb4'SELECTED',_utf8mb4'NONE'))),
  CONSTRAINT `ck_cus_customer_scope_industry_mode` CHECK ((`industry_mode` in (_utf8mb4'ALL',_utf8mb4'SELECTED',_utf8mb4'NONE'))),
  CONSTRAINT `ck_cus_customer_scope_interval` CHECK (((`effective_to` is null) or (`effective_to` > `effective_from`))),
  CONSTRAINT `ck_cus_customer_scope_market_mode` CHECK ((`market_mode` in (_utf8mb4'ALL',_utf8mb4'SELECTED',_utf8mb4'NONE'))),
  CONSTRAINT `ck_cus_customer_scope_subject` CHECK ((`subject_type` in (_utf8mb4'USER',_utf8mb4'ROLE'))),
  CONSTRAINT `ck_cus_customer_scope_system_mode` CHECK ((`system_mode` in (_utf8mb4'ALL',_utf8mb4'SELECTED',_utf8mb4'NONE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUS客户复选权限切片';

CREATE TABLE `cus_customer_service_level` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL COMMENT '客户编号',
  `level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务等级 STRATEGIC 战略 / IMPORTANT 重要 / STANDARD 标准 / GENERAL 一般',
  `valid_from` date DEFAULT NULL COMMENT '生效开始日期',
  `valid_to` date DEFAULT NULL COMMENT '生效结束日期',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已生效 2已停用 3已归档',
  `response_time_hours` int DEFAULT NULL COMMENT '响应时间（小时）',
  `proactive_service` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否主动服务',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_service_level_customer` (`customer_id`),
  KEY `idx_pms_service_level_status` (`customer_id`,`status`),
  KEY `idx_pms_service_level_level` (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS客户服务等级';

CREATE TABLE `cus_inspection_history` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `customer_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `task_id` bigint NOT NULL,
  `task_version` bigint NOT NULL,
  `task_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_name` varchar(282) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `report_id` bigint NOT NULL,
  `source_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `archived_by` bigint NOT NULL,
  `archived_at` datetime(3) NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_inspection_history_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cus_inspection_task` (`tenant_id`,`task_id`),
  KEY `idx_cus_inspection_history` (`tenant_id`,`customer_id`,`project_id`,`id`),
  CONSTRAINT `ck_cus_inspection_source` CHECK (((`task_id` > 0) and (`task_version` > 0) and (`report_id` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `cus_inspection_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `history_id` bigint NOT NULL,
  `reference_kind` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_id` bigint NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_inspection_reference_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cus_inspection_reference` (`tenant_id`,`history_id`,`reference_kind`,`source_id`),
  CONSTRAINT `fk_cus_inspection_history` FOREIGN KEY (`tenant_id`, `history_id`) REFERENCES `cus_inspection_history` (`tenant_id`, `id`),
  CONSTRAINT `ck_cus_inspection_reference_id` CHECK ((`source_id` > 0)),
  CONSTRAINT `ck_cus_inspection_reference_kind` CHECK ((`reference_kind` in (_utf8mb4'DEVICE',_utf8mb4'EXECUTION',_utf8mb4'RESULT',_utf8mb4'REPORT',_utf8mb4'ANNOTATION',_utf8mb4'ISSUE',_utf8mb4'REMEDIATION',_utf8mb4'EVIDENCE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `cus_market_relation` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `market_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市场部编码',
  `market_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市场部名称',
  `system_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '系统部编码',
  `system_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '系统部名称',
  `expend_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '拓展部编码',
  `expend_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '拓展部名称',
  `industry_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行业编码',
  `industry_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行业名称',
  `mapping_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_as_of` datetime NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_market_relation_codes` (`tenant_id`,`market_code`,`system_code`,`expend_code`,`industry_code`),
  KEY `idx_cus_market_relation_market` (`tenant_id`,`market_code`,`mapping_status`),
  KEY `idx_cus_market_relation_system` (`tenant_id`,`market_code`,`system_code`,`mapping_status`),
  KEY `idx_cus_market_relation_expend` (`tenant_id`,`market_code`,`system_code`,`expend_code`,`mapping_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUS市场行业四级组合目录';

CREATE TABLE `cus_project_customer_contact_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL,
  `customer_id` bigint DEFAULT NULL,
  `customer_contact_id` bigint DEFAULT NULL,
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `department` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_flag` bit(1) NOT NULL DEFAULT b'0',
  `primary_set_time` datetime DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '0',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_by` bigint DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `active_primary_project_id` bigint GENERATED ALWAYS AS ((case when ((`deleted` = 0x00) and (`status` = 0) and (`primary_flag` = 0x01)) then `project_id` else NULL end)) STORED,
  `project_party_id` bigint DEFAULT NULL COMMENT '联系人所属的项目最终客户相关方',
  `contact_code` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人业务编码',
  `registration_source` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登记来源：1项目信息、2手工成员',
  `effective_from` datetime(3) DEFAULT NULL COMMENT '联系人区间开始',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '联系人区间结束',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cus_project_contact_source` (`tenant_id`,`project_id`,`customer_contact_id`),
  UNIQUE KEY `uk_cus_project_contact_primary` (`tenant_id`,`active_primary_project_id`),
  KEY `idx_cus_project_contact_customer` (`tenant_id`,`customer_id`,`id`),
  CONSTRAINT `ck_cus_project_contact_status` CHECK ((`status` in (0,1))),
  CONSTRAINT `ck_cus_project_contact_affiliation` CHECK ((((`customer_id` is not null) and (`customer_contact_id` is not null)) or ((`customer_id` is null) and (`customer_contact_id` is null) and (`project_party_id` is not null) and (`primary_flag` = 0x00)))),
  CONSTRAINT `ck_cus_project_contact_interval` CHECK (((`effective_from` is null) or (`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `cut_approval_instance` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `plan_revision_id` bigint NOT NULL,
  `plan_revision_no` int NOT NULL,
  `assessment_id` bigint NOT NULL,
  `assessment_version` int NOT NULL,
  `checklist_id` bigint DEFAULT NULL,
  `checklist_version` int DEFAULT NULL,
  `grade_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `initiator_user_id` bigint NOT NULL,
  `initiator_project_scope_version` bigint NOT NULL,
  `source_snapshot_version` int NOT NULL,
  `source_snapshot` json DEFAULT NULL COMMENT '旧审批提交来源事实原件；新业务写入NULL，禁止更改历史原值',
  `route_snapshot` json DEFAULT NULL COMMENT '旧审批路由原件；新业务写入NULL，禁止更改历史原值',
  `lead_time_enabled_flag` bit(1) NOT NULL,
  `lead_time_snapshot` json DEFAULT NULL COMMENT '旧提前时间规则及计算事实原件；新业务写入NULL，禁止更改历史原值',
  `status_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hold_reason_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_node_no` int DEFAULT NULL,
  `previous_approval_instance_id` bigint DEFAULT NULL,
  `replacement_approval_instance_id` bigint DEFAULT NULL,
  `decide_time` datetime(3) DEFAULT NULL,
  `rejection_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `source_task_version` bigint DEFAULT NULL COMMENT '提交时任务版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `source_plan_version` bigint DEFAULT NULL COMMENT '提交时方案并发版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `source_cutover_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当时割接类型；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `source_network_mode_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当时组网模式',
  `source_schedule_time` datetime(3) DEFAULT NULL COMMENT '当时计划时间；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `lead_rule_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '提前时间规则版本',
  `lead_timezone_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '提前时间计算时区',
  `lead_plan_submit_time` datetime(3) DEFAULT NULL COMMENT '方案提交时间',
  `lead_required_days` int DEFAULT NULL COMMENT '原规则所需自然日数',
  `lead_actual_natural_days` int DEFAULT NULL COMMENT '原实际自然日数',
  `lead_late_submission_flag` bit(1) DEFAULT NULL COMMENT '原提前时间不足结论',
  `project_version` bigint DEFAULT NULL COMMENT '来源项目版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `project_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源项目编码；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源项目名称；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `customer_id` bigint DEFAULT NULL COMMENT '来源客户ID；原无客户时为空',
  `customer_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源客户编码',
  `customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源客户名称',
  `department_id` bigint DEFAULT NULL COMMENT '来源部门ID',
  `department_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源部门编码',
  `department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源部门名称',
  `project_scope_version` bigint DEFAULT NULL COMMENT '来源项目范围版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `withdraw_user_id` bigint DEFAULT NULL COMMENT '任务负责人撤回身份',
  `withdraw_time` datetime(3) DEFAULT NULL COMMENT '负责人撤回时间',
  `withdraw_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人撤回原因',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_approval_task_plan` (`tenant_id`,`task_id`,`plan_revision_id`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cut_approval_previous` (`tenant_id`,`previous_approval_instance_id`),
  KEY `idx_cut_approval_project_status` (`tenant_id`,`project_id`,`status_code`,`id`),
  KEY `fk_cut_approval_task` (`task_id`),
  KEY `fk_cut_approval_plan` (`plan_revision_id`),
  CONSTRAINT `fk_cut_approval_plan` FOREIGN KEY (`plan_revision_id`) REFERENCES `cut_plan_revision` (`id`),
  CONSTRAINT `fk_cut_approval_task` FOREIGN KEY (`task_id`) REFERENCES `cut_task` (`id`),
  CONSTRAINT `chk_cut_approval_checklist` CHECK (((0 <> coalesce(((`grade_code` in (_utf8mb4'A',_utf8mb4'B',_utf8mb4'C')) and (`checklist_id` > 0) and (`checklist_version` > 0)),false)) or (0 <> coalesce(((`grade_code` = _utf8mb4'D') and (`checklist_id` is null) and (`checklist_version` is null)),false)))),
  CONSTRAINT `chk_cut_approval_decision` CHECK ((coalesce((((`status_code` = _utf8mb4'APPROVED') and (`decide_time` is not null) and (`rejection_reason` is null)) or ((`status_code` = _utf8mb4'REJECTED') and (`decide_time` is not null) and (char_length(trim(`rejection_reason`)) between 1 and 1000)) or ((`status_code` in (_utf8mb4'PENDING',_utf8mb4'PAUSED_SOURCE_INVALIDATED',_utf8mb4'WITHDRAWN')) and (`decide_time` is null) and (`rejection_reason` is null))),false) = true)),
  CONSTRAINT `chk_cut_approval_grade` CHECK ((`grade_code` in (_utf8mb4'A',_utf8mb4'B',_utf8mb4'C',_utf8mb4'D'))),
  CONSTRAINT `chk_cut_approval_hold` CHECK (((`hold_reason_code` is null) or ((`status_code` = _utf8mb4'PENDING') and (`hold_reason_code` in (_utf8mb4'ROUTE_CANDIDATE_NOT_UNIQUE',_utf8mb4'APPROVER_UNAVAILABLE'))))),
  CONSTRAINT `chk_cut_approval_lead_time` CHECK (((((`lead_time_enabled_flag` = 0x00) and (`lead_rule_version` is null) and (`lead_timezone_id` is null) and (`lead_plan_submit_time` is null) and (`lead_required_days` is null) and (`lead_actual_natural_days` is null) and (`lead_late_submission_flag` is null)) or (0 <> coalesce(((`lead_time_enabled_flag` = 0x01) and (`grade_code` in (_utf8mb4'A',_utf8mb4'B')) and (`lead_rule_version` is not null) and (`lead_timezone_id` is not null) and (`lead_plan_submit_time` is not null) and (`lead_required_days` is not null) and (`lead_actual_natural_days` is not null) and (`lead_late_submission_flag` is not null) and (`source_schedule_time` is not null)),false))) = true)),
  CONSTRAINT `chk_cut_approval_replacement` CHECK ((((`previous_approval_instance_id` is null) or (`previous_approval_instance_id` > 0)) and ((`replacement_approval_instance_id` is null) or (`replacement_approval_instance_id` > 0)))),
  CONSTRAINT `chk_cut_approval_status` CHECK ((`status_code` in (_utf8mb4'PENDING',_utf8mb4'PAUSED_SOURCE_INVALIDATED',_utf8mb4'WITHDRAWN',_utf8mb4'APPROVED',_utf8mb4'REJECTED'))),
  CONSTRAINT `chk_cut_approval_values` CHECK (((`plan_revision_no` > 0) and (`assessment_version` > 0) and (`initiator_user_id` > 0) and (`initiator_project_scope_version` >= 0) and (`source_snapshot_version` > 0) and (`version` >= 0) and ((`current_node_no` is null) or (`current_node_no` > 0)))),
  CONSTRAINT `chk_cut_approval_withdrawal` CHECK ((coalesce((((`status_code` = _utf8mb4'WITHDRAWN') and (`withdraw_user_id` > 0) and (`withdraw_time` is not null) and (char_length(trim(`withdraw_reason`)) between 1 and 1000)) or ((`status_code` <> _utf8mb4'WITHDRAWN') and (`withdraw_user_id` is null) and (`withdraw_time` is null) and (`withdraw_reason` is null))),false) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-005 P5分级审批实例';

CREATE TABLE `cut_approval_node` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `approval_instance_id` bigint NOT NULL,
  `node_no` int NOT NULL,
  `node_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_approver_user_id` bigint DEFAULT NULL,
  `current_approver_user_id` bigint DEFAULT NULL,
  `candidate_fact_snapshot` json DEFAULT NULL COMMENT '旧原办理资格事实原件；新业务写入NULL，禁止更改历史原值',
  `project_scope_version` bigint DEFAULT NULL,
  `assessment_review_decision_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assessment_review_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `feedback` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decide_time` datetime(3) DEFAULT NULL,
  `pending_marker` tinyint GENERATED ALWAYS AS ((case when (`status_code` = _utf8mb4'PENDING') then 1 else NULL end)) STORED,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
