  `candidate_role_id` bigint DEFAULT NULL COMMENT 'SYSTEM实际角色ID',
  `candidate_role_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SYSTEM实际角色编码',
  `candidate_group_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPM原生候选组键',
  `qualification_kind_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单人资格来源种类：发起人项目权限或当前项目服务经理',
  `qualification_outcome_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务经理来源FOUND/NOT_UNIQUE等原结论',
  `qualification_role_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当时实际服务经理职责编码',
  `qualification_project_version` bigint DEFAULT NULL COMMENT '当时项目版本',
  `qualification_participant_fact_version` bigint DEFAULT NULL COMMENT '当时参与事实版本',
  `qualification_required_action_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发起人需要的ACTION_EDIT等既有动作',
  `qualification_allowed_flag` bit(1) DEFAULT NULL COMMENT '发起人当时项目授权结论',
  `qualification_check_time` datetime(3) DEFAULT NULL COMMENT '资格事实核验时间',
  `decision_actor_user_id` bigint DEFAULT NULL COMMENT '真正完成本节点的办理人',
  `decision_role_id` bigint DEFAULT NULL COMMENT '办理时实际角色ID',
  `decision_membership_version` bigint DEFAULT NULL COMMENT '办理时单人成员关系水位',
  `decision_user_status_version` bigint DEFAULT NULL COMMENT '办理时用户有效性水位',
  `decision_check_time` datetime(3) DEFAULT NULL COMMENT '决定事务资格核验时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_approval_node_no` (`tenant_id`,`approval_instance_id`,`node_no`),
  UNIQUE KEY `uk_cut_approval_pending_node` (`tenant_id`,`approval_instance_id`,`pending_marker`),
  KEY `idx_cut_approval_todo` (`tenant_id`,`current_approver_user_id`,`status_code`,`id`),
  KEY `fk_cut_approval_node_instance` (`approval_instance_id`),
  CONSTRAINT `fk_cut_approval_node_instance` FOREIGN KEY (`approval_instance_id`) REFERENCES `cut_approval_instance` (`id`),
  CONSTRAINT `chk_cut_approval_assessment_review` CHECK ((((`node_code` <> _utf8mb4'SERVICE_MANAGER') and (`assessment_review_decision_code` is null) and (`assessment_review_reason` is null)) or ((`node_code` = _utf8mb4'SERVICE_MANAGER') and (`assessment_review_decision_code` is null) and (`assessment_review_reason` is null)) or ((`node_code` = _utf8mb4'SERVICE_MANAGER') and (`assessment_review_decision_code` = _utf8mb4'CONFIRMED') and (`assessment_review_reason` is null)) or (0 <> coalesce(((`node_code` = _utf8mb4'SERVICE_MANAGER') and (`assessment_review_decision_code` = _utf8mb4'NOT_REASONABLE') and (`status_code` = _utf8mb4'REJECTED') and (char_length(trim(`assessment_review_reason`)) between 1 and 1000)),false)))),
  CONSTRAINT `chk_cut_approval_node_approver` CHECK ((coalesce((((`approval_mode_code` = _utf8mb4'ROLE') and (`candidate_role_id` > 0) and (`candidate_group_key` = concat(_utf8mb4'ROLE:',`candidate_role_id`)) and (`original_approver_user_id` is null) and (((`node_code` = _utf8mb4'SECOND_LINE') and (`candidate_role_code` = _utf8mb4'probSupporter')) or ((`node_code` = _utf8mb4'RND') and (`candidate_role_code` = _utf8mb4'probRD'))) and (((`status_code` = _utf8mb4'WAITING') and (`current_approver_user_id` is null)) or ((`status_code` in (_utf8mb4'PENDING',_utf8mb4'CANCELLED')) and ((`current_approver_user_id` is null) or (`current_approver_user_id` > 0))) or ((`status_code` in (_utf8mb4'APPROVED',_utf8mb4'REJECTED')) and (`current_approver_user_id` > 0) and (`decision_actor_user_id` = `current_approver_user_id`)))) or ((`approval_mode_code` = _utf8mb4'PERSONAL') and (`candidate_role_id` is null) and (`candidate_role_code` is null) and (`candidate_group_key` is null) and (((`original_approver_user_id` is null) and (`current_approver_user_id` is null)) or ((`original_approver_user_id` > 0) and (`current_approver_user_id` > 0))))),false) = true)),
  CONSTRAINT `chk_cut_approval_node_code` CHECK ((`node_code` in (_utf8mb4'INITIATOR',_utf8mb4'SERVICE_MANAGER',_utf8mb4'SECOND_LINE',_utf8mb4'RND'))),
  CONSTRAINT `chk_cut_approval_node_decision` CHECK ((((0 <> coalesce(((`status_code` in (_utf8mb4'APPROVED',_utf8mb4'REJECTED')) and (`decide_time` is not null) and (char_length(trim(`feedback`)) between 1 and 1000)),false)) or ((`status_code` in (_utf8mb4'WAITING',_utf8mb4'PENDING',_utf8mb4'CANCELLED')) and (`decide_time` is null) and (`feedback` is null))) = true)),
  CONSTRAINT `chk_cut_approval_node_status` CHECK ((`status_code` in (_utf8mb4'WAITING',_utf8mb4'PENDING',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'CANCELLED'))),
  CONSTRAINT `chk_cut_approval_node_values` CHECK (((`node_no` > 0) and (`version` >= 0) and ((`project_scope_version` is null) or (`project_scope_version` >= 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-005审批节点';

CREATE TABLE `cut_approval_notification` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `approval_instance_id` bigint NOT NULL,
  `approval_node_id` bigint NOT NULL,
  `recipient_user_id` bigint NOT NULL,
