  `correlation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `channel_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `message_id` bigint DEFAULT NULL,
  `provider_reference_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retry_count` int NOT NULL,
  `next_retry_time` datetime(3) DEFAULT NULL,
  `last_error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_attempt_time` datetime(3) DEFAULT NULL,
  `send_time` datetime(3) DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_approval_notification_delivery` (`tenant_id`,`delivery_key`),
  KEY `idx_cut_approval_notification_due` (`tenant_id`,`status_code`,`next_retry_time`,`id`),
  KEY `fk_cut_approval_notification_instance` (`approval_instance_id`),
  KEY `fk_cut_approval_notification_node` (`approval_node_id`),
  CONSTRAINT `fk_cut_approval_notification_instance` FOREIGN KEY (`approval_instance_id`) REFERENCES `cut_approval_instance` (`id`),
  CONSTRAINT `fk_cut_approval_notification_node` FOREIGN KEY (`approval_node_id`) REFERENCES `cut_approval_node` (`id`),
  CONSTRAINT `chk_cut_approval_notification_channel` CHECK ((`channel_code` in (_utf8mb4'IN_PLATFORM',_utf8mb4'SMS',_utf8mb4'EMAIL',_utf8mb4'DINGTALK'))),
  CONSTRAINT `chk_cut_approval_notification_correlation` CHECK ((((`channel_code` = _utf8mb4'IN_PLATFORM') and ((`correlation_id` is null) or (0 <> coalesce(((char_length(`correlation_id`) between 1 and 128) and (char_length(`correlation_id`) = char_length(trim(`correlation_id`)))),false)))) or (0 <> coalesce(((`channel_code` in (_utf8mb4'SMS',_utf8mb4'EMAIL',_utf8mb4'DINGTALK')) and (`correlation_id` is not null) and (char_length(`correlation_id`) between 1 and 128) and (char_length(`correlation_id`) = char_length(trim(`correlation_id`)))),false)))),
  CONSTRAINT `chk_cut_approval_notification_status` CHECK (((((`channel_code` = _utf8mb4'IN_PLATFORM') and (`provider_reference_id` is null) and (`last_attempt_time` is null) and (((`status_code` = _utf8mb4'PENDING') and (`message_id` is null) and (`next_retry_time` is null) and (`last_error_code` is null) and (`send_time` is null)) or (0 <> coalesce(((`status_code` = _utf8mb4'PENDING_RETRY') and (`message_id` is null) and (`next_retry_time` is not null) and (char_length(trim(`last_error_code`)) between 1 and 64) and (`send_time` is null)),false)) or (0 <> coalesce(((`status_code` = _utf8mb4'SENT') and (`message_id` > 0) and (`next_retry_time` is null) and (`last_error_code` is null) and (`send_time` is not null)),false)))) or ((`channel_code` in (_utf8mb4'SMS',_utf8mb4'EMAIL',_utf8mb4'DINGTALK')) and (`message_id` is null) and (`send_time` is null) and (((`status_code` = _utf8mb4'PENDING') and (`retry_count` = 0) and (`provider_reference_id` is null) and (`next_retry_time` is null) and (`last_error_code` is null) and (`last_attempt_time` is null)) or (0 <> coalesce(((`status_code` = _utf8mb4'PENDING_RETRY') and (`retry_count` > 0) and (`provider_reference_id` is null) and (`next_retry_time` is not null) and (`last_attempt_time` is not null) and (char_length(trim(`last_error_code`)) between 1 and 64)),false)) or (0 <> coalesce(((`status_code` = _utf8mb4'ACCEPTED') and (char_length(trim(`provider_reference_id`)) between 1 and 128) and (`next_retry_time` is null) and (`last_error_code` is null) and (`last_attempt_time` is not null)),false)) or ((`status_code` = _utf8mb4'DELIVERY_UNKNOWN') and (`next_retry_time` is null) and (`last_error_code` is null) and (`last_attempt_time` is not null))))) = true)),
  CONSTRAINT `chk_cut_approval_notification_values` CHECK (((`recipient_user_id` > 0) and (char_length(trim(`delivery_key`)) between 1 and 128) and (char_length(trim(`template_code`)) between 1 and 64) and (`retry_count` >= 0) and (`version` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-005审批通知投递';

