  CONSTRAINT `fk_cut_structured_72` FOREIGN KEY (`tenant_id`, `checklist_item_id`) REFERENCES `cut_cutover_checklist_item` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_73` FOREIGN KEY (`tenant_id`, `checklist_result_id`) REFERENCES `cut_cutover_checklist_item_result` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批冻结结果集合';

CREATE TABLE `cut_approval_review_item` (
