  CONSTRAINT `chk_cut_approval_review_code` CHECK ((`item_code` in (_utf8mb4'PREPARATION',_utf8mb4'BUSINESS_TEST',_utf8mb4'EXECUTION',_utf8mb4'ROLLBACK',_utf8mb4'OTHER'))),
  CONSTRAINT `chk_cut_approval_review_decision` CHECK ((((`decision_code` = _utf8mb4'YES') and (`unreasonable_reason` is null)) or (0 <> coalesce(((`decision_code` = _utf8mb4'NO') and (char_length(trim(`unreasonable_reason`)) between 1 and 1000)),false))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-005服务经理复核项';

