  KEY `idx_cut_config_rule_item` (`tenant_id`,`configuration_revision_id`,`item_definition_revision_id`,`status_code`,`priority`),
  CONSTRAINT `chk_cut_config_rule_status` CHECK ((`status_code` in (_utf8mb4'ENABLED',_utf8mb4'DISABLED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUT-07统一采集项绑定规则修订';

CREATE TABLE `cut_cutover_checklist_item` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `checklist_id` bigint NOT NULL COMMENT 'CUT-03清单版本ID',
  `stable_item_key` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_definition_revision_id` bigint DEFAULT NULL COMMENT '系统采集项定义逻辑引用',
  `item_definition_version` int DEFAULT NULL,
  `item_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `interface_format_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `interface_schema_snapshot` json DEFAULT NULL COMMENT '旧冻结界面与输入Schema原件；新业务写入NULL，禁止更改历史原值',
  `display_condition_snapshot` json DEFAULT NULL COMMENT '旧冻结显示条件原件；新业务写入NULL，禁止更改历史原值',
  `work_mode_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `required_flag` bit(1) NOT NULL,
  `source_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_id` bigint DEFAULT NULL COMMENT '适用设备逻辑引用',
  `command_template_id` bigint DEFAULT NULL COMMENT 'DAC命令模板逻辑引用',
  `binding_rule_revision_id` bigint DEFAULT NULL,
  `binding_rule_version` int DEFAULT NULL,
  `applicable_flag` bit(1) NOT NULL,
  `custom_creator_user_id` bigint DEFAULT NULL COMMENT '自定义项创建人',
  `sort_order` int NOT NULL,
  `version` int NOT NULL COMMENT '草稿阶段乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_checklist_item_key` (`tenant_id`,`checklist_id`,`stable_item_key`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  KEY `idx_cut_checklist_item_order` (`tenant_id`,`checklist_id`,`item_type_code`,`applicable_flag`,`sort_order`,`id`),
  KEY `fk_cut_checklist_item_root` (`checklist_id`),
  CONSTRAINT `fk_cut_checklist_item_root` FOREIGN KEY (`checklist_id`) REFERENCES `cut_cutover_checklist` (`id`),
  CONSTRAINT `chk_cut_checklist_item_flags` CHECK (((`required_flag` in (0x00,0x01)) and (`applicable_flag` in (0x00,0x01)))),
  CONSTRAINT `chk_cut_checklist_item_source` CHECK (((((`source_code` = _utf8mb4'SYSTEM_MATCHED') and (`item_definition_revision_id` is not null) and (`item_definition_version` is not null) and (`item_definition_version` > 0) and (`custom_creator_user_id` is null)) or ((`source_code` = _utf8mb4'CUSTOM') and (`item_definition_revision_id` is null) and (`item_definition_version` is null) and (`binding_rule_revision_id` is null) and (`binding_rule_version` is null) and (`custom_creator_user_id` is not null))) = true)),
  CONSTRAINT `chk_cut_checklist_item_values` CHECK (((`sort_order` >= 0) and (`version` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-003 P3动态采集清单项';

CREATE TABLE `cut_cutover_checklist_item_definition_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT,
