  `interface_schema` json DEFAULT NULL COMMENT '旧采集项字段结构原件；新业务写入NULL，禁止更改历史原值',
  `feedback_format_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `required_flag` bit(1) NOT NULL DEFAULT b'0',
  `work_mode_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `external_source_config` json DEFAULT NULL COMMENT '旧外部来源配置原件；新业务写入NULL，禁止更改历史原值',
  `subtable_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED',
  `sort_order` int NOT NULL DEFAULT '0',
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
