  `external_interface_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '正式集成目录的接口标识',
  `external_manual_fallback_flag` bit(1) DEFAULT NULL COMMENT '外部加载失败时是否允许人工填写/证据替代',
