CREATE TABLE `cut_plan_risk_mitigation` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `plan_revision_id` bigint NOT NULL COMMENT '既有方案修订ID',
  `checklist_result_id` bigint NOT NULL COMMENT '当时采用的统一结果ID',
  `checklist_item_id` bigint NOT NULL COMMENT '对应采集项',
  `checklist_result_version` int NOT NULL COMMENT '当时结果版本号',
  `mitigation` text COMMENT '填写值：本项应对措施；草稿尚未填写时为空，风险来源引用仍保留',
  `sort_order` int NOT NULL COMMENT '顺序',
  `creator` varchar(64) NOT NULL COMMENT '创建审计账号；服务端写入',
  `create_time` datetime(3) NOT NULL COMMENT '创建审计时间',
  `updater` varchar(64) NOT NULL COMMENT '更新审计账号；服务端写入',
  `update_time` datetime(3) NOT NULL COMMENT '更新审计时间',
  `deleted` bit(1) NOT NULL COMMENT '草稿明细逻辑删除标记；已发布或已提交历史不开放删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`plan_revision_id`,`checklist_result_id`),
  KEY `fk_cut_structured_67` (`tenant_id`,`checklist_result_id`),
  KEY `fk_cut_structured_68` (`tenant_id`,`checklist_item_id`),
  CONSTRAINT `fk_cut_structured_66` FOREIGN KEY (`tenant_id`, `plan_revision_id`) REFERENCES `cut_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_67` FOREIGN KEY (`tenant_id`, `checklist_result_id`) REFERENCES `cut_cutover_checklist_item_result` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_68` FOREIGN KEY (`tenant_id`, `checklist_item_id`) REFERENCES `cut_cutover_checklist_item` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='方案逐项风险应对';

CREATE TABLE `cut_plan_schedule` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `plan_revision_id` bigint NOT NULL COMMENT '既有方案修订ID',
  `sequence_no` int NOT NULL COMMENT '计划行序号',
  `plan_time` datetime(3) NOT NULL COMMENT '填写值：计划时间',
  `content` text NOT NULL COMMENT '填写值：计划内容',
  `creator` varchar(64) NOT NULL COMMENT '创建审计账号；服务端写入',
  `create_time` datetime(3) NOT NULL COMMENT '创建审计时间',
  `updater` varchar(64) NOT NULL COMMENT '更新审计账号；服务端写入',
  `update_time` datetime(3) NOT NULL COMMENT '更新审计时间',
  `deleted` bit(1) NOT NULL COMMENT '草稿明细逻辑删除标记；已发布或已提交历史不开放删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`plan_revision_id`,`sequence_no`),
  CONSTRAINT `fk_cut_structured_62` FOREIGN KEY (`tenant_id`, `plan_revision_id`) REFERENCES `cut_plan_revision` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='方案计划安排行';

CREATE TABLE `cut_plan_support_contact_change` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `support_arrangement_id` bigint NOT NULL COMMENT '原保障安排',
  `change_no` int NOT NULL COMMENT '变更序号',
  `previous_change_id` bigint DEFAULT NULL COMMENT '前一次联系信息变更',
  `before_person_name` varchar(128) NOT NULL COMMENT '变更前人员',
  `before_phone` varchar(64) NOT NULL COMMENT '变更前电话',
  `before_arrive_time` datetime(3) NOT NULL COMMENT '变更前到位时间',
  `before_customer_contact_id` bigint DEFAULT NULL COMMENT '客户角色变更前CUS联系人引用',
  `before_customer_contact_version` bigint DEFAULT NULL COMMENT '客户角色变更前CUS联系人版本',
  `after_person_name` varchar(128) NOT NULL COMMENT '填写值：变更后人员',
  `after_phone` varchar(64) NOT NULL COMMENT '填写值：变更后电话',
  `after_arrive_time` datetime(3) NOT NULL COMMENT '填写值：变更后到位时间',
  `after_customer_contact_id` bigint DEFAULT NULL COMMENT '客户角色变更后CUS联系人引用',
  `after_customer_contact_version` bigint DEFAULT NULL COMMENT '客户角色变更后CUS联系人版本',
  `reason` text COMMENT '填写值：变更原因；当前接口必填，历史原件及既有无原因参数接口缺失时不补造',
  `operate_user_id` bigint NOT NULL COMMENT '实际操作者',
  `operate_time` datetime(3) NOT NULL COMMENT '实际操作时间',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  `before_person_source_code` varchar(32) DEFAULT NULL,
  `before_person_source_id` bigint DEFAULT NULL,
  `before_person_source_version` bigint DEFAULT NULL,
  `after_person_source_code` varchar(32) DEFAULT NULL,
  `after_person_source_id` bigint DEFAULT NULL,
  `after_person_source_version` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`support_arrangement_id`,`change_no`),
  KEY `fk_cut_structured_70` (`tenant_id`,`previous_change_id`),
  CONSTRAINT `fk_cut_structured_69` FOREIGN KEY (`tenant_id`, `support_arrangement_id`) REFERENCES `cut_cutover_support_arrangement` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_70` FOREIGN KEY (`tenant_id`, `previous_change_id`) REFERENCES `cut_plan_support_contact_change` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='批准后保障联系信息变更';

CREATE TABLE `cut_result_bulletin_summary` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `checklist_result_id` bigint NOT NULL COMMENT '所属统一结果版本；与根同事务写入',
  `has_bulletins_flag` bit(1) DEFAULT NULL COMMENT '实际是否存在公告；成功查询可据列表计算，失败不能写false',
