CREATE TABLE `kno_announcement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告编号（如 TA-2026-001）',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `announcement_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TECH_NOTICE' COMMENT '公告类型：TECH_NOTICE技术公告/EOS停产/EOM停维',
  `product_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '适用设备型号',
  `affected_versions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '影响版本范围JSON数组',
  `publish_date` date DEFAULT NULL COMMENT '发布日期',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '失效日期',
  `severity` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '严重等级：CRITICAL/HIGH/MEDIUM/LOW',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '公告内容富文本',
  `handling_suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '处置建议',
  `file_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件URL',
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件名',
  `file_size` bigint DEFAULT NULL COMMENT '附件大小（字节）',
  `file_checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件校验值',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已发布/2已停用',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `creator_user_id` bigint DEFAULT NULL COMMENT '创建人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_announcement_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_announcement_type` (`announcement_type`),
  KEY `idx_pms_eng_announcement_model` (`product_model`),
  KEY `idx_pms_eng_announcement_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='技术公告与停产停维';

CREATE TABLE `kno_announcement_check` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检查编号（如 PCH-2026-001）',
  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `announcement_id` bigint NOT NULL COMMENT '关联技术公告ID',
  `device_id` bigint DEFAULT NULL COMMENT '关联设备ID',
  `device_serial` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号',
  `device_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备型号',
  `device_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备版本',
  `match_result` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNKNOWN' COMMENT '匹配结果：HIT命中/MISS未命中/UNKNOWN未知',
  `eom_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'EOS/EOM状态：EOS/EOM/NONE',
  `handling_suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '处置建议',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0待检查/1已检查/2已处置/3已忽略',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `checker_user_id` bigint DEFAULT NULL COMMENT '检查人',
  `check_time` datetime DEFAULT NULL COMMENT '检查时间',
  `handle_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理意见',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `creator_user_id` bigint DEFAULT NULL COMMENT '创建人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_announcement_check_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_announcement_check_project` (`project_id`),
  KEY `idx_pms_eng_announcement_check_announcement` (`announcement_id`),
  KEY `idx_pms_eng_announcement_check_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='技术公告预检查记录';

CREATE TABLE `plt_approval_attempt` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务主体所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务主体类型',
  `entity_id` bigint NOT NULL COMMENT '业务主体ID',
  `purpose` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批用途',
  `attempt_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '尝试幂等键',
  `submission_basis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交依据（内容范围/并发依据说明）',
  `submission_concurrency_basis` int DEFAULT NULL COMMENT '提交时的业务内容并发基准（生效时校验批准是否仍适用）',
  `neutral_process_ref` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '中性流程引用',
  `backend_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '承接本尝试的审批执行实现',
  `instance_ref` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '引擎原生实例标识（仅存于关联记录）',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态 PENDING/APPROVED/REJECTED/WITHDRAWN',
  `conclusion_basis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结论依据（引擎随可信结果返回）',
  `decided_time` datetime(3) DEFAULT NULL COMMENT '流程结论时间',
  `previous_attempt_id` bigint DEFAULT NULL COMMENT '重提来源尝试主键（同主体同用途的上一轮）',
  `batch_group_ref` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次组标识（同批多主体共享）',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_approval_attempt` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`purpose`,`attempt_id`),
  KEY `idx_plt_approval_attempt_instance` (`tenant_id`,`instance_ref`),
  KEY `idx_plt_approval_attempt_subject` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`purpose`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批-公共尝试关联';

CREATE TABLE `plt_approval_effect` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `attempt_row_id` bigint NOT NULL COMMENT '尝试关联主键',
  `operation_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准后执行的实体命令（目录声明操作）',
  `idempotency_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '命令执行幂等键',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态 SUCCESS/PENDING_RECOVERY/FAILED',
  `receipt_outcome` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '命令回执结果（成功时）',
  `concurrency_basis` int DEFAULT NULL COMMENT '执行时并发依据',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败/待恢复原因',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_approval_effect` (`tenant_id`,`attempt_row_id`,`idempotency_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批-领域生效记录（与流程批准分列）';

CREATE TABLE `plt_approval_opinion` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `attempt_row_id` bigint NOT NULL COMMENT '尝试关联主键',
  `action` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作 SUBMIT/APPROVE/REJECT/WITHDRAW',
  `comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '意见',
  `actor_user_id` bigint NOT NULL COMMENT '操作者用户ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_plt_approval_opinion_attempt` (`tenant_id`,`attempt_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批-意见记录（旧尝试意见随行保留）';

CREATE TABLE `plt_authorization` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '授权编号（如 AUTH-2026-001）',
  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '授权名称',
  `authorization_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEMPORARY' COMMENT '授权类型：FORMAL正式/TEMPORARY临时/LOAN借货',
  `device_id` bigint DEFAULT NULL COMMENT '关联设备ID',
  `device_serial` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号',
  `device_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备型号',
  `license_key` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '授权密钥',
  `license_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '授权类型描述',
  `apply_start_date` date DEFAULT NULL COMMENT '申请开始日期',
  `apply_end_date` date DEFAULT NULL COMMENT '申请结束日期',
  `actual_end_date` date DEFAULT NULL COMMENT '实际结束日期',
  `usage_limit` int DEFAULT NULL COMMENT '使用次数限制',
  `used_count` int NOT NULL DEFAULT '0' COMMENT '已使用次数',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已提交/2审批中/3已通过/4已驳回/5已撤回/6已终止',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `submit_user_id` bigint DEFAULT NULL COMMENT '提交人',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人',
  `approve_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `recall_user_id` bigint DEFAULT NULL COMMENT '撤回人',
  `recall_time` datetime DEFAULT NULL COMMENT '撤回时间',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPM流程实例ID（预留）',
  `creator_user_id` bigint DEFAULT NULL COMMENT '创建人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_authorization_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_authorization_project` (`project_id`),
  KEY `idx_pms_eng_authorization_status` (`status`),
  KEY `idx_pms_eng_authorization_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='授权与借货准备';

CREATE TABLE `plt_authorization_grant` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '授权记录编号',
  `subject_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_id` bigint NOT NULL,
  `resource_context_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` bigint NOT NULL,
  `action_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `effective_from` datetime NOT NULL,
  `effective_to` datetime DEFAULT NULL,
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_context_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `granted_by` bigint NOT NULL,
  `granted_at` datetime NOT NULL,
  `revoked_by` bigint DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `revoke_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `current_marker` tinyint DEFAULT '1',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_authorization_grant_current` (`tenant_id`,`subject_type_code`,`subject_id`,`resource_context_code`,`resource_type_code`,`resource_id`,`action_code`,`scope_code`,`current_marker`),
  KEY `idx_plt_authorization_grant_subject` (`tenant_id`,`subject_type_code`,`subject_id`,`status_code`,`effective_from`,`effective_to`),
  KEY `idx_plt_authorization_grant_resource` (`tenant_id`,`resource_context_code`,`resource_type_code`,`resource_id`,`action_code`,`status_code`,`effective_from`,`effective_to`),
  CONSTRAINT `ck_plt_authorization_grant_current_marker` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `ck_plt_authorization_grant_interval` CHECK (((`effective_to` is null) or (`effective_to` > `effective_from`))),
  CONSTRAINT `ck_plt_authorization_grant_status` CHECK ((`status_code` in (_utf8mb4'ACTIVE',_utf8mb4'REVOKED',_utf8mb4'EXPIRED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='平台通用授权事实';

CREATE TABLE `plt_business_view_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '业务视图修订编号',
  `tenant_id` bigint NOT NULL,
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `view_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `revision_no` bigint unsigned NOT NULL,
  `owner_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `view_source` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `dynamic_form_revision_id` bigint DEFAULT NULL,
  `component_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `component_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `context_schema` json NOT NULL,
  `supported_actions` json NOT NULL,
  `query_provider_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `command_provider_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `permission_provider_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `published_at` datetime(6) DEFAULT NULL,
  `disabled_at` datetime(6) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bvr_identity` (`tenant_id`,`entity_type`,`view_key`,`revision_no`),
  CONSTRAINT `ck_bvr_actions` CHECK ((json_type(`supported_actions`) = _utf8mb4'ARRAY')),
  CONSTRAINT `ck_bvr_disabled` CHECK (((`disabled_at` is null) or ((`published_at` is not null) and (`disabled_at` >= `published_at`)))),
  CONSTRAINT `ck_bvr_schema` CHECK ((json_type(`context_schema`) = _utf8mb4'OBJECT')),
  CONSTRAINT `ck_bvr_source` CHECK ((((`view_source` = _utf8mb4'PAGE') and (`dynamic_form_revision_id` is null)) or ((`view_source` = _utf8mb4'DYNAMIC_FORM') and (`dynamic_form_revision_id` is not null) and (`dynamic_form_revision_id` > 0)))),
  CONSTRAINT `ck_bvr_version` CHECK ((`revision_no` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `plt_collection_batch` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_count` int NOT NULL,
  `success_count` int NOT NULL DEFAULT '0',
  `failure_count` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_batch_idempotency` (`tenant_id`,`idempotency_key`),
  UNIQUE KEY `uk_plt_batch_no` (`tenant_id`,`batch_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INT-12采集批次';

CREATE TABLE `plt_collection_callback_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `callback_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `receipt_id` bigint NOT NULL,
  `sequence_no` bigint NOT NULL,
  `external_task_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `external_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `mapped_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `result_version` bigint NOT NULL,
  `file_version_id` bigint DEFAULT NULL,
  `quarantine_evidence_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failure_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `processing_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `started_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `trace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_callback_id` (`tenant_id`,`callback_id`),
  UNIQUE KEY `uk_plt_callback_sequence` (`tenant_id`,`platform_task_id`,`sequence_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INT-12 Platform不可变回调事实';

CREATE TABLE `plt_collection_log_quarantine` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `callback_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `storage_operation_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `size_bytes` bigint NOT NULL,
  `reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quarantined_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_collection_quarantine` (`tenant_id`,`callback_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_collection_request` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `entry` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `object_id` bigint NOT NULL,
  `actor_id` bigint NOT NULL,
  `request_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `request_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `command_text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `template_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `template_revision_id` bigint DEFAULT NULL,
  `credential_version` bigint DEFAULT NULL,
  `retry_of_id` bigint DEFAULT NULL,
  `consumed_result_version` bigint DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `execution_purpose` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dispatch_mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SERVER',
  `local_connection_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `local_connection_version` bigint DEFAULT NULL,
  `desktop_source_version` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_collection_request_key` (`tenant_id`,`request_key`),
  UNIQUE KEY `uk_plt_collection_request_task` (`tenant_id`,`platform_task_id`),
  KEY `idx_plt_collection_request_source` (`tenant_id`,`entry`,`object_id`,`id`),
  CONSTRAINT `ck_collection_execution_purpose` CHECK (((`execution_purpose` is null) or (`execution_purpose` in (_utf8mb4'PRECHECK',_utf8mb4'INSPECTION'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_collection_result_consumption` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consumer_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consumer_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consumer_object_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `result_version` bigint NOT NULL,
  `consumption_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consumed_at` datetime(3) NOT NULL,
  `trace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_collection_consumption` (`tenant_id`,`platform_task_id`,`consumer_context`,`consumer_object_type`,`consumer_object_id`,`result_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INT-12业务结果消费确认';

CREATE TABLE `plt_collection_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '采集任务编号',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '行版本（乐观锁）',
  `tenant_id` bigint NOT NULL,
  `batch_id` bigint NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `host` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `port` int NOT NULL,
  `protocol` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `credential_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `credential_id` bigint DEFAULT NULL,
  `grant_snapshot_id` bigint DEFAULT NULL,
  `temporary_username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `completion_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `technical_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `external_task_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `external_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `result_version` bigint DEFAULT NULL,
  `file_version_id` bigint DEFAULT NULL,
  `quarantine_evidence_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failure_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consumer_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consumer_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consumer_object_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consumed_result_version` bigint DEFAULT NULL,
  `last_callback_sequence` bigint DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_collection_task_id` (`tenant_id`,`platform_task_id`),
  UNIQUE KEY `uk_plt_collection_idempotency` (`tenant_id`,`idempotency_key`),
  KEY `idx_plt_collection_batch` (`tenant_id`,`batch_id`),
  KEY `idx_plt_collection_external_task` (`tenant_id`,`external_task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INT-12逐设备采集任务';

CREATE TABLE `plt_collection_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '采集模板编号',
  `tenant_id` bigint NOT NULL,
  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `purpose` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `protocol` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '历史协议信息；新模板不填写，执行协议由设备连接指定',
  `device_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `revision` int NOT NULL,
  `command_text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `publication_started` bit(1) NOT NULL DEFAULT b'0',
  `published_at` datetime DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `version` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_collection_template_version` (`tenant_id`,`template_code`,`revision`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_credential_grant` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `credential_id` bigint NOT NULL,
  `grantee_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `grantee_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `protocol` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `command_template_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_plt_grant_credential` (`tenant_id`,`credential_id`,`status`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INT-12凭证显式授权';

CREATE TABLE `plt_delivery_capability_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用实体所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用实体类型',
  `type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '材料类型编码',
  `required` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否必交（属于要求，不属于类型）',
  `minimum_quantity` int NOT NULL DEFAULT '0' COMMENT '最低数量',
  `counting_unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MATERIAL' COMMENT '计数单位 MATERIAL/FILE_VERSION/SUBMISSION',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_config` (`tenant_id`,`owner_module`,`entity_type`,`type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付-实体能力适用配置';

CREATE TABLE `plt_delivery_fulfillment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `requirement_id` bigint NOT NULL,
  `material_id` bigint NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_fulfillment` (`tenant_id`,`requirement_id`,`material_id`),
  KEY `idx_plt_delivery_fulfillment_material` (`tenant_id`,`material_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付材料与要求的显式履行关系';

CREATE TABLE `plt_delivery_material` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源实体所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源实体类型',
  `entity_id` bigint NOT NULL COMMENT '来源实体ID',
  `type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '材料类型编码',
  `material_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FILE' COMMENT '材料证据锚 FILE=文件版本 / BUSINESS_RESULT=业务成果',
  `requirement_id` bigint DEFAULT NULL COMMENT '绑定的模板冻结要求（模板行材料直连要求）',
  `project_id` bigint DEFAULT NULL COMMENT '项目上下文（供项目级汇总）',
  `business_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务成果对象类型（BUSINESS_RESULT 行，统一目录 entityType）',
  `business_object_id` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务成果对象ID（type|objectId|resultId|formedAt 复合身份）',
  `business_revision_no` bigint DEFAULT NULL COMMENT '业务成果修订锚（如方案基线版本；无修订对象为 NULL）',
  `file_reference_id` bigint DEFAULT NULL COMMENT '统一文件引用ID（BUSINESS_RESULT 行为空）',
  `file_artifact_id` bigint DEFAULT NULL COMMENT '文件工件ID（BUSINESS_RESULT 行为空）',
  `file_version_no` int DEFAULT NULL COMMENT '文件版本号（BUSINESS_RESULT 行为空）',
  `file_sha256` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件内容摘要（BUSINESS_RESULT 行为空）',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名称（BUSINESS_RESULT 行为空）',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料标题',
  `source_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPLOAD' COMMENT '来源 UPLOAD/GENERATED/ASSOCIATED',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态 ACTIVE/WITHDRAWN',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  `archive_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_REQUIRED' COMMENT '归档补偿状态 NOT_REQUIRED/PENDING_COMPENSATION/ARCHIVED/INVALID',
  `archive_failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '归档失败原因编码',
  `archive_retry_count` int NOT NULL DEFAULT '0' COMMENT '归档补偿重试次数',
  `archive_time` datetime(3) DEFAULT NULL COMMENT '归档完成时间',
  `source_identity_key` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新登记来源版本身份SHA256（旧行保持NULL）',
  `business_type_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '稳定业务类型/来源目录编码，不是模板要求编码',
  `source_owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_entity_id` bigint DEFAULT NULL,
  `source_revision_id` bigint DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0' COMMENT '公共材料操作版本；独立于文件版本及业务修订',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_mat` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`type_code`,`file_artifact_id`,`file_version_no`),
  UNIQUE KEY `uk_plt_delivery_material_source` (`tenant_id`,`source_identity_key`),
  KEY `idx_plt_delivery_mat_entity` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`type_code`),
  KEY `idx_plt_delivery_mat_project` (`tenant_id`,`project_id`),
  KEY `idx_plt_delivery_mat_requirement` (`requirement_id`),
  KEY `idx_plt_delivery_mat_business` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`business_object_type`,`business_object_id`),
  KEY `idx_plt_delivery_mat_archive` (`tenant_id`,`archive_status`),
  KEY `idx_plt_delivery_native_source` (`tenant_id`,`source_owner_module`,`source_entity_type`,`source_entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付-实际材料记录';

CREATE TABLE `plt_delivery_requirement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源实体所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源实体类型',
  `entity_id` bigint NOT NULL COMMENT '来源实体ID',
  `type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '材料类型编码',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '要求显示名（TEMPLATE_FROZEN=交付件名称）',
  `requirement_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CATALOG' COMMENT '要求来源 CATALOG=能力配置生成 / TEMPLATE_FROZEN=模板冻结应交根',
  `stage_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绑定阶段编码（TEMPLATE_FROZEN）',
  `task_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绑定任务编码（NULL=阶段级要求）',
  `plan_version_id` bigint DEFAULT NULL COMMENT '冻结计划版本（TEMPLATE_FROZEN）',
  `source_definition_id` bigint DEFAULT NULL COMMENT '模板交付件定义引用ID',
  `project_id` bigint DEFAULT NULL COMMENT '项目上下文（供项目级汇总与门禁定位）',
  `frozen_config_json` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冻结要求配置（数量/允许来源/自动来源/确认规则 JSON）',
  `required` bit(1) NOT NULL COMMENT '是否必交',
  `minimum_quantity` int NOT NULL COMMENT '最低数量',
  `counting_unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计数单位 MATERIAL/FILE_VERSION/SUBMISSION',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN' COMMENT '状态 OPEN/SATISFIED/CONFIRMED',
  `confirmed_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '确认人（仅 CONFIRMED 有效）',
  `confirmed_time` datetime(3) DEFAULT NULL COMMENT '确认时间（仅 CONFIRMED 有效）',
  `config_id` bigint NOT NULL DEFAULT '0' COMMENT '生成本要求的能力配置主键',
  `config_version` int NOT NULL DEFAULT '0' COMMENT '生成本要求的配置版本',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  `archived_reopen_snapshot_id` bigint NOT NULL DEFAULT '0' COMMENT '0=current; otherwise governance REOPEN snapshot retaining this history',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_req` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`type_code`,`archived_reopen_snapshot_id`),
  KEY `idx_plt_delivery_req_entity` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付-要求实例';

CREATE TABLE `plt_delivery_submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `requirement_id` bigint NOT NULL COMMENT '要求实例ID',
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交幂等键',
  `material_ids_json` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本次提交的材料ID清单（JSON 数组）',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPLOAD' COMMENT '提交来源 UPLOAD/BUSINESS_RESULT/BUSINESS_DOCUMENT/AUTO_PROJECTION',
  `project_id` bigint DEFAULT NULL COMMENT '项目上下文',
  `request_payload_json` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求快照（幂等重放比对）',
  `decision_evidence_json` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '判定证据快照（满足/原因/证据）',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CURRENT' COMMENT '状态 CURRENT/SUPERSEDED/WITHDRAWN',
  `submit_evidence_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '提交证据快照（文件版本与摘要）',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  `current_marker` bigint GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'CURRENT') then `requirement_id` else NULL end)) STORED COMMENT '当前提交标记（CURRENT 时=requirement_id，其余为 NULL）',
  `archive_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `archive_failure_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `archive_retry_count` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_sub_request` (`tenant_id`,`requirement_id`,`request_key`),
  UNIQUE KEY `uk_plt_delivery_sub_current` (`tenant_id`,`current_marker`),
  KEY `idx_plt_delivery_sub_req` (`tenant_id`,`requirement_id`,`status`),
  KEY `idx_delivery_submission_archive` (`tenant_id`,`archive_status`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付-提交台账';

CREATE TABLE `plt_delivery_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型稳定编码',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型名称',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类',
  `allowed_media_json` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '允许的媒体类型清单（JSON 数组）',
  `max_size_bytes` bigint NOT NULL COMMENT '单文件大小上限（字节）',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_type` (`tenant_id`,`type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付-统一类型目录';

CREATE TABLE `plt_device_credential` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `credential_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `credential_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `encrypted_secret` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `kms_reference` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credential_version` bigint NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `external_connection_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registration_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registration_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registration_template_id` bigint DEFAULT NULL,
  `registration_expires_at` datetime DEFAULT NULL,
  `project_id` bigint DEFAULT NULL,
  `device_id` bigint DEFAULT NULL,
  `host` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `port` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_credential_code` (`tenant_id`,`credential_code`),
  UNIQUE KEY `uk_plt_credential_external` (`tenant_id`,`external_connection_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INT-12设备凭证';

CREATE TABLE `plt_device_log_parse` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `actor_id` bigint NOT NULL,
  `request_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_entry` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_object_id` bigint DEFAULT NULL,
  `source_execution_id` bigint DEFAULT NULL,
  `source_collection_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_file_version_id` bigint DEFAULT NULL,
  `state` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUBMITTING',
  `external_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `release_version` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wait_reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `result_snapshot_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Original successful sanitized parser response, write once',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_device_log_parse_request` (`tenant_id`,`request_key`),
  KEY `idx_device_log_parse_project` (`tenant_id`,`project_id`,`source_execution_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_dynamic_form_instance` (
  `id` bigint NOT NULL COMMENT '手工实例ID（应用预分配）',
  `instance_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户内实例编码',
  `instance_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例名称',
  `owner_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例Owner Context',
  `object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例对象类型',
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例对象稳定ID',
  `template_id` bigint NOT NULL COMMENT '冻结模板ID',
  `template_revision_id` bigint NOT NULL COMMENT '冻结模板修订ID',
  `template_revision_no` int NOT NULL COMMENT '冻结模板修订号',
  `engine_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结渲染引擎编码',
  `designer_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结设计器版本',
  `renderer_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结渲染器版本',
  `value_json` json NOT NULL COMMENT '普通字段值对象',
  `created_by` bigint NOT NULL COMMENT '实例创建主体',
  `version` int NOT NULL DEFAULT '0' COMMENT '实例乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_dynamic_form_instance_code` (`tenant_id`,`instance_code`),
  UNIQUE KEY `uk_plt_dynamic_form_instance_owner` (`tenant_id`,`owner_context`,`object_type`,`object_id`),
  KEY `idx_plt_dynamic_form_instance_page` (`tenant_id`,`update_time`,`id`),
  KEY `idx_plt_dynamic_form_instance_revision` (`tenant_id`,`template_revision_id`,`template_id`,`id`),
  CONSTRAINT `fk_plt_dynamic_form_instance_revision` FOREIGN KEY (`tenant_id`, `template_revision_id`, `template_id`) REFERENCES `plt_dynamic_form_template_revision` (`tenant_id`, `id`, `template_id`),
  CONSTRAINT `chk_plt_dynamic_form_instance_revision_number` CHECK ((`template_revision_no` > 0)),
  CONSTRAINT `chk_plt_dynamic_form_instance_value_json` CHECK ((json_type(`value_json`) = _utf8mb4'OBJECT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM手工动态表单实例';

CREATE TABLE `plt_dynamic_form_template` (
  `id` bigint NOT NULL COMMENT '模板稳定ID（应用分配）',
  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户内稳定模板编码',
  `template_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板分类编码',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板说明',
  `availability_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板可用性',
  `current_published_revision_id` bigint DEFAULT NULL COMMENT '当前已发布修订ID',
  `version` int NOT NULL DEFAULT '0' COMMENT '元数据乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_dynamic_form_template_code` (`tenant_id`,`template_code`),
  UNIQUE KEY `uk_plt_dynamic_form_template_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_dynamic_form_template_selection` (`tenant_id`,`availability_code`,`template_name`,`id`),
  KEY `idx_plt_dynamic_form_template_published` (`tenant_id`,`current_published_revision_id`),
  KEY `idx_plt_dynamic_form_template_published_fk` (`tenant_id`,`current_published_revision_id`,`id`),
  CONSTRAINT `chk_plt_dynamic_form_template_availability` CHECK ((`availability_code` in (_utf8mb4'ENABLED',_utf8mb4'DISABLED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM动态表单模板身份';

CREATE TABLE `plt_dynamic_form_template_revision` (
  `id` bigint NOT NULL COMMENT '模板修订ID（应用分配）',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `revision_no` int NOT NULL COMMENT '模板内修订号',
  `status_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修订状态',
  `draft_marker` tinyint DEFAULT NULL COMMENT '当前草稿唯一标记',
  `source_revision_id` bigint DEFAULT NULL COMMENT '复制来源修订ID',
  `form_conf_json` json NOT NULL COMMENT 'FormCreate配置对象',
  `form_rules_json` json NOT NULL COMMENT 'FormCreate规则数组',
  `engine_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渲染引擎编码',
  `designer_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设计器版本',
  `renderer_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渲染器版本',
  `published_by` bigint DEFAULT NULL COMMENT '发布人',
  `published_at` datetime DEFAULT NULL COMMENT '发布时间',
  `version` int NOT NULL DEFAULT '0' COMMENT '修订乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_dynamic_form_revision_no` (`tenant_id`,`template_id`,`revision_no`),
  UNIQUE KEY `uk_plt_dynamic_form_revision_tenant_row` (`tenant_id`,`id`,`template_id`),
  UNIQUE KEY `uk_plt_dynamic_form_revision_draft` (`tenant_id`,`template_id`,`draft_marker`),
  KEY `idx_plt_dynamic_form_revision_status` (`tenant_id`,`template_id`,`status_code`,`revision_no`,`id`),
  KEY `idx_plt_dynamic_form_revision_source` (`tenant_id`,`source_revision_id`,`template_id`),
  CONSTRAINT `fk_plt_dynamic_form_revision_template` FOREIGN KEY (`tenant_id`, `template_id`) REFERENCES `plt_dynamic_form_template` (`tenant_id`, `id`),
  CONSTRAINT `chk_plt_dynamic_form_revision_draft_marker` CHECK ((((`status_code` = _utf8mb4'DRAFT') and (`draft_marker` = 1)) or ((`status_code` = _utf8mb4'PUBLISHED') and (`draft_marker` is null)))),
  CONSTRAINT `chk_plt_dynamic_form_revision_json` CHECK (((json_type(`form_conf_json`) = _utf8mb4'OBJECT') and (json_type(`form_rules_json`) = _utf8mb4'ARRAY'))),
  CONSTRAINT `chk_plt_dynamic_form_revision_number` CHECK ((`revision_no` > 0)),
  CONSTRAINT `chk_plt_dynamic_form_revision_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PUBLISHED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM动态表单不可变修订';

CREATE TABLE `plt_entity_extension_definition` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `revision_no` int NOT NULL,
  `source_form_revision_id` bigint DEFAULT NULL,
  `fields_json` json NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_entity_extension_definition` (`tenant_id`,`owner_module`,`entity_type`,`revision_no`),
  UNIQUE KEY `uk_entity_definition_source` (`tenant_id`,`owner_module`,`entity_type`,`source_form_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_entity_extension_value` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint NOT NULL,
  `revision_id` bigint NOT NULL DEFAULT '0' COMMENT '0=current; positive=Owner history record ID',
  `definition_revision_id` bigint NOT NULL,
  `values_json` json NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_entity_extension_target` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`revision_id`),
  KEY `fk_extension_definition` (`definition_revision_id`),
  CONSTRAINT `fk_extension_definition` FOREIGN KEY (`definition_revision_id`) REFERENCES `plt_entity_extension_definition` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_entity_form_binding` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint NOT NULL,
  `revision_id` bigint NOT NULL DEFAULT '0' COMMENT '0=current; positive=Owner history record ID',
  `form_revision_id` bigint NOT NULL,
  `extension_definition_revision_id` bigint DEFAULT NULL,
  `field_bindings_json` json NOT NULL COMMENT 'Control field key to stable business/extension field code',
  `version` int NOT NULL DEFAULT '1',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_entity_form_target` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `plt_export_audit` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `export_task_id` bigint NOT NULL,
  `audit_sequence` int NOT NULL,
  `action_code` varchar(32) NOT NULL,
  `actor_user_id` bigint NOT NULL,
  `detail_snapshot` json NOT NULL,
  `occurred_at` datetime(3) NOT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_export_audit_sequence` (`tenant_id`,`export_task_id`,`audit_sequence`),
  CONSTRAINT `chk_plt_export_audit_action` CHECK ((`action_code` in (_utf8mb4'REQUESTED',_utf8mb4'GENERATION_STARTED',_utf8mb4'SUCCEEDED',_utf8mb4'FAILED',_utf8mb4'REJECTED',_utf8mb4'RETRY_REQUESTED',_utf8mb4'DOWNLOADED',_utf8mb4'EXPIRED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLT统一业务导出永久审计';

CREATE TABLE `plt_export_task` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `owner_context` varchar(32) NOT NULL,
  `export_type` varchar(64) NOT NULL,
  `operation_id` varchar(128) NOT NULL,
  `request_digest` char(64) NOT NULL,
  `actor_user_id` bigint NOT NULL,
  `filter_snapshot` json NOT NULL,
  `scope_snapshot` json NOT NULL,
  `requested_fields_snapshot` json NOT NULL,
  `include_files` bit(1) NOT NULL,
  `scope_version` bigint NOT NULL,
  `task_status` varchar(32) NOT NULL,
  `result_count` bigint DEFAULT NULL,
  `artifact_id` bigint DEFAULT NULL,
  `file_version_no` int DEFAULT NULL,
  `reference_key` varchar(128) DEFAULT NULL,
  `artifact_version` int DEFAULT NULL,
  `reference_version` int DEFAULT NULL,
  `availability_version` int DEFAULT NULL,
  `file_hash` char(64) DEFAULT NULL,
  `expires_at` datetime(3) DEFAULT NULL,
  `failure_code` varchar(64) DEFAULT NULL,
  `failure_retryable` bit(1) DEFAULT NULL,
  `retry_count` int NOT NULL DEFAULT '0',
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_export_operation` (`tenant_id`,`owner_context`,`export_type`,`actor_user_id`,`operation_id`),
  KEY `idx_plt_export_due` (`tenant_id`,`task_status`,`create_time`),
  CONSTRAINT `chk_plt_export_failure` CHECK ((((`task_status` = _utf8mb4'FAILED') and (`failure_code` is not null) and (`failure_retryable` is not null)) or ((`task_status` <> _utf8mb4'FAILED') and (`failure_code` is null) and (`failure_retryable` is null)))),
  CONSTRAINT `chk_plt_export_file_fact` CHECK ((((`artifact_id` is null) and (`file_version_no` is null) and (`reference_key` is null) and (`artifact_version` is null) and (`reference_version` is null) and (`availability_version` is null) and (`file_hash` is null)) or ((`artifact_id` is not null) and (`file_version_no` is not null) and (`reference_key` is not null) and (`artifact_version` is not null) and (`reference_version` is not null) and (`availability_version` is not null) and (`file_hash` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLT统一业务导出任务';

CREATE TABLE `plt_external_key_mapping` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `batch_id` bigint NOT NULL COMMENT '批次ID',
  `source_record_id` bigint NOT NULL,
  `result_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_table` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标表',
  `target_id` bigint DEFAULT NULL COMMENT '目标ID',
  `target_role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务角色',
  `target_sequence` int DEFAULT NULL COMMENT '目标顺序',
  `result_key` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`result_type` = _utf8mb4'RETAINED') then _utf8mb4'RETAINED' else concat(`target_role`,_utf8mb4':',`target_sequence`) end)) STORED,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_external_mapping_result` (`tenant_id`,`source_record_id`,`result_key`),
  KEY `idx_plt_external_mapping_batch` (`tenant_id`,`batch_id`,`source_record_id`),
  CONSTRAINT `ck_plt_external_mapping_union` CHECK ((((`result_type` = _utf8mb4'MAPPED') and (`target_context` is not null) and (`target_object_type` is not null) and (`target_table` is not null) and (`target_id` > 0) and (`target_role` is not null) and (`target_sequence` >= 0)) or ((`result_type` = _utf8mb4'RETAINED') and (`target_context` is null) and (`target_object_type` is null) and (`target_table` is null) and (`target_id` is null) and (`target_role` is null) and (`target_sequence` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLT迁移外部键映射或留存分类';

CREATE TABLE `plt_file_access_grant` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '短时访问授权ID',
  `artifact_id` bigint NOT NULL COMMENT '文件Artifact稳定ID',
  `file_version_no` int unsigned NOT NULL COMMENT '文件版本号',
  `subject_user_id` bigint NOT NULL COMMENT '授权用户ID',
  `operation_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '授权操作',
  `business_scope_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务范围事实摘要',
  `token_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '不可逆令牌摘要',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '授权状态',
  `expires_at` datetime(3) NOT NULL COMMENT '授权失效时间',
  `created_at` datetime(3) NOT NULL COMMENT '创建时间',
  `consumed_at` datetime(3) DEFAULT NULL COMMENT '消费时间',
  `revoked_at` datetime(3) DEFAULT NULL COMMENT '撤销时间',
  `revoked_by` bigint DEFAULT NULL COMMENT '撤销操作人',
  `revoke_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '撤销原因',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_file_access_token_digest` (`token_digest`),
  UNIQUE KEY `uk_plt_file_access_grant_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_file_access_grant_subject` (`tenant_id`,`subject_user_id`,`status_code`,`expires_at`,`id`),
  KEY `idx_plt_file_access_grant_artifact` (`tenant_id`,`artifact_id`,`file_version_no`,`status_code`,`id`),
  CONSTRAINT `fk_plt_file_access_grant_version` FOREIGN KEY (`tenant_id`, `artifact_id`, `file_version_no`) REFERENCES `plt_file_version` (`tenant_id`, `artifact_id`, `version_no`),
  CONSTRAINT `chk_plt_file_access_grant_operation` CHECK ((`operation_code` in (_utf8mb4'DOWNLOAD',_utf8mb4'PREVIEW'))),
  CONSTRAINT `chk_plt_file_access_grant_status` CHECK ((`status_code` in (_utf8mb4'ACTIVE',_utf8mb4'CONSUMED',_utf8mb4'REVOKED',_utf8mb4'EXPIRED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM文件短时访问授权';

CREATE TABLE `plt_file_archive_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件归档事实ID',
  `artifact_id` bigint NOT NULL COMMENT '文件Artifact稳定ID',
  `file_version_no` int unsigned NOT NULL COMMENT '文件版本号',
  `archive_batch_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归档批次ID',
  `business_decision_ref` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务决定稳定引用',
  `archived_by` bigint NOT NULL COMMENT '归档操作人',
  `archived_at` datetime(3) NOT NULL COMMENT '归档时间',
  `archive_note` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '归档说明',
  `created_at` datetime(3) NOT NULL COMMENT '记录创建时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_file_archive_fact` (`tenant_id`,`archive_batch_id`,`artifact_id`,`file_version_no`),
  UNIQUE KEY `uk_plt_file_archive_record_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_file_archive_record_artifact` (`tenant_id`,`artifact_id`,`file_version_no`,`archived_at`,`id`),
  CONSTRAINT `fk_plt_file_archive_record_version` FOREIGN KEY (`tenant_id`, `artifact_id`, `file_version_no`) REFERENCES `plt_file_version` (`tenant_id`, `artifact_id`, `version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM文件版本追加归档事实';

CREATE TABLE `plt_file_artifact` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件Artifact稳定ID',
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件显示名称',
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件类别编码',
  `owner_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务Owner Context',
  `lifecycle_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Artifact生命周期',
  `invalid_reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失效原因编码',
  `invalid_reason_detail` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失效原因说明',
  `invalidated_at` datetime(3) DEFAULT NULL COMMENT '失效时间',
  `invalidated_by` bigint DEFAULT NULL COMMENT '失效操作人',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_file_artifact_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_file_artifact_owner_category` (`tenant_id`,`owner_context`,`category_code`,`id`),
  KEY `idx_plt_file_artifact_creator` (`tenant_id`,`creator`,`create_time`,`id`),
  CONSTRAINT `chk_plt_file_artifact_lifecycle` CHECK ((`lifecycle_status_code` in (_utf8mb4'DRAFT',_utf8mb4'ACTIVE',_utf8mb4'INVALIDATED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM文件Artifact稳定身份';

CREATE TABLE `plt_file_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件业务引用ID',
  `owner_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务Owner Context',
  `object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务对象类型',
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务对象稳定ID',
  `purpose_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务用途编码',
  `reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用途内稳定引用槽位',
  `artifact_id` bigint NOT NULL COMMENT '文件Artifact稳定ID',
  `file_version_no` int unsigned NOT NULL COMMENT '冻结文件版本号',
  `sensitivity_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '敏感级别编码',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '引用生命周期状态',
  `scope_version` bigint unsigned NOT NULL COMMENT '业务范围事实版本',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `detached_at` datetime(3) DEFAULT NULL COMMENT '解绑时间',
  `detached_by` bigint DEFAULT NULL COMMENT '解绑操作人',
  `detached_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '解绑原因',
  `archived_at` datetime(3) DEFAULT NULL COMMENT '归档时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_file_reference_slot` (`tenant_id`,`owner_context`,`object_type`,`object_id`,`purpose_code`,`reference_key`),
  UNIQUE KEY `uk_plt_file_reference_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_file_reference_artifact` (`tenant_id`,`artifact_id`,`file_version_no`,`status_code`,`id`),
  KEY `idx_plt_file_reference_object` (`tenant_id`,`owner_context`,`object_type`,`object_id`,`status_code`,`id`),
  CONSTRAINT `fk_plt_file_reference_artifact` FOREIGN KEY (`tenant_id`, `artifact_id`) REFERENCES `plt_file_artifact` (`tenant_id`, `id`),
  CONSTRAINT `fk_plt_file_reference_version` FOREIGN KEY (`tenant_id`, `artifact_id`, `file_version_no`) REFERENCES `plt_file_version` (`tenant_id`, `artifact_id`, `version_no`),
  CONSTRAINT `chk_plt_file_reference_key` CHECK ((char_length(trim(`reference_key`)) > 0)),
  CONSTRAINT `chk_plt_file_reference_status` CHECK ((`status_code` in (_utf8mb4'ACTIVE',_utf8mb4'DETACHED',_utf8mb4'ARCHIVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM业务对象固定版本引用';

CREATE TABLE `plt_file_upload_session` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '上传会话ID',
  `mode_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上传模式',
  `owner_context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务Owner Context',
  `object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务对象类型',
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务对象稳定ID',
  `purpose_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务用途编码',
  `reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用途内稳定引用槽位',
  `file_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名称',
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件类别编码',
  `declared_size_bytes` bigint unsigned NOT NULL COMMENT '客户端声明大小',
  `declared_media_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户端声明媒体类型',
  `storage_operation_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '技术存储幂等操作ID',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上传会话状态',
  `scope_version` bigint unsigned NOT NULL COMMENT '业务范围事实版本',
  `expires_at` datetime(3) NOT NULL COMMENT '会话失效时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `artifact_id` bigint DEFAULT NULL COMMENT '目标Artifact ID',
  `reference_id` bigint DEFAULT NULL COMMENT '目标引用ID',
  `expected_reference_version` int unsigned DEFAULT NULL COMMENT '期望引用版本',
  `client_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端摘要',
  `actual_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务端摘要',
  `completed_file_version_no` int unsigned DEFAULT NULL COMMENT '完成的文件版本号',
  `registered_infra_file_id` bigint DEFAULT NULL COMMENT '已登记INFRA技术文件ID',
  `failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败码',
  `failure_detail` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败说明',
  `completed_at` datetime(3) DEFAULT NULL COMMENT '完成时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_file_upload_storage_operation` (`tenant_id`,`storage_operation_id`),
  UNIQUE KEY `uk_plt_file_upload_session_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_file_upload_session_expiry` (`tenant_id`,`status_code`,`expires_at`,`id`),
  KEY `idx_plt_file_upload_session_object` (`tenant_id`,`owner_context`,`object_type`,`object_id`,`create_time`,`id`),
  CONSTRAINT `chk_plt_file_upload_reference_key` CHECK ((char_length(trim(`reference_key`)) > 0)),
  CONSTRAINT `chk_plt_file_upload_session_mode` CHECK ((`mode_code` in (_utf8mb4'CREATE_ARTIFACT',_utf8mb4'ADD_VERSION'))),
  CONSTRAINT `chk_plt_file_upload_session_status` CHECK ((`status_code` in (_utf8mb4'INITIALIZED',_utf8mb4'VALIDATING',_utf8mb4'COMPLETED',_utf8mb4'FAILED_RETRYABLE',_utf8mb4'FAILED_FINAL',_utf8mb4'EXPIRED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM文件上传会话';

CREATE TABLE `plt_file_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件版本记录ID',
  `artifact_id` bigint NOT NULL COMMENT '文件Artifact稳定ID',
  `version_no` int unsigned NOT NULL COMMENT 'Artifact内版本号',
  `infra_file_id` bigint NOT NULL COMMENT 'INFRA技术文件记录ID',
  `availability_version` int unsigned NOT NULL DEFAULT '0' COMMENT '可用性事实版本',
  `sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端计算的SHA-256',
  `size_bytes` bigint unsigned NOT NULL COMMENT '文件大小（字节）',
  `declared_media_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '声明媒体类型',
  `detected_media_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端检测媒体类型',
  `scan_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '安全扫描状态',
  `scan_provider_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扫描Provider编码',
  `scan_provider_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扫描Provider版本',
  `availability_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '版本可用性状态',
  `unavailable_reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '不可用原因编码',
  `unavailable_at` datetime(3) DEFAULT NULL COMMENT '不可用时间',
  `version_note` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本说明',
  `created_by` bigint NOT NULL COMMENT '创建人用户ID',
  `created_at` datetime(3) NOT NULL COMMENT '创建时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_file_version_artifact_no` (`tenant_id`,`artifact_id`,`version_no`),
  UNIQUE KEY `uk_plt_file_version_infra_file` (`infra_file_id`),
  UNIQUE KEY `uk_plt_file_version_tenant_row` (`tenant_id`,`id`),
  KEY `idx_plt_file_version_created` (`tenant_id`,`artifact_id`,`created_at`,`id`),
  KEY `idx_plt_file_version_availability` (`tenant_id`,`availability_status_code`,`id`),
  CONSTRAINT `fk_plt_file_version_artifact` FOREIGN KEY (`tenant_id`, `artifact_id`) REFERENCES `plt_file_artifact` (`tenant_id`, `id`),
  CONSTRAINT `chk_plt_file_version_availability` CHECK ((`availability_status_code` in (_utf8mb4'AVAILABLE',_utf8mb4'UNAVAILABLE',_utf8mb4'INVALIDATED'))),
  CONSTRAINT `chk_plt_file_version_scan` CHECK ((`scan_status_code` in (_utf8mb4'PASSED',_utf8mb4'SKIPPED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLATFORM不可变文件版本';

CREATE TABLE `plt_form_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例编号（如 FI-2026-001）',
  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `template_id` bigint NOT NULL COMMENT '关联模板ID',
  `template_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板快照JSON（版本固定到实例）',
  `form_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '填报数据JSON',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实例名称',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0待填/1已填/2已提交/3已审核/4已驳回',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审核人',
  `approve_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核意见',
  `approve_time` datetime DEFAULT NULL COMMENT '审核时间',
  `filler_user_id` bigint DEFAULT NULL COMMENT '填报人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_form_instance_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_form_instance_project` (`project_id`),
  KEY `idx_pms_eng_form_instance_template` (`template_id`),
  KEY `idx_pms_eng_form_instance_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='准备数据表单实例';

CREATE TABLE `plt_form_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板编号（如 FT-2026-001）',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `product_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品类型（联动条件）',
  `conf` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单配置JSON（form-create conf）',
  `fields` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单字段JSON（form-create fields）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板说明',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已发布/2已停用',
  `version` int NOT NULL DEFAULT '0' COMMENT '模板版本号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_form_template_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_form_template_product` (`product_type`),
  KEY `idx_pms_eng_form_template_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='准备数据表单模板';

CREATE TABLE `plt_idempotency_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scope_code` varchar(128) NOT NULL,
  `actor_id` bigint NOT NULL,
  `idempotency_key` varchar(128) NOT NULL,
  `request_digest` char(64) NOT NULL,
  `status` varchar(32) NOT NULL,
  `resource_type` varchar(64) DEFAULT NULL,
  `resource_key` varchar(128) DEFAULT NULL,
  `response_payload` json DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_idempotency_scope` (`tenant_id`,`scope_code`,`actor_id`,`idempotency_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='平台命令幂等记录';

CREATE TABLE `plt_migration_batch` (
  `id` bigint NOT NULL,
  `owner_context_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `purpose_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `release_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_table` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `manifest_schema_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `expected_row_count` bigint NOT NULL,
  `content_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `exported_at` datetime(3) NOT NULL,
  `previous_batch_id` bigint DEFAULT NULL,
  `previous_issue_id` bigint DEFAULT NULL,
  `batch_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_count` bigint NOT NULL,
  `mapped_count` bigint NOT NULL,
  `issue_count` bigint NOT NULL,
  `retained_count` bigint NOT NULL,
  `failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rule_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_migration_batch_identity` (`tenant_id`,`owner_context_code`,`purpose_code`,`release_id`,`source_system`,`source_table`),
  KEY `idx_plt_migration_batch_claim` (`tenant_id`,`owner_context_code`,`purpose_code`,`batch_status`,`create_time`,`id`),
  CONSTRAINT `ck_plt_migration_batch_counts` CHECK (((`expected_row_count` >= 0) and (`source_count` >= 0) and (`mapped_count` >= 0) and (`issue_count` >= 0) and (`retained_count` >= 0))),
  CONSTRAINT `ck_plt_migration_batch_failure` CHECK ((((`batch_status` = _utf8mb4'FAILED') and (`failure_code` in (_utf8mb4'MANIFEST_STRUCTURE_INVALID',_utf8mb4'MANIFEST_ROW_COUNT_MISMATCH',_utf8mb4'MANIFEST_SCHEMA_VERSION_MISMATCH',_utf8mb4'MANIFEST_CONTENT_SHA256_MISMATCH',_utf8mb4'SOURCE_PAYLOAD_INVALID',_utf8mb4'SOURCE_RECORD_CONFLICT'))) or ((`batch_status` <> _utf8mb4'FAILED') and (`failure_code` is null)))),
  CONSTRAINT `ck_plt_migration_batch_final_counts` CHECK ((((`batch_status` = _utf8mb4'COMPLETED') and (`source_count` = ((`mapped_count` + `issue_count`) + `retained_count`)) and (`rule_version` is not null)) or ((`batch_status` <> _utf8mb4'COMPLETED') and (`mapped_count` = 0) and (`issue_count` = 0) and (`retained_count` = 0) and (`rule_version` is null)))),
  CONSTRAINT `ck_plt_migration_batch_status` CHECK ((`batch_status` in (_utf8mb4'IMPORTING',_utf8mb4'STAGED_READY',_utf8mb4'RECONCILING',_utf8mb4'COMPLETED',_utf8mb4'FAILED'))),
  CONSTRAINT `ck_plt_migration_batch_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLT迁移证据批次';

CREATE TABLE `plt_migration_issue` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `batch_id` bigint NOT NULL COMMENT '批次ID',
  `source_record_id` bigint NOT NULL,
  `issue_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `issue_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型编码',
  `raw_business_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始业务键',
  `candidate_target_ids` json NOT NULL COMMENT '目标记录ID数组JSON',
  `raw_payload` json DEFAULT NULL COMMENT '原始字段和值JSON',
  `issue_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `resolver_user_id` bigint DEFAULT NULL,
  `rule_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_result` json DEFAULT NULL,
  `resolved_at` datetime(3) DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_migration_issue_key` (`tenant_id`,`source_record_id`,`issue_key`),
  KEY `idx_plt_migration_issue_batch` (`tenant_id`,`batch_id`,`source_record_id`),
  CONSTRAINT `ck_plt_migration_issue_resolution` CHECK ((((`issue_status` = _utf8mb4'OPEN') and (`resolver_user_id` is null) and (`rule_version` is null) and (`target_result` is null) and (`resolved_at` is null)) or ((`issue_status` = _utf8mb4'CLOSED') and (`resolver_user_id` > 0) and (`rule_version` is not null) and (`target_result` is not null) and (`resolved_at` is not null)))),
  CONSTRAINT `ck_plt_migration_issue_status` CHECK ((`issue_status` in (_utf8mb4'OPEN',_utf8mb4'CLOSED'))),
  CONSTRAINT `ck_plt_migration_issue_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLT迁移问题与追加式关闭证据';

CREATE TABLE `plt_migration_source_record` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `batch_id` bigint NOT NULL COMMENT '批次ID',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_table` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统物理表名',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_business_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源记录可读业务键',
  `source_payload` json NOT NULL COMMENT '来源记录原值JSON',
  `source_checksum` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源记录SHA-256校验值',
  `extracted_at` datetime(3) NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_migration_source_identity` (`tenant_id`,`batch_id`,`source_system`,`source_table`,`source_record_key`),
  KEY `idx_plt_migration_source_cursor` (`tenant_id`,`batch_id`,`id`),
  KEY `idx_plt_migration_global_source_identity` (`tenant_id`,`source_system`,`source_table`,`source_record_key`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PLT不可变迁移来源行';

CREATE TABLE `plt_operation_audit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `operation_code` varchar(128) NOT NULL,
  `aggregate_type` varchar(64) NOT NULL,
  `aggregate_key` varchar(128) DEFAULT NULL,
  `actor_id` bigint NOT NULL,
  `correlation_id` varchar(128) NOT NULL,
  `idempotency_key_digest` char(64) DEFAULT NULL,
  `result_code` varchar(32) NOT NULL,
  `detail_snapshot` json NOT NULL,
  `occurred_at` datetime(3) NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_plt_operation_audit_aggregate` (`tenant_id`,`aggregate_type`,`aggregate_key`,`occurred_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='平台操作审计';

CREATE TABLE `plt_outbox_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` varchar(64) NOT NULL,
  `event_type` varchar(128) NOT NULL,
  `aggregate_type` varchar(64) NOT NULL,
  `aggregate_key` varchar(128) NOT NULL,
  `payload` json NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `occurred_at` datetime(3) NOT NULL,
  `next_retry_time` datetime(3) DEFAULT NULL,
  `retry_count` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_outbox_event_id` (`event_id`),
  KEY `idx_plt_outbox_dispatch` (`status`,`next_retry_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='平台事务Outbox事件';

CREATE TABLE `pms_bind_approval_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `instance_ref` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本引擎实例标识',
  `attempt_hint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发起尝试幂等键（重放锚点）',
  `purpose` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批用途',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态 PENDING/APPROVED/REJECTED/WITHDRAWN',
  `decision_comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '决定意见',
  `decided_time` datetime(3) DEFAULT NULL COMMENT '决定时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_bind_approval_instance` (`tenant_id`,`instance_ref`),
  KEY `idx_pms_bind_approval_attempt` (`tenant_id`,`attempt_hint`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绑定-本地审批引擎实例';

CREATE TABLE `pms_bind_event_checkpoint` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '已处理完的业务事件身份',
  `processed_at` datetime(3) NOT NULL COMMENT '处理完成时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bind_event_ckpt` (`tenant_id`,`event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绑定-事件驱动消费检查点';

CREATE TABLE `pms_bind_evented_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `definition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '过程定义编码',
  `definition_version` int NOT NULL COMMENT '消费的定义发布版本',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件来源对象所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件来源对象实体类型',
  `entity_id` bigint NOT NULL COMMENT '事件来源对象实体ID',
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消费的业务事件身份',
  `verdict` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '条件判定 SATISFIED/UNSATISFIED/UNKNOWN',
  `result_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '满足条件形成的结果身份',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bind_evented_ev_def` (`tenant_id`,`event_id`,`definition_code`),
  KEY `idx_bind_evented_def` (`tenant_id`,`definition_code`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绑定-事件驱动执行实例';

CREATE TABLE `pms_bind_inline_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `definition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '过程定义编码',
  `definition_version` int NOT NULL COMMENT '消费的定义发布版本',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象实体类型',
  `entity_id` bigint NOT NULL COMMENT '对象实体ID',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本次同步执行的幂等键',
  `verdict` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '条件判定 SATISFIED/UNSATISFIED/UNKNOWN',
  `result_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '满足条件形成的结果身份',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bind_inline_idem` (`tenant_id`,`idempotency_key`),
  KEY `idx_bind_inline_def` (`tenant_id`,`definition_code`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绑定-同步执行实例';

CREATE TABLE `pms_plat_business_result` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `result_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务结果类型',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象实体类型',
  `entity_id` bigint NOT NULL COMMENT '对象实体ID',
  `result_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结果身份',
  `semantics` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结果语义 NEW_RESULT 等',
  `formation_basis` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '形成依据（事件ID/执行引用），不为字段修改时间',
  `formed_by_backend` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '形成结果的后端标识',
  `formed_at` datetime(3) NOT NULL COMMENT '形成时间',
  `valid` bit(1) NOT NULL DEFAULT b'1' COMMENT '有效性',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_biz_result_basis` (`tenant_id`,`result_type`,`owner_module`,`entity_type`,`entity_id`,`formation_basis`),
  KEY `idx_pms_biz_result_object` (`tenant_id`,`result_type`,`owner_module`,`entity_type`,`entity_id`,`valid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一业务结果登记';

CREATE TABLE `pms_plat_demo_ticket_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '修订主键',
  `summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '摘要',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '详情',
  `priority` int DEFAULT NULL COMMENT '优先级',
  `handled` bit(1) DEFAULT NULL COMMENT '已受理',
  `entity_id` bigint NOT NULL COMMENT '所属业务实体ID（演示工单主键）',
  `revision_no` int NOT NULL COMMENT '修订号（同实体递增，1 起）',
  `source_revision_id` bigint DEFAULT NULL COMMENT '复制来源修订主键（初始修订为空）',
  `base_effective_revision_id` bigint DEFAULT NULL COMMENT '创建基线的生效修订主键',
  `base_entity_version` int DEFAULT NULL COMMENT '创建基线的业务行版本',
  `revision_state` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '修订状态 DRAFT/FROZEN',
  `effective` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否当前生效修订',
  `change_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修订原因',
  `frozen_by` bigint DEFAULT NULL COMMENT '冻结人',
  `frozen_at` datetime(3) DEFAULT NULL COMMENT '冻结时间',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_demo_ticket_revision_no` (`tenant_id`,`entity_id`,`revision_no`),
  KEY `idx_demo_ticket_revision_state` (`tenant_id`,`entity_id`,`revision_state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='演示工单修订（继承式内容历史）';

CREATE TABLE `pms_plat_evidence_impact` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `evidence_id` bigint NOT NULL,
  `result_id` varchar(64) NOT NULL,
  `impact` varchar(32) NOT NULL COMMENT 'RESULT_INVALIDATED 等',
  `detail` varchar(255) DEFAULT NULL,
  `recorded_at` datetime NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_impact_evidence` (`tenant_id`,`evidence_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='执行证据历史影响';

CREATE TABLE `pms_plat_evidence_result_ref` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `evidence_id` bigint NOT NULL,
  `result_id` varchar(64) NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_evidence_result` (`evidence_id`,`result_id`),
  KEY `idx_evidence_result_id` (`tenant_id`,`result_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='执行证据采纳结果引用';

CREATE TABLE `pms_plat_execution_evidence` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_stable_ref` varchar(128) DEFAULT NULL,
  `plan_version` varchar(64) DEFAULT NULL,
  `node_key` varchar(128) NOT NULL,
  `round_no` bigint NOT NULL,
  `rule_version` varchar(64) DEFAULT NULL,
  `decision` varchar(16) NOT NULL,
  `subscription_id` bigint DEFAULT NULL,
  `adopted_fact_refs` json DEFAULT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_evidence_node` (`tenant_id`,`project_stable_ref`,`node_key`,`round_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一模型执行证据';

CREATE TABLE `pms_plat_process_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `definition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定定义编码',
  `definition_version` int NOT NULL DEFAULT '0' COMMENT '发布版本，发布一次递增',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '定义名称',
  `owner_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实体所属模块',
  `entity_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实体类型',
  `entity_stable_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结的实体稳定编码',
  `entity_contract_version` int NOT NULL COMMENT '冻结的实体契约版本',
  `operation_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发的业务操作编码',
  `operation_version` int NOT NULL COMMENT '冻结的操作版本',
  `rule_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则语义编码',
  `rule_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则语义版本',
  `conditions_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '类型化字段条件 JSON',
  `result_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '满足条件后形成的业务结果类型',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/PUBLISHED',
  `published_at` datetime(3) DEFAULT NULL COMMENT '发布时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_proc_def_code_ver` (`tenant_id`,`definition_code`,`definition_version`),
  KEY `idx_pms_proc_def_entity` (`tenant_id`,`owner_module`,`entity_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='中性过程定义';

CREATE TABLE `pms_plat_result_subscription` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `subscription_code` varchar(64) NOT NULL,
  `subscriber_kind` varchar(16) NOT NULL COMMENT '订阅者类型：TASK/STAGE/NODE',
  `subscriber_node_key` varchar(128) NOT NULL,
  `result_type` varchar(128) NOT NULL,
  `owner_module` varchar(64) NOT NULL,
  `entity_type` varchar(64) NOT NULL,
  `expected_object_ids` json DEFAULT NULL COMMENT 'ALL_EXPECTED 必填的期望对象集合',
  `acquisition` varchar(24) NOT NULL COMMENT 'NEW_RESULT/REUSE_EXISTING/PINNED_RESULT',
  `selection` varchar(24) NOT NULL COMMENT 'EXACT_ONE/ANY_MATCHING/ALL_EXPECTED',
  `validity_policy` varchar(24) NOT NULL COMMENT 'ANY/CURRENT_VALID',
  `pinned_result_id` varchar(64) DEFAULT NULL,
  `round_no` bigint NOT NULL DEFAULT '1',
  `formation_baseline` bigint NOT NULL COMMENT '轮次形成序号下界（不含），取建立时结果最大序号',
  `project_stable_ref` varchar(128) DEFAULT NULL COMMENT '建立订阅时冻结的项目稳定引用（证据写入用）',
  `plan_version` varchar(64) DEFAULT NULL COMMENT '建立订阅时冻结的计划版本',
  `rule_version` varchar(64) DEFAULT NULL COMMENT '建立订阅时冻结的规则版本',
  `status` varchar(16) NOT NULL DEFAULT 'COLLECTING' COMMENT 'COLLECTING/SATISFIED/WAITING/AMBIGUOUS/UNAVAILABLE',
  `last_examined` bigint DEFAULT NULL,
  `last_eligible` bigint DEFAULT NULL,
  `missing_objects` json DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_result_subscription_code` (`tenant_id`,`subscription_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一模型结果订阅';

CREATE TABLE `proj_business_result_change` (
  `tenant_id` bigint NOT NULL,
  `channel_id` bigint NOT NULL,
  `sequence_no` bigint NOT NULL,
  `source_event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `notification_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `result_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `formation_marker` tinyint DEFAULT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`channel_id`,`sequence_no`),
  UNIQUE KEY `uk_result_source_event` (`channel_id`,`source_event_id`),
  UNIQUE KEY `uk_result_notification` (`tenant_id`,`notification_id`),
  UNIQUE KEY `uk_result_first_formation` (`channel_id`,`object_id`,`result_id`,`formation_marker`),
  CONSTRAINT `ck_result_formation_marker` CHECK (((`formation_marker` is null) or (`formation_marker` = 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `proj_business_result_channel` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `owner_context` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `entity_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `result_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `committed_sequence` bigint NOT NULL DEFAULT '0',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_result_channel` (`tenant_id`,`project_id`,`owner_context`,`entity_type`,`result_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `proj_delivery_definition_reference` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `owner_revision_id` bigint NOT NULL,
  `reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `target_revision_id` bigint NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pdr_slot` (`tenant_id`,`owner_revision_id`,`reference_key`),
  KEY `idx_pdr_target` (`tenant_id`,`target_revision_id`),
  CONSTRAINT `fk_pdr_source` FOREIGN KEY (`tenant_id`, `owner_revision_id`) REFERENCES `proj_delivery_definition_revision` (`tenant_id`, `id`),
  CONSTRAINT `fk_pdr_target` FOREIGN KEY (`tenant_id`, `target_revision_id`) REFERENCES `proj_delivery_definition_revision` (`tenant_id`, `id`),
  CONSTRAINT `ck_pdr_not_self` CHECK ((`owner_revision_id` <> `target_revision_id`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `proj_delivery_definition_revision` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `definition_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `definition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `revision_no` bigint unsigned NOT NULL,
  `revision_state` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `schema_version` int unsigned NOT NULL,
  `payload` json NOT NULL,
  `published_at` datetime(6) DEFAULT NULL,
  `disabled_at` datetime(6) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pdd_revision` (`tenant_id`,`definition_kind`,`definition_code`,`revision_no`),
  UNIQUE KEY `uk_pdd_tenant_id` (`tenant_id`,`id`),
  CONSTRAINT `ck_pdd_kind` CHECK ((`definition_kind` in (_utf8mb4'STAGE',_utf8mb4'TASK',_utf8mb4'DELIVERABLE',_utf8mb4'WORK_BINDING',_utf8mb4'COMPLETION_RULE',_utf8mb4'PERMISSION_POLICY',_utf8mb4'GATE',_utf8mb4'MILESTONE'))),
  CONSTRAINT `ck_pdd_payload` CHECK ((json_type(`payload`) = _utf8mb4'OBJECT')),
  CONSTRAINT `ck_pdd_published` CHECK ((((`revision_state` = _utf8mb4'DRAFT') and (`published_at` is null)) or ((`revision_state` = _utf8mb4'PUBLISHED') and (`published_at` is not null)))),
  CONSTRAINT `ck_pdd_state` CHECK ((`revision_state` in (_utf8mb4'DRAFT',_utf8mb4'PUBLISHED'))),
  CONSTRAINT `ck_pdd_version` CHECK (((`revision_no` > 0) and (`schema_version` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `proj_idempotency_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '幂等记录ID',
  `command` varchar(64) NOT NULL COMMENT '命令标识（如 ProjectCreate）',
  `actor_id` bigint NOT NULL COMMENT '操作者用户ID',
  `idempotency_key` varchar(128) NOT NULL COMMENT '幂等键（Header Idempotency-Key）',
  `request_digest` char(64) NOT NULL COMMENT '请求体 SHA-256 摘要（同键异摘要拒绝）',
  `response_payload` text COMMENT '首次成功响应载荷（重放原样返回）',
  `status` varchar(16) NOT NULL DEFAULT 'COMPLETED' COMMENT '记录状态：COMPLETED/FAILED',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_idempotency` (`tenant_id`,`command`,`actor_id`,`idempotency_key`),
  KEY `idx_proj_idempotency_create` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='API 命令幂等记录';

CREATE TABLE `proj_legacy_detail_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `snapshot_id` bigint NOT NULL,
  `domain_code` varchar(48) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_table` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_key` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `parent_domain` varchar(48) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `parent_source_key` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `source_updated_at` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `checksum` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `redacted_fields_json` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_legacy_detail_record` (`tenant_id`,`snapshot_id`,`domain_code`,`source_key`),
  KEY `idx_legacy_detail_parent` (`tenant_id`,`snapshot_id`,`parent_domain`,`parent_source_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_legacy_detail_snapshot` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `source_id` bigint NOT NULL,
  `batch_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `checksum` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_read_at` datetime(3) NOT NULL,
  `captured_at` datetime(3) NOT NULL,
  `operator_user_id` bigint NOT NULL,
  `domain_counts_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `record_count` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_legacy_detail_batch` (`tenant_id`,`source_id`,`batch_key`),
  KEY `idx_legacy_detail_snapshot_source` (`tenant_id`,`source_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_legacy_detail_source` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_project_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_contract_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `current_snapshot_id` bigint DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_legacy_detail_identity` (`tenant_id`,`source_system`,`source_project_key`),
  KEY `idx_legacy_detail_project` (`tenant_id`,`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_node_overdue_completion` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `node_kind` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_id` bigint NOT NULL,
  `node_version` int NOT NULL,
  `node_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan_end_time` datetime(3) DEFAULT NULL,
  `acceptance_time` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) NOT NULL,
  `work_overdue` bit(1) NOT NULL,
  `acceptance_overdue` bit(1) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_node_completion` (`tenant_id`,`node_kind`,`node_id`,`node_version`),
  KEY `idx_project_completion` (`tenant_id`,`project_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PROJ阶段任务完成时的不可变超期事实，仅追加，不回填旧历史';

CREATE TABLE `proj_payment_acceptance_binding` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `node_type` varchar(16) NOT NULL,
  `node_id` bigint NOT NULL,
  `source_owner` varchar(96) NOT NULL,
  `source_key` varchar(128) NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT 'payment_plan_sync',
  `updater` varchar(64) NOT NULL DEFAULT 'payment_plan_sync',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payment_acceptance_node` (`tenant_id`,`node_type`,`node_id`),
  UNIQUE KEY `uk_payment_acceptance_source` (`tenant_id`,`source_owner`,`source_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回款计划验收输入来源绑定';

CREATE TABLE `proj_preparation_confirmation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `form_revision_id` bigint NOT NULL,
  `form_revision_version` int NOT NULL,
  `form_snapshot_json` json NOT NULL,
  `values_json` json NOT NULL,
  `submitted_by` bigint NOT NULL,
  `submitted_at` datetime NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_preparation_confirmation` (`tenant_id`,`project_id`,`revision_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目经理工前确认不可变历史';

CREATE TABLE `proj_project` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目主档编号',
  `project_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目编码',
  `code_root_id` bigint NOT NULL COMMENT '创建时命名空间根项目ID',
  `project_sequence` int unsigned NOT NULL DEFAULT '0' COMMENT '永久流水号：0表示独立命名空间',
  `code_rule_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'V1' COMMENT '项目编码生成规则版本',
  `project_name` varchar(255) DEFAULT NULL COMMENT '项目名称',
  `parent_id` bigint DEFAULT NULL COMMENT '父记录ID',
  `root_id` bigint NOT NULL COMMENT '项目树根节点项目ID',
  `tree_path` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目祖先路径缓存',
  `tree_depth` int unsigned NOT NULL DEFAULT '0' COMMENT '节点层级深度缓存：根节点为0',
  `tree_sort` int NOT NULL DEFAULT '0' COMMENT '排序值',
  `business_level_code` varchar(64) DEFAULT NULL COMMENT '业务层级标签编码（与结构层级 tree_depth 分离；字典 pms_project_business_level）',
  `business_level_name` varchar(128) DEFAULT NULL COMMENT '业务层级标签名称（拆分/移动时可指定）',
  `customer_id` bigint DEFAULT NULL COMMENT '直接客户主档ID',
  `customer_code` varchar(64) DEFAULT NULL COMMENT '客户编码',
  `customer_name` varchar(255) DEFAULT NULL COMMENT '客户名称',
  `manager_id` bigint DEFAULT NULL COMMENT '主负责人用户ID',
  `manager_employee_no` varchar(64) DEFAULT NULL COMMENT '负责人工号',
  `manager_name` varchar(128) DEFAULT NULL COMMENT '负责人姓名',
  `company_id` bigint DEFAULT NULL COMMENT '主责公司ID',
  `company_code` varchar(64) DEFAULT NULL COMMENT '公司编码',
  `company_name` varchar(255) DEFAULT NULL COMMENT '公司名称',
  `department_id` bigint DEFAULT NULL COMMENT '主责部门ID',
  `department_code` varchar(64) DEFAULT NULL COMMENT '部门编码',
  `department_name` varchar(255) DEFAULT NULL COMMENT '部门名称',
  `project_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STANDARD' COMMENT '项目类型编码',
  `signing_method` varchar(64) DEFAULT NULL COMMENT '签约方式（字典 pms_signing_method；SDS 08 四维分列，前向扩列）',
  `project_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目分类',
  `implementation_mode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实施模式编码',
  `major_project_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '重大项目级别',
  `market_code` varchar(64) DEFAULT NULL COMMENT '市场部编码',
  `market_name` varchar(255) DEFAULT NULL COMMENT '市场部名称',
  `system_code` varchar(64) DEFAULT NULL COMMENT '系统部编码',
  `system_name` varchar(255) DEFAULT NULL COMMENT '系统部名称',
  `expend_code` varchar(64) DEFAULT NULL COMMENT '拓展部编码',
  `expend_name` varchar(255) DEFAULT NULL COMMENT '拓展部名称',
  `industry_code` varchar(64) DEFAULT NULL COMMENT '行业编码',
  `industry_name` varchar(255) DEFAULT NULL COMMENT '行业名称',
  `customer_project_name` varchar(255) DEFAULT NULL COMMENT '客户项目名称',
  `sales_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '销售类型编码',
  `business_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型编码',
  `service_level_code` varchar(64) DEFAULT NULL COMMENT '服务级别编码',
  `not_track_reason` varchar(1024) DEFAULT NULL COMMENT '不跟踪原因',
  `contract_no` varchar(128) DEFAULT NULL COMMENT '手工登记合同号（正式商业关系随 INT-02 接管；前向扩列）',
  `implementation_location` varchar(500) DEFAULT NULL COMMENT '实施地点（多地点拆分属 PM-02；前向扩列）',
  `location_resolution_status` varchar(16) NOT NULL DEFAULT 'UNRESOLVED' COMMENT '地点解析状态：RESOLVED/UNRESOLVED',
  `creation_reason` varchar(500) DEFAULT NULL COMMENT '手工创建原因（BR-2 必填，应用层校验；前向扩列）',
  `lifecycle_template_id` bigint DEFAULT NULL COMMENT '生命周期模板ID',
  `lifecycle_template_revision_no` int DEFAULT NULL COMMENT '冻结的模板版本号（创建时快照；前向扩列）',
  `lifecycle_template_revision_id` bigint DEFAULT NULL COMMENT '创建时冻结的生命周期模板修订ID；仅来源追溯/冻结身份，不作为运行时设计态反查入口',
  `template_load_method` varchar(32) DEFAULT NULL COMMENT '模板加载方式：AUTO_DEFAULT唯一默认命中/MANUAL_SELECTED人工选择（前向扩列）',
  `process_definition_key` varchar(64) DEFAULT NULL COMMENT '冻结的流程定义引用（取自绑定版本，创建时快照；前向扩列）',
  `process_definition_version` varchar(32) DEFAULT NULL COMMENT '冻结的流程定义版本引用（前向扩列）',
  `project_start_time` datetime(3) DEFAULT NULL COMMENT '项目开始时间',
  `project_refresh_time` datetime(3) DEFAULT NULL COMMENT '项目刷新时间',
  `project_close_time` datetime(3) DEFAULT NULL COMMENT '项目关闭时间',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '项目创建来源类型',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态',
  `progress` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '项目进度百分比（来源属 PM-11 阶段推进/任务闭环，本 Feature 仅消费做汇总）',
  `aggregation_weight` decimal(5,2) DEFAULT NULL COMMENT '相对直接父项目的权重（NULL=等权，读时按直接子项目数归一化）',
  `weight_source` varchar(32) DEFAULT NULL COMMENT '权重来源：DEFAULT_EQUAL 默认等权 / MANUAL 人工设置',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `lifecycle_status` varchar(32) DEFAULT NULL COMMENT '生命周期：ACTIVE/NORMAL_CLOSED/EXCEPTION_CLOSED',
  `current_stage` varchar(32) DEFAULT NULL COMMENT '当前阶段：S0～S6',
  `assignment_status` varchar(32) DEFAULT NULL COMMENT '主责指派状态：UNASSIGNED/ASSIGNED',
  `task_tree_version` bigint unsigned NOT NULL DEFAULT '0' COMMENT '项目内任务树结构版本水位',
  `task_progress_version` bigint unsigned NOT NULL DEFAULT '0' COMMENT '项目内任务进度事实版本水位',
  `project_end_date` date DEFAULT NULL COMMENT '工勘提供的项目结束日期，工期倒排截止日期',
  `closure_policy_snapshot` json DEFAULT NULL COMMENT 'Explicit closure policy frozen from published template',
  `closure_type` varchar(32) DEFAULT NULL,
  `closed_from_stage` varchar(32) DEFAULT NULL,
  `closed_at` datetime(3) DEFAULT NULL,
  `active_plan_version_id` bigint DEFAULT NULL,
  `custom_info` json DEFAULT NULL,
  `order_create_time` datetime(3) DEFAULT NULL,
  `disabled` bit(1) DEFAULT NULL,
  `effective_from` datetime(3) DEFAULT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_project_code` (`tenant_id`,`project_code`),
  UNIQUE KEY `uk_proj_project_code_sequence` (`tenant_id`,`code_root_id`,`project_sequence`),
  UNIQUE KEY `uk_proj_project_tenant_row` (`tenant_id`,`id`),
  KEY `idx_proj_project_parent` (`tenant_id`,`parent_id`,`tree_sort`,`id`),
  KEY `idx_proj_project_path` (`tenant_id`,`root_id`,`tree_path`(191)),
  KEY `idx_proj_project_manager` (`tenant_id`,`manager_id`,`status`),
  KEY `idx_proj_project_customer` (`tenant_id`,`customer_code`,`status`,`id`),
  KEY `idx_proj_project_company_department` (`tenant_id`,`company_code`,`department_code`,`status`,`id`),
  KEY `idx_project_lifecycle_template_revision` (`tenant_id`,`lifecycle_template_revision_id`),
  KEY `idx_project_active_plan` (`tenant_id`,`active_plan_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目主档及非固定层级项目树（双重唯一：编码租户内唯一/序号命名空间根内唯一）';

CREATE TABLE `proj_project_code_sequence` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '序列ID',
  `code_namespace` varchar(64) NOT NULL COMMENT '编码命名空间：V1=PLATFORM_ROOT（租户级平台流水）；PM-02 预留 ROOT:<code_root_id>',
  `next_value` bigint NOT NULL DEFAULT '1' COMMENT '下一个可分配流水号',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_code_sequence` (`tenant_id`,`code_namespace`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目平台编码序列（SELECT ... FOR UPDATE 原子递增）';

CREATE TABLE `proj_project_company_department_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `company_id` bigint DEFAULT NULL COMMENT '平台公司主档ID',
  `company_code` varchar(64) NOT NULL COMMENT '公司编码',
  `company_name` varchar(255) DEFAULT NULL COMMENT '公司名称',
  `department_id` bigint DEFAULT NULL COMMENT '部门ID',
  `department_code` varchar(64) DEFAULT NULL COMMENT '部门编码',
  `department_name` varchar(255) DEFAULT NULL COMMENT '部门名称',
  `relation_role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务角色',
  `is_primary` tinyint NOT NULL DEFAULT '0' COMMENT '同一业务范围内是否为主记录：0否，1是',
  `effective_from` datetime(3) DEFAULT NULL COMMENT '生效开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '生效结束时间',
  `status` varchar(32) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态',
  `primary_project_id` bigint GENERATED ALWAYS AS ((case when ((`deleted` = 0x00) and (`effective_to` is null) and (`is_primary` = 1)) then `project_id` else NULL end)) STORED COMMENT '当前有效主记录指向的项目ID（参与唯一键）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_company_department_rel` (`tenant_id`,`project_id`,`company_code`,`department_code`,`relation_role`,`effective_from`),
  UNIQUE KEY `uk_proj_primary_company_department` (`tenant_id`,`primary_project_id`,`relation_role`),
  KEY `idx_proj_company_reverse` (`tenant_id`,`company_code`,`relation_role`,`status`,`project_id`),
  CONSTRAINT `chk_proj_company_department_dates` CHECK (((`effective_to` is null) or (`effective_from` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_proj_company_department_pair` CHECK (((`department_id` is null) or (`department_code` is not null))),
  CONSTRAINT `chk_proj_company_department_primary` CHECK ((`is_primary` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目业务角色下的公司与部门组合关系（每项目每角色至多一条当前有效主记录）';

CREATE TABLE `proj_project_deliverable` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '交付件实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `deliverable_code` varchar(64) NOT NULL COMMENT '交付件码（实例化时冻结，项目内唯一）',
  `name` varchar(128) NOT NULL COMMENT '交付件名称（快照）',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `task_code` varchar(64) DEFAULT NULL COMMENT '关联任务码（NULL=阶段级）',
  `required` bit(1) NOT NULL DEFAULT b'1' COMMENT '必需标志（快照）',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板交付件定义ID',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING' COMMENT '交付件状态（字典 pms_project_deliverable_status）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_deliverable` (`tenant_id`,`project_id`,`deliverable_code`),
  KEY `idx_proj_deliverable_stage` (`project_id`,`stage_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目交付件实例';

CREATE TABLE `proj_project_exit_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目正常收尾退出记录编号',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '行版本（乐观锁）',
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `application_id` bigint DEFAULT NULL,
  `snapshot_id` bigint DEFAULT NULL,
  `closure_type` varchar(32) NOT NULL,
  `project_version` int NOT NULL,
  `stage_instance_id` bigint NOT NULL,
  `template_revision_id` bigint NOT NULL,
  `scope_version` bigint NOT NULL,
  `gate_snapshot_ref` bigint NOT NULL,
  `source_context` varchar(32) NOT NULL,
  `source_record_id` bigint NOT NULL,
  `source_record_revision` bigint NOT NULL COMMENT '来源记录修订（聚合版本）',
  `closed_from_stage` varchar(32) NOT NULL,
  `before_lifecycle_status` varchar(32) NOT NULL,
  `after_lifecycle_status` varchar(32) NOT NULL,
  `before_project_version` int NOT NULL,
  `after_project_version` int NOT NULL,
  `process_instance_id` varchar(128) DEFAULT NULL,
  `revalidation_evidence` json NOT NULL,
  `closed_at` datetime(3) NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_per_project_version` (`tenant_id`,`project_id`,`project_version`),
  UNIQUE KEY `uk_per_source` (`tenant_id`,`source_context`,`source_record_id`,`source_record_revision`),
  UNIQUE KEY `uk_proj_exit_application` (`tenant_id`,`application_id`),
  CONSTRAINT `ck_per_stage` CHECK ((`closed_from_stage` in (_utf8mb4'S0',_utf8mb4'S1',_utf8mb4'S2',_utf8mb4'S3',_utf8mb4'S4',_utf8mb4'S5',_utf8mb4'S6'))),
  CONSTRAINT `ck_per_type` CHECK ((((`closure_type` in (_utf8mb4'NORMAL',_utf8mb4'NO_TRACKING')) and (`source_context` = _utf8mb4'ACC')) or ((`closure_type` = _utf8mb4'EXCEPTION') and (`source_context` = _utf8mb4'PROJ'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_gate` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '门禁实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `gate_code` varchar(64) NOT NULL COMMENT '门禁码（实例化时冻结，项目内唯一）',
  `name` varchar(128) NOT NULL COMMENT '门禁名称（快照）',
  `gate_type` varchar(16) NOT NULL COMMENT '类型：ENTRY准入/EXIT准出',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `description` varchar(500) DEFAULT NULL COMMENT '门禁说明（快照）',
  `validation_summary` varchar(1000) DEFAULT NULL COMMENT '冻结的校验内容摘要（实例化时自模板引用行生成）',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板门禁定义ID',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING' COMMENT '门禁状态（字典 pms_project_gate_status）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `active_gate_code` varchar(64) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `gate_code` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_gate` (`tenant_id`,`project_id`,`active_gate_code`),
  KEY `idx_proj_gate_stage` (`project_id`,`stage_code`,`gate_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目门禁实例（ENTRY/EXIT）';

CREATE TABLE `proj_project_gate_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '门禁引用ID',
  `gate_id` bigint NOT NULL COMMENT '门禁实例ID（proj_project_gate）',
  `ref_type` varchar(16) NOT NULL COMMENT '引用类型：TASK/DELIVERABLE/STATE/PROCESS（冻结）',
  `ref_code` varchar(64) NOT NULL COMMENT '引用编码（冻结）',
  `ref_version` varchar(32) DEFAULT NULL COMMENT '引用版本（流程引用时使用，冻结）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `active_ref_code` varchar(64) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `ref_code` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_gate_ref` (`tenant_id`,`gate_id`,`ref_type`,`active_ref_code`),
  KEY `idx_proj_gate_ref_gate` (`gate_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目门禁实例引用行';

CREATE TABLE `proj_project_governance_action` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `action_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '治理动作单号，全局唯一',
  `action_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作类型 ROLLBACK 回退总部 / DIRECT_CLOSE 直接关闭',
  `reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '回退/关闭原因',
  `proof_files` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证明材料文件URL列表（JSON数组）',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人编号',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人编号',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `before_project_status` int DEFAULT NULL COMMENT '执行前项目状态',
  `after_project_status` int DEFAULT NULL COMMENT '执行后项目状态',
  `before_manager_user_id` bigint DEFAULT NULL COMMENT '执行前项目经理',
  `after_manager_user_id` bigint DEFAULT NULL COMMENT '执行后项目经理（回退时置空）',
  `execute_time` datetime DEFAULT NULL COMMENT '执行时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2审批中 3已执行 4已驳回 5已撤回',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_governance_action_no` (`action_no`),
  KEY `idx_pms_governance_action_project` (`project_id`),
  KEY `idx_pms_governance_action_type` (`action_type`),
  KEY `idx_pms_governance_action_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 项目治理动作（回退/关闭）';

CREATE TABLE `proj_project_lease_product` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint DEFAULT NULL,
  `project_code` text,
  `execution_no` text,
  `product_category` text,
  `product_type` text,
  `product_code` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `product_model` text,
  `product_name` text,
  `quantity` decimal(24,6) DEFAULT NULL,
  `memo` text,
  `lease_duration` decimal(16,2) DEFAULT NULL,
  `data_source` varchar(25) DEFAULT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`tenant_id`,`project_id`,`deleted`),
  KEY `idx_lease_cache_project` (`tenant_id`,`project_code`(255),`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_member_assignment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `user_id` bigint DEFAULT NULL COMMENT '系统账号ID；外部最终用户为空',
  `employee_no` varchar(64) DEFAULT NULL COMMENT '成员工号',
  `member_name` varchar(128) DEFAULT NULL COMMENT '成员姓名',
  `company_id` bigint DEFAULT NULL COMMENT '加入时公司ID',
  `company_code` varchar(64) DEFAULT NULL COMMENT '公司编码',
  `company_name` varchar(255) DEFAULT NULL COMMENT '公司名称',
  `department_id` bigint DEFAULT NULL COMMENT '部门ID快照',
  `department_code` varchar(64) DEFAULT NULL COMMENT '部门编码',
  `department_name` varchar(255) DEFAULT NULL COMMENT '部门名称',
  `member_role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '成员角色编码',
  `assignment_type` varchar(32) DEFAULT NULL COMMENT '责任类型：PRIMARY/COLLABORATOR',
  `site_id` bigint DEFAULT NULL COMMENT 'AST站点稳定ID',
  `responsibility` varchar(500) DEFAULT NULL COMMENT '职责',
  `change_reason` varchar(500) DEFAULT NULL COMMENT '指派或改派原因',
  `effective_from` datetime(3) DEFAULT NULL COMMENT '生效开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '生效结束时间',
  `status` varchar(32) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间，未确认历史可保留原NULL',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间，未确认历史可保留原NULL',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `remark` varchar(500) DEFAULT NULL COMMENT '普通备注，非指派原因',
  `end_reason` varchar(500) DEFAULT NULL COMMENT '区间结束原因，保留原加入/调整原因',
  `external_mobile` varchar(64) DEFAULT NULL,
  `external_email` varchar(255) DEFAULT NULL,
  `authorization_confirmed` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否经Owner确认参与当前授权；外部最终用户为0',
  `title` varchar(64) DEFAULT NULL COMMENT '外部最终用户职务，随成员区间留痕',
  `member_code` varchar(45) DEFAULT NULL COMMENT '成员区间人员编码',
  `phone_number` varchar(20) DEFAULT NULL COMMENT '成员区间联系电话',
  `email` varchar(45) DEFAULT NULL COMMENT '成员区间邮箱',
  `registration_source` varchar(2) DEFAULT NULL COMMENT '登记来源：1项目信息，2手工成员',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_member_role` (`tenant_id`,`project_id`,`user_id`,`member_role`,`effective_from`),
  KEY `idx_proj_member_user` (`tenant_id`,`user_id`,`status`,`project_id`),
  KEY `idx_proj_member_employee` (`tenant_id`,`employee_no`,`status`,`project_id`),
  KEY `idx_proj_member_current_responsibility` (`tenant_id`,`project_id`,`member_role`,`assignment_type`,`site_id`,`status`,`effective_to`),
  CONSTRAINT `ck_proj_member_confirmed_identity_audit` CHECK (((`authorization_confirmed` = 0x00) or ((`user_id` is not null) and (`create_time` is not null) and (`update_time` is not null)))),
  CONSTRAINT `ck_proj_member_end_user_no_system_identity` CHECK (((`member_role` <> _utf8mb4'END_USER') or ((`user_id` is null) and (`authorization_confirmed` = 0x00)))),
  CONSTRAINT `chk_proj_member_dates` CHECK (((`effective_to` is null) or (`effective_from` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目成员、角色及有效期（区间留痕）';

CREATE TABLE `proj_project_milestone` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '里程碑实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `milestone_code` varchar(64) NOT NULL COMMENT '里程碑码（实例化时冻结，项目内唯一）',
  `name` varchar(128) NOT NULL COMMENT '里程碑名称（快照）',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `timing` varchar(64) DEFAULT NULL COMMENT '时点说明（快照）',
  `criteria` varchar(500) DEFAULT NULL COMMENT '达成标准（快照）',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板里程碑定义ID',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING' COMMENT '里程碑状态（字典 pms_project_milestone_status）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `active_milestone_code` varchar(64) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `milestone_code` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_milestone` (`tenant_id`,`project_id`,`active_milestone_code`),
  KEY `idx_proj_milestone_stage` (`project_id`,`stage_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目里程碑实例';

CREATE TABLE `proj_project_node_execution` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `plan_version_id` bigint NOT NULL,
  `node_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_instance_id` bigint NOT NULL,
  `contract_id` bigint NOT NULL,
  `round_no` int NOT NULL,
  `current_marker` tinyint DEFAULT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `admitted_at` datetime(3) DEFAULT NULL,
  `started_at` datetime(3) DEFAULT NULL,
  `started_plan_version_id` bigint DEFAULT NULL,
  `submitted_at` datetime(3) DEFAULT NULL,
  `submitted_by` bigint DEFAULT NULL,
  `submission_note` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ended_at` datetime(3) DEFAULT NULL,
  `result_snapshot` json DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_node_execution_round` (`tenant_id`,`project_id`,`node_key`,`round_no`),
  UNIQUE KEY `uk_node_current_execution` (`tenant_id`,`project_id`,`node_key`,`current_marker`),
  KEY `idx_node_execution_plan` (`tenant_id`,`project_id`,`plan_version_id`),
  CONSTRAINT `ck_node_execution_end` CHECK (((`status` not in (_utf8mb4'DONE',_utf8mb4'TERMINATED')) or ((`ended_at` is not null) and (`result_snapshot` is not null)))),
  CONSTRAINT `ck_node_execution_kind` CHECK ((`node_kind` in (_utf8mb4'STAGE',_utf8mb4'TASK'))),
  CONSTRAINT `ck_node_execution_round` CHECK (((`round_no` > 0) and ((`current_marker` is null) or (`current_marker` = 1)))),
  CONSTRAINT `ck_node_execution_status` CHECK ((`status` in (_utf8mb4'PENDING',_utf8mb4'ACTIVE',_utf8mb4'DONE',_utf8mb4'TERMINATED'))),
  CONSTRAINT `ck_node_execution_submission` CHECK (((`submitted_at` is null) or ((`submitted_by` is not null) and (`started_at` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_party` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `party_role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参与方角色编码',
  `party_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参与方编码',
  `party_name` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参与方名称',
  `contact_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人名称',
  `phone` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人电话',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_table` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统物理表名',
  `source_record_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源记录稳定唯一键',
  `effective_from` datetime(3) DEFAULT NULL COMMENT '生效开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '生效结束时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_party_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_project_party_source` (`tenant_id`,`source_system`,`source_table`,`source_record_key`,`party_role`),
  KEY `idx_project_party_project` (`tenant_id`,`project_id`,`party_role`,`status`),
  KEY `idx_project_party_code` (`tenant_id`,`party_role`,`party_code`,`status`),
  CONSTRAINT `fk_project_party_project` FOREIGN KEY (`tenant_id`, `project_id`) REFERENCES `proj_project` (`tenant_id`, `id`),
  CONSTRAINT `chk_project_party_dates` CHECK (((`effective_to` is null) or (`effective_from` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_project_party_deleted` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目参与方，按合同客户、最终用户、代理商、服务商等角色保存';

CREATE TABLE `proj_project_plan_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目计划版本编号',
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_template_revision_id` bigint DEFAULT NULL,
  `base_plan_version_id` bigint DEFAULT NULL,
  `designer_document` json NOT NULL,
  `execution_snapshot` json DEFAULT NULL,
  `effective_at` datetime(3) DEFAULT NULL,
  `closed_at` datetime(3) DEFAULT NULL,
  `closure_result` json DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `draft_marker` tinyint GENERATED ALWAYS AS ((case when ((`status` = _utf8mb4'DRAFT') and (`deleted` = 0x00)) then 1 else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_plan_revision` (`tenant_id`,`project_id`,`revision_no`),
  UNIQUE KEY `uk_project_plan_draft` (`tenant_id`,`project_id`,`draft_marker`),
  CONSTRAINT `ck_project_plan_payload` CHECK (((`status` = _utf8mb4'DRAFT') or ((`execution_snapshot` is not null) and (`effective_at` is not null)))),
  CONSTRAINT `ck_project_plan_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'EFFECTIVE',_utf8mb4'SUPERSEDED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_portfolio` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目组合编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组合编码，全局唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组合名称',
  `purpose` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组合用途（战略/客户/区域/计划/专项）',
  `owner_user_id` bigint DEFAULT NULL COMMENT '负责人用户编号',
  `valid_from` date DEFAULT NULL COMMENT '有效开始时间',
  `valid_to` date DEFAULT NULL COMMENT '有效结束时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态',
  `target_metrics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '统计目标（JSON 文本）',
  `member_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STATIC' COMMENT '成员类型 STATIC 静态 / DYNAMIC 动态',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_portfolio_code` (`code`),
  KEY `idx_pms_portfolio_owner` (`owner_user_id`),
  KEY `idx_pms_portfolio_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS项目组合';

CREATE TABLE `proj_project_portfolio_member` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `portfolio_id` bigint NOT NULL COMMENT '项目组合ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `inclusion_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STATIC' COMMENT '纳入类型 STATIC 静态 / DYNAMIC 动态',
  `inclusion_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳入原因',
  `exclusion_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '排除原因',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1纳入 2排除',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_portfolio_member` (`portfolio_id`,`project_id`),
  KEY `idx_pms_portfolio_member_project` (`project_id`),
  KEY `idx_pms_portfolio_member_status` (`portfolio_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS项目组合成员';

CREATE TABLE `proj_project_portfolio_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `portfolio_id` bigint NOT NULL COMMENT '组合编号',
  `rule_field` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则字段 CUSTOMER/REGION/TYPE/STATUS',
  `rule_operator` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EQ' COMMENT '规则操作符 EQ/NE/IN/LIKE',
  `rule_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则值（IN 用逗号分隔）',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_portfolio_rule_portfolio` (`portfolio_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS项目组合动态规则';

CREATE TABLE `proj_project_product_configuration` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint DEFAULT NULL,
  `project_code` text,
  `execution_no` text,
  `item_group` int DEFAULT NULL,
  `product_code` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `parent_code` text,
  `quantity` decimal(24,6) DEFAULT NULL,
  `bom_path` text,
  `product_model` text,
  `product_description` text,
  `level` int DEFAULT NULL,
  `data_source` varchar(25) DEFAULT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`tenant_id`,`project_id`,`deleted`),
  KEY `idx_configuration_cache_project` (`tenant_id`,`project_code`(100),`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_progress_fact` (
  `id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `fact_source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fact_source_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fact_version` bigint NOT NULL,
  `progress` decimal(7,4) NOT NULL,
  `source_watermark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `occurred_at` datetime NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_progress_fact` (`tenant_id`,`project_id`,`fact_source_type`,`fact_source_id`,`fact_version`),
  KEY `idx_proj_progress_fact_latest` (`tenant_id`,`project_id`,`occurred_at`,`id`),
  CONSTRAINT `ck_proj_progress_fact_value` CHECK (((`progress` >= 0) and (`progress` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度追加事实';

CREATE TABLE `proj_project_progress_policy_item` (
  `id` bigint NOT NULL,
  `policy_revision_id` bigint NOT NULL,
  `child_project_id` bigint NOT NULL,
  `weight` decimal(7,4) NOT NULL,
  `include_status_snapshot` json NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_progress_policy_item` (`tenant_id`,`policy_revision_id`,`child_project_id`),
  CONSTRAINT `ck_proj_progress_policy_weight` CHECK (((`weight` >= 0) and (`weight` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度策略权重项';

CREATE TABLE `proj_project_progress_policy_revision` (
  `id` bigint NOT NULL,
  `parent_project_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `policy_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `process_definition_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `effective_from` datetime DEFAULT NULL,
  `effective_to` datetime DEFAULT NULL,
  `approved_by` bigint DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `supersedes_revision_id` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_progress_policy_revision` (`tenant_id`,`parent_project_id`,`revision_no`),
  UNIQUE KEY `uk_proj_progress_policy_process` (`tenant_id`,`process_instance_id`),
  KEY `idx_proj_progress_policy_active` (`tenant_id`,`parent_project_id`,`status`,`effective_from`,`effective_to`),
  CONSTRAINT `ck_proj_progress_policy_range` CHECK (((`effective_to` is null) or (`effective_from` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `ck_proj_progress_policy_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'APPROVING',_utf8mb4'ACTIVE',_utf8mb4'REJECTED',_utf8mb4'SUPERSEDED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度策略版本';

CREATE TABLE `proj_project_progress_snapshot` (
  `id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `policy_revision_id` bigint NOT NULL,
  `tree_version` bigint NOT NULL,
  `source_watermark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `snapshot_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `progress` decimal(7,4) DEFAULT NULL,
  `missing_item_count` int NOT NULL DEFAULT '0',
  `calculated_at` datetime NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_progress_snapshot` (`tenant_id`,`project_id`,`policy_revision_id`,`tree_version`,`source_watermark`),
  KEY `idx_proj_progress_snapshot_latest` (`tenant_id`,`project_id`,`calculated_at`,`id`),
  CONSTRAINT `ck_proj_progress_snapshot_status` CHECK ((`snapshot_status` in (_utf8mb4'READY',_utf8mb4'PENDING'))),
  CONSTRAINT `ck_proj_progress_snapshot_value` CHECK (((`progress` is null) or ((`progress` >= 0) and (`progress` <= 100))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度不可变快照';

CREATE TABLE `proj_project_progress_snapshot_detail` (
  `id` bigint NOT NULL,
  `snapshot_id` bigint NOT NULL,
  `child_project_id` bigint NOT NULL,
  `fact_version` bigint DEFAULT NULL,
  `child_progress` decimal(7,4) DEFAULT NULL,
  `normalized_weight` decimal(7,4) NOT NULL,
  `contribution` decimal(7,4) DEFAULT NULL,
  `missing_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_progress_snapshot_detail` (`tenant_id`,`snapshot_id`,`child_project_id`),
  KEY `idx_proj_progress_snapshot_detail` (`tenant_id`,`snapshot_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度快照解释明细';

CREATE TABLE `proj_project_real_product` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `contract_no` text,
  `project_code` text,
  `execution_no` text,
  `product_category_name` text,
  `product_name` text,
  `product_sub_code` text,
  `product_sub_model` text,
  `product_sub_name` text,
  `quantity` decimal(24,6) DEFAULT NULL,
  `memo` text,
  `data_source` varchar(25) DEFAULT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`tenant_id`,`project_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_risk` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险标题',
  `risk_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险等级 HIGH/MEDIUM/LOW',
  `risk_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险类型',
  `cause` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险原因',
  `impact` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险影响',
  `mitigation` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缓解措施',
  `contingency` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应急措施',
  `owner_user_id` bigint DEFAULT NULL COMMENT '风险负责人',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0已识别 1处理中 2已关闭 3已发生',
  `warning_threshold` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预警阈值',
  `review_notes` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核备注',
  `identified_at` datetime DEFAULT NULL COMMENT '识别时间',
  `closed_at` datetime DEFAULT NULL COMMENT '关闭时间',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_project_risk_project` (`project_id`),
  KEY `idx_pms_project_risk_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目风险';

CREATE TABLE `proj_project_site` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关系ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `site_id` bigint NOT NULL COMMENT 'AST站点稳定ID（无物理外键）',
  `site_version_snapshot` int NOT NULL COMMENT '站点引用版本快照',
  `primary_site` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否主站点',
  `scope_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '范围状态',
  `effective_from` datetime NOT NULL COMMENT '生效开始时间',
  `effective_to` datetime DEFAULT NULL COMMENT '失效时间',
  `site_code_snapshot` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '站点编码快照',
  `site_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '站点名称快照',
  `address_snapshot` json DEFAULT NULL COMMENT '地址快照',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `current_primary_project_id` bigint GENERATED ALWAYS AS ((case when ((`primary_site` = 0x01) and (`effective_to` is null) and (`scope_status` = _utf8mb4'ACTIVE') and (`deleted` = 0x00)) then `project_id` else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_site_interval` (`tenant_id`,`project_id`,`site_id`,`effective_from`),
  UNIQUE KEY `uk_proj_current_primary` (`tenant_id`,`current_primary_project_id`),
  KEY `idx_proj_site_project` (`tenant_id`,`project_id`,`effective_to`),
  KEY `idx_proj_site_site` (`tenant_id`,`site_id`,`effective_to`),
  CONSTRAINT `chk_proj_site_interval` CHECK (((`effective_to` is null) or (`effective_to` > `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目实施站点时态关系';

CREATE TABLE `proj_project_split_item` (
  `id` bigint NOT NULL,
  `split_request_id` bigint NOT NULL,
  `client_item_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `business_level_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tree_sort` int NOT NULL DEFAULT '0',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `item_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `validation_result` json DEFAULT NULL,
  `created_project_id` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `template_revision_id` bigint DEFAULT NULL COMMENT '子项目显式选择的已发布模板版本',
  `template_selection_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板匹配覆盖原因',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_split_item_client` (`tenant_id`,`split_request_id`,`client_item_key`),
  KEY `idx_proj_split_item_request` (`tenant_id`,`split_request_id`,`tree_sort`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目拆分方案项';

CREATE TABLE `proj_project_split_request` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目拆分申请编号',
  `parent_project_id` bigint NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `draft_version` int NOT NULL DEFAULT '0',
  `parent_version` int DEFAULT NULL,
  `scope_version` bigint DEFAULT NULL,
  `tree_version` bigint DEFAULT NULL,
  `template_revision_id` bigint DEFAULT NULL,
  `preview_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validation_summary` json DEFAULT NULL,
  `validated_at` datetime DEFAULT NULL,
  `applied_change_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_proj_split_request_parent` (`tenant_id`,`parent_project_id`,`status`,`update_time`,`id`),
  CONSTRAINT `ck_proj_split_request_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'APPLIED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目拆分申请';

CREATE TABLE `proj_project_split_scope` (
  `id` bigint NOT NULL,
  `split_item_id` bigint NOT NULL,
  `order_line_id` bigint NOT NULL,
  `allocated_qty` decimal(18,6) NOT NULL,
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `serial_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_scope_version` bigint NOT NULL,
  `source_snapshot` json DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_split_scope_dimension` (`tenant_id`,`split_item_id`,`order_line_id`,`department_code`,`serial_no`),
  KEY `idx_proj_split_scope_item` (`tenant_id`,`split_item_id`,`id`),
  CONSTRAINT `ck_proj_split_scope_quantity` CHECK ((`allocated_qty` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目拆分范围发生时快照';

CREATE TABLE `proj_project_stage` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID（proj_project）',
  `stage_code` varchar(32) NOT NULL COMMENT '阶段码（S0～S6，实例化时冻结）',
  `name` varchar(128) NOT NULL COMMENT '阶段名称（快照）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '阶段顺序（快照）',
  `entry_criteria` varchar(500) DEFAULT NULL COMMENT '准入条件说明（快照）',
  `exit_criteria` varchar(500) DEFAULT NULL COMMENT '准出条件说明（快照）',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板阶段定义ID（proj_project_template_stage_definition）',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING' COMMENT '阶段实例状态（字典 pms_project_stage_status，S0 初始 ACTIVE）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  `graph_version` bigint DEFAULT NULL,
  `start_node` bit(1) DEFAULT NULL,
  `terminal_node` bit(1) DEFAULT NULL,
  `active_stage_code` varchar(32) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `stage_code` else NULL end)) VIRTUAL,
  `suggested_start_time` datetime(3) DEFAULT NULL COMMENT '建议开始时间',
  `suggested_end_time` datetime(3) DEFAULT NULL COMMENT '建议结束时间',
  `plan_start_time` datetime(3) DEFAULT NULL COMMENT '计划开始时间',
  `plan_end_time` datetime(3) DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime(3) DEFAULT NULL COMMENT '当前轮次阶段激活时间',
  `actual_end_time` datetime(3) DEFAULT NULL COMMENT '当前轮次阶段结束时间',
  `deviation_reason` varchar(500) DEFAULT NULL COMMENT '偏差原因',
  `responsible_role` varchar(64) DEFAULT NULL COMMENT '保留字段，暂不参与业务',
  `responsible_user_id` bigint DEFAULT NULL COMMENT '保留字段，暂不参与业务',
  `acceptance_time` datetime(3) DEFAULT NULL COMMENT '验收时间，与实际结束时间独立',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_stage` (`tenant_id`,`project_id`,`active_stage_code`),
  KEY `idx_proj_stage_project` (`project_id`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目阶段实例（实例化时从模板冻结）';

CREATE TABLE `proj_project_stage_execution_contract` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `source_node_key` varchar(128) DEFAULT NULL,
  `graph_version` bigint NOT NULL,
  `definition_revision_id` bigint DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `binding_version` int NOT NULL,
  `binding_type` varchar(32) NOT NULL,
  `binding_snapshot` json NOT NULL,
  `permission_snapshot` json DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_snapshot` json DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  `definition_snapshot` json NOT NULL,
  `effective_from` datetime NOT NULL,
  `effective_to` datetime DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`effective_to` is null) then 1 else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_psec_version` (`tenant_id`,`project_id`,`stage_id`,`binding_version`),
  UNIQUE KEY `uk_psec_current` (`tenant_id`,`project_id`,`stage_id`,`current_marker`),
  KEY `idx_psec_project` (`tenant_id`,`project_id`,`stage_id`),
  KEY `idx_psec_source_node` (`tenant_id`,`project_id`,`source_node_key`),
  CONSTRAINT `ck_psec_time` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `ck_psec_type` CHECK ((`binding_type` in (_utf8mb4'STAGE_NATIVE',_utf8mb4'BUSINESS_OBJECT',_utf8mb4'BUSINESS_COMPONENT',_utf8mb4'DYNAMIC_FORM',_utf8mb4'APPROVAL',_utf8mb4'COMPOSITE'))),
  CONSTRAINT `ck_psec_version` CHECK (((`binding_version` > 0) and (`graph_version` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_stage_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段快照ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `stage_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '快照阶段编码',
  `snapshot_no` int NOT NULL COMMENT '同项目同阶段快照序号',
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PM-10动作类型：ROLLBACK/EXCEPTION_CLOSE/REOPEN',
  `before_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前阶段',
  `after_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后阶段',
  `before_lifecycle_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前生命周期状态',
  `after_lifecycle_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后生命周期状态',
  `before_assignment_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前指派状态',
  `after_assignment_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后指派状态',
  `reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作原因编码',
  `reason_detail` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作原因说明',
  `reassignment_requirement` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回退后的重新指派要求',
  `business_basis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '异常关闭业务依据',
  `legacy_items_json` json DEFAULT NULL COMMENT '异常关闭遗留事项快照',
  `guard_snapshot_json` json DEFAULT NULL COMMENT '提交使用的守卫令牌快照',
  `tree_version` bigint DEFAULT NULL COMMENT '守卫冻结的完整树版本',
  `provider_facts_json` json DEFAULT NULL COMMENT '守卫冻结的提供方事实版本与摘要',
  `related_snapshot_id` bigint DEFAULT NULL COMMENT '重开关联的异常关闭快照ID',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PM-10稳定业务操作ID',
  `operator_user_id` bigint DEFAULT NULL COMMENT 'PM-10操作者用户ID',
  `operated_at` datetime(3) DEFAULT NULL COMMENT 'PM-10业务操作时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_stage_snapshot_project_stage_no` (`tenant_id`,`project_id`,`stage_code`,`snapshot_no`),
  UNIQUE KEY `uk_proj_stage_snapshot_operation` (`tenant_id`,`operation_id`),
  KEY `idx_proj_stage_snapshot_project_time` (`tenant_id`,`project_id`,`operated_at`,`id`),
  KEY `idx_proj_stage_snapshot_related` (`tenant_id`,`project_id`,`related_snapshot_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PM-03、PM-10、EXE-06共享项目阶段快照（只追加）';

CREATE TABLE `proj_project_stage_transition` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `template_revision_id` bigint NOT NULL,
  `source_transition_key` varchar(128) DEFAULT NULL,
  `source_transition_id` bigint DEFAULT NULL,
  `transition_code` varchar(128) NOT NULL,
  `transition_revision` bigint DEFAULT NULL,
  `from_stage_id` bigint NOT NULL,
  `to_stage_id` bigint NOT NULL,
  `priority` int NOT NULL,
  `is_default` bit(1) NOT NULL,
  `default_marker` tinyint GENERATED ALWAYS AS ((case when (`is_default` = 1) then 1 else NULL end)) STORED,
  `condition_rule_revision_id` bigint DEFAULT NULL,
  `condition_snapshot` json DEFAULT NULL,
  `graph_version` bigint NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pst_code` (`tenant_id`,`project_id`,`graph_version`,`transition_code`),
  UNIQUE KEY `uk_pst_edge` (`tenant_id`,`project_id`,`graph_version`,`source_transition_id`),
  UNIQUE KEY `uk_pst_default` (`tenant_id`,`project_id`,`graph_version`,`from_stage_id`,`default_marker`),
  UNIQUE KEY `uk_pst_source_key_v2` (`tenant_id`,`project_id`,`graph_version`,`source_transition_key`),
  KEY `idx_pst_out` (`tenant_id`,`project_id`,`graph_version`,`from_stage_id`,`priority`),
  CONSTRAINT `ck_pst_condition_v2` CHECK (((`condition_rule_revision_id` is null) or (`condition_snapshot` is not null))),
  CONSTRAINT `ck_pst_default_v2` CHECK (((`is_default` in (0,1)) and ((`is_default` = 0) or ((`condition_rule_revision_id` is null) and (`condition_snapshot` is null))))),
  CONSTRAINT `ck_pst_self` CHECK ((`from_stage_id` <> `to_stage_id`)),
  CONSTRAINT `ck_pst_versions` CHECK (((`transition_revision` > 0) and (`graph_version` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proj_project_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `task_code` varchar(64) NOT NULL COMMENT '任务码（实例化时冻结，项目内唯一）',
  `name` varchar(128) NOT NULL COMMENT '任务名称（快照）',
  `parent_task_code` varchar(64) DEFAULT NULL COMMENT '父任务码（NULL=顶层）',
  `parent_task_id` bigint DEFAULT NULL COMMENT '当前直接父任务ID',
  `root_task_id` bigint NOT NULL COMMENT '当前根任务ID',
  `tree_depth` int unsigned NOT NULL DEFAULT '0' COMMENT '结构深度，根任务为0',
  `business_level_code` varchar(64) DEFAULT NULL COMMENT '业务层级编码，与结构深度无关',
  `milestone_id` bigint DEFAULT NULL COMMENT '关联里程碑实例ID',
  `plan_start_time` datetime(3) DEFAULT NULL COMMENT '计划开始时间',
  `plan_end_time` datetime(3) DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime(3) DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime(3) DEFAULT NULL COMMENT '实际结束时间',
  `progress` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '任务进度0～100',
  `state_machine_revision_id` bigint NOT NULL COMMENT '创建时冻结的任务状态机版本ID',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `priority` int NOT NULL DEFAULT '2' COMMENT '优先级（快照）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序（快照）',
  `estimated_hours` decimal(6,1) DEFAULT NULL COMMENT '预估工时（快照）',
  `satisfaction_timing` varchar(32) DEFAULT NULL COMMENT '满意度适用时点（快照，由 ACC-02 消费）',
  `acc_satisfaction_template_id` bigint DEFAULT NULL COMMENT 'ACC满意度模板ID',
  `template_revision_id` bigint DEFAULT NULL COMMENT 'ACC模板修订ID',
  `template_version` int DEFAULT NULL COMMENT 'ACC模板版本',
  `satisfaction_rule_version` varchar(64) DEFAULT NULL COMMENT '满意度规则版本',
  `satisfaction_threshold` decimal(7,2) DEFAULT NULL COMMENT '满意度达标阈值',
  `description` longtext COMMENT '任务说明，格式由description_format明确',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板任务定义ID（proj_project_template_task_definition）',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING_ASSIGN' COMMENT '任务实例状态（字典 pms_project_task_status，初始待分配）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `description_format` varchar(16) NOT NULL DEFAULT 'PLAIN' COMMENT 'PLAIN保留旧纯文本；HTML为安全富文本',
  `active_task_code` varchar(64) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `task_code` else NULL end)) VIRTUAL,
  `suggested_start_time` datetime(3) DEFAULT NULL COMMENT '建议开始时间',
  `suggested_end_time` datetime(3) DEFAULT NULL COMMENT '建议结束时间',
  `acceptance_time` datetime(3) DEFAULT NULL COMMENT '验收时间，与实际结束时间独立',
  `required_task` bit(1) NOT NULL DEFAULT b'1' COMMENT '任务必选标志，旧任务保持必选',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_proj_task_tenant_project_row` (`tenant_id`,`project_id`,`id`),
  UNIQUE KEY `uk_proj_task` (`tenant_id`,`project_id`,`active_task_code`),
  KEY `idx_proj_task_parent` (`project_id`,`parent_task_code`),
  KEY `idx_proj_task_stage` (`project_id`,`stage_code`),
  KEY `idx_proj_task_direct_children` (`tenant_id`,`project_id`,`parent_task_id`,`sort_order`,`id`),
  KEY `idx_proj_task_root_depth` (`tenant_id`,`project_id`,`root_task_id`,`tree_depth`,`id`),
  KEY `idx_proj_task_business_level` (`tenant_id`,`project_id`,`business_level_code`,`sort_order`,`id`),
  KEY `fk_proj_task_state_revision` (`tenant_id`,`state_machine_revision_id`),
  CONSTRAINT `fk_proj_task_parent` FOREIGN KEY (`tenant_id`, `project_id`, `parent_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `fk_proj_task_root` FOREIGN KEY (`tenant_id`, `project_id`, `root_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `fk_proj_task_state_revision` FOREIGN KEY (`tenant_id`, `state_machine_revision_id`) REFERENCES `proj_task_state_machine_revision` (`tenant_id`, `id`),
  CONSTRAINT `chk_proj_task_plan_time` CHECK (((`plan_end_time` is null) or (`plan_start_time` is null) or (`plan_end_time` >= `plan_start_time`))),
  CONSTRAINT `chk_proj_task_progress` CHECK (((`progress` >= 0) and (`progress` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务实例（初始待分配）';

CREATE TABLE `proj_project_task_assignment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务责任区间ID',
  `project_task_id` bigint NOT NULL COMMENT '项目任务ID',
  `assignee_user_id` bigint NOT NULL COMMENT '负责人用户ID',
  `effective_from` datetime(3) NOT NULL COMMENT '责任开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '责任结束时间',
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`effective_to` is null) then 1 else NULL end)) STORED,
  `assigned_by` bigint NOT NULL COMMENT '指派人用户ID',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指派或转派原因',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_assignment_current` (`tenant_id`,`project_task_id`,`current_marker`),
  KEY `idx_proj_task_assignment_assignee` (`tenant_id`,`assignee_user_id`,`effective_to`,`project_task_id`),
  CONSTRAINT `fk_proj_task_assignment_task` FOREIGN KEY (`tenant_id`, `project_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `id`),
  CONSTRAINT `chk_proj_task_assignment_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务负责人责任区间';

CREATE TABLE `proj_project_task_completion_evaluation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_task_id` bigint NOT NULL COMMENT 'ProjectTask逻辑引用',
  `execution_contract_id` bigint NOT NULL COMMENT '执行契约版本逻辑引用',
  `task_version` int unsigned NOT NULL COMMENT '判定时任务版本',
  `contract_version` int unsigned NOT NULL COMMENT '判定时契约版本',
  `evaluation_result_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完成判定结果编码',
  `unmet_items_json` json DEFAULT NULL COMMENT '未满足项快照',
  `command_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定命令ID',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键',
  `fact_context_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部事实Owner Context',
  `fact_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部事实对象类型',
  `fact_object_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部事实对象稳定键',
  `fact_version` bigint DEFAULT NULL COMMENT '外部事实版本',
  `gate_snapshot_ref` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '门禁快照引用',
  `business_facts_json` json DEFAULT NULL COMMENT '冻结业务关联事实及逐项完成判定证据',
  `evaluated_by` bigint NOT NULL COMMENT '判定操作者用户ID',
  `evaluated_at` datetime(3) NOT NULL COMMENT '判定时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_completion_evaluation` (`tenant_id`,`project_task_id`,`idempotency_key`),
  KEY `idx_proj_task_completion_evaluation_time` (`tenant_id`,`project_task_id`,`evaluated_at`,`id`),
  KEY `fk_proj_task_completion_evaluation_contract` (`tenant_id`,`execution_contract_id`),
  CONSTRAINT `fk_proj_task_completion_evaluation_contract` FOREIGN KEY (`tenant_id`, `execution_contract_id`) REFERENCES `proj_project_task_execution_contract` (`tenant_id`, `id`),
  CONSTRAINT `fk_proj_task_completion_evaluation_task` FOREIGN KEY (`tenant_id`, `project_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务完成判定追加事实';

CREATE TABLE `proj_project_task_execution_contract` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `project_task_id` bigint NOT NULL COMMENT 'ProjectTask逻辑引用',
  `source_node_key` varchar(128) DEFAULT NULL,
  `template_task_definition_id` bigint DEFAULT NULL COMMENT '来源模板任务定义逻辑引用',
  `work_binding_type_code` varchar(32) NOT NULL,
  `target_context_code` varchar(32) DEFAULT NULL,
  `target_object_type` varchar(64) DEFAULT NULL,
  `target_object_key` varchar(128) DEFAULT NULL,
  `component_key` varchar(128) DEFAULT NULL,
  `dynamic_form_revision_id` bigint DEFAULT NULL,
  `approval_instance_id` bigint DEFAULT NULL,
  `binding_parameter_snapshot` json NOT NULL COMMENT '冻结绑定参数与Schema版本',
  `binding_view_snapshot` json DEFAULT NULL,
  `permission_policy_ref` varchar(512) DEFAULT NULL,
  `permission_snapshot` json DEFAULT NULL,
  `completion_rule_type_code` varchar(32) NOT NULL,
  `completion_rule_snapshot` json NOT NULL COMMENT '冻结完成规则与Schema版本',
  `gate_ref` varchar(512) DEFAULT NULL,
  `source_definition_version` int unsigned NOT NULL,
  `contract_version` int unsigned NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`effective_to` is null) then 1 else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '受控换绑乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `definition_revision_id` bigint DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  `definition_snapshot` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_task_execution_contract_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_project_task_execution_contract_version` (`tenant_id`,`project_task_id`,`contract_version`),
  UNIQUE KEY `uk_project_task_execution_contract_current` (`tenant_id`,`project_task_id`,`current_marker`),
  KEY `idx_project_task_execution_contract_target` (`tenant_id`,`target_context_code`,`target_object_type`,`target_object_key`),
  KEY `fk_project_task_execution_contract_definition` (`tenant_id`,`template_task_definition_id`),
  KEY `idx_ptc_source_node` (`tenant_id`,`project_task_id`,`source_node_key`),
  CONSTRAINT `fk_project_task_execution_contract_definition` FOREIGN KEY (`tenant_id`, `template_task_definition_id`) REFERENCES `proj_project_template_task_definition` (`tenant_id`, `id`),
  CONSTRAINT `chk_project_task_execution_contract_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_project_task_execution_contract_version` CHECK (((`source_definition_version` > 0) and (`contract_version` > 0))),
  CONSTRAINT `ck_ptc_permission_v2` CHECK (((`permission_policy_ref` is not null) or (`permission_snapshot` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ProjectTask执行契约';

CREATE TABLE `proj_project_task_responsible` (
  `id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_task_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `effective_from` datetime(6) NOT NULL,
  `effective_to` datetime(6) DEFAULT NULL,
  `assigned_by` bigint NOT NULL,
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `current_marker` tinyint GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0)) then 1 else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_responsible_current` (`tenant_id`,`project_task_id`,`current_marker`),
  KEY `idx_proj_task_responsible_user` (`tenant_id`,`user_id`,`project_id`,`effective_to`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务协调负责人责任区间，不授予办理或审批权限';

CREATE TABLE `proj_project_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `code` varchar(64) NOT NULL COMMENT '模板编码（租户内唯一，系统保留编码受保护）',
  `name` varchar(128) NOT NULL COMMENT '模板名称',
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT草稿/ACTIVE生效/RETIRED停用',
  `match_priority` int NOT NULL DEFAULT '100' COMMENT '匹配优先级（数值小者先命中）',
  `description` varchar(500) DEFAULT NULL COMMENT '业务场景描述',
  `system_reserved` bit(1) NOT NULL DEFAULT b'0' COMMENT '系统保留编码标志：不得删除/复用/改义',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `version` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_code` (`tenant_id`,`code`),
  KEY `idx_status_priority` (`status`,`match_priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板（身份/状态/优先级）';

CREATE TABLE `proj_project_template_deliverable_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '交付件定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `deliverable_code` varchar(64) NOT NULL COMMENT '交付件码（版本内唯一）',
  `name` varchar(128) NOT NULL COMMENT '交付件名称',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `task_code` varchar(64) DEFAULT NULL COMMENT '关联任务码（NULL=阶段级）',
  `required` bit(1) NOT NULL DEFAULT b'1' COMMENT '必需标志',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_deliverable` (`template_revision_id`,`deliverable_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板交付件定义';

CREATE TABLE `proj_project_template_gate_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '门禁定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `gate_code` varchar(64) NOT NULL COMMENT '门禁码（版本内唯一）',
  `name` varchar(128) NOT NULL COMMENT '门禁名称',
  `gate_type` varchar(16) NOT NULL COMMENT '类型：ENTRY准入/EXIT准出',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `description` varchar(500) DEFAULT NULL COMMENT '门禁说明',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_gate` (`template_revision_id`,`gate_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板门禁定义';

CREATE TABLE `proj_project_template_gate_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '门禁引用ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `gate_code` varchar(64) NOT NULL COMMENT '所属门禁码',
  `ref_type` varchar(16) NOT NULL COMMENT '引用类型：TASK/DELIVERABLE/STATE/PROCESS',
  `ref_code` varchar(64) NOT NULL COMMENT '引用编码',
  `ref_version` varchar(32) DEFAULT NULL COMMENT '引用版本（流程引用时使用）',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_gate_ref` (`template_revision_id`,`gate_code`,`ref_type`,`ref_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板门禁引用行';

CREATE TABLE `proj_project_template_match_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '匹配决策历史ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `trigger_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'INITIAL_CREATE/SOURCE_CORRECTION/MANUAL_ADJUSTMENT',
  `record_purpose` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CREATE_DECISION/IMPACT_EVALUATION',
  `input_origin` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MANUAL/SOURCE',
  `snapshot_schema_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '四属性快照结构版本',
  `before_attribute_snapshot` json DEFAULT NULL COMMENT '变更前四属性快照；首次创建为空',
  `attribute_snapshot` json NOT NULL COMMENT '本次判定使用的四属性完整快照',
  `attribute_owner_snapshot` json NOT NULL COMMENT '四属性Owner快照',
  `source_owner` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源事实Owner',
  `source_system` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统；手工为MANUAL',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源业务键',
  `source_event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源事件ID',
  `source_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `source_occurred_at` datetime(3) DEFAULT NULL COMMENT '来源发生时间',
  `source_value_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源原值SHA-256',
  `mapping_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源映射版本',
  `matcher_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板匹配规则版本',
  `match_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'UNIQUE/NO_MATCH/MULTIPLE_MATCHES',
  `candidate_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '排序后候选集合SHA-256',
  `decision_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首次创建AUTO_UNIQUE/EXPLICIT_SELECTION',
  `matched_template_id` bigint DEFAULT NULL COMMENT '唯一命中或显式选中模板ID',
  `matched_template_revision_id` bigint DEFAULT NULL COMMENT '唯一命中或显式选中模板修订ID',
  `frozen_template_revision_id` bigint NOT NULL COMMENT '项目当前冻结模板修订ID',
  `impact_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NOT_APPLICABLE/NO_IMPACT/CANDIDATE_CHANGED/NO_MATCH/MULTIPLE_MATCHES',
  `operator_id` bigint NOT NULL COMMENT '认证用户或注册服务主体稳定ID',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '去除首尾空白后的创建或调整原因',
  `occurred_at` datetime(3) NOT NULL COMMENT '业务发生时间',
  `recorded_at` datetime(3) NOT NULL COMMENT '事实写入时间',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '命令幂等键',
  `request_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求摘要',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定业务操作ID',
  `trace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可选技术Trace关联',
  `audit_log_id` bigint DEFAULT NULL COMMENT '可选系统操作日志关联',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_template_match_history_operation` (`tenant_id`,`operation_id`),
  UNIQUE KEY `uk_proj_template_match_history_idempotency` (`tenant_id`,`project_id`,`idempotency_key`),
  KEY `idx_proj_template_match_history_project_time` (`tenant_id`,`project_id`,`occurred_at`,`id`),
  KEY `idx_proj_template_match_history_result` (`tenant_id`,`project_id`,`match_result`,`impact_result`,`occurred_at`),
  CONSTRAINT `ck_proj_template_match_history_decision` CHECK (((`decision_mode` is null) or (`decision_mode` in (_utf8mb4'AUTO_UNIQUE',_utf8mb4'EXPLICIT_SELECTION')))),
  CONSTRAINT `ck_proj_template_match_history_impact` CHECK ((`impact_result` in (_utf8mb4'NOT_APPLICABLE',_utf8mb4'NO_IMPACT',_utf8mb4'CANDIDATE_CHANGED',_utf8mb4'NO_MATCH',_utf8mb4'MULTIPLE_MATCHES'))),
  CONSTRAINT `ck_proj_template_match_history_matched` CHECK ((((`match_result` = _utf8mb4'UNIQUE') and (`matched_template_id` is not null) and (`matched_template_revision_id` is not null)) or ((`match_result` = _utf8mb4'MULTIPLE_MATCHES') and (`trigger_type` = _utf8mb4'INITIAL_CREATE') and (`decision_mode` = _utf8mb4'EXPLICIT_SELECTION') and (`matched_template_id` is not null) and (`matched_template_revision_id` is not null)) or ((`match_result` in (_utf8mb4'NO_MATCH',_utf8mb4'MULTIPLE_MATCHES')) and (`trigger_type` <> _utf8mb4'INITIAL_CREATE') and (`matched_template_id` is null) and (`matched_template_revision_id` is null)))),
  CONSTRAINT `ck_proj_template_match_history_origin` CHECK ((`input_origin` in (_utf8mb4'MANUAL',_utf8mb4'SOURCE'))),
  CONSTRAINT `ck_proj_template_match_history_purpose` CHECK ((`record_purpose` in (_utf8mb4'CREATE_DECISION',_utf8mb4'IMPACT_EVALUATION'))),
  CONSTRAINT `ck_proj_template_match_history_result` CHECK ((`match_result` in (_utf8mb4'UNIQUE',_utf8mb4'NO_MATCH',_utf8mb4'MULTIPLE_MATCHES'))),
  CONSTRAINT `ck_proj_template_match_history_source` CHECK (((`trigger_type` <> _utf8mb4'SOURCE_CORRECTION') or ((`input_origin` = _utf8mb4'SOURCE') and (`source_owner` is not null) and (`source_key` is not null) and (`source_event_id` is not null) and (`source_version` is not null) and (`source_occurred_at` is not null) and (`source_value_digest` is not null) and (`mapping_version` is not null)))),
  CONSTRAINT `ck_proj_template_match_history_trigger` CHECK ((`trigger_type` in (_utf8mb4'INITIAL_CREATE',_utf8mb4'SOURCE_CORRECTION',_utf8mb4'MANUAL_ADJUSTMENT'))),
  CONSTRAINT `ck_proj_template_match_history_trigger_purpose` CHECK ((((`trigger_type` = _utf8mb4'INITIAL_CREATE') and (`record_purpose` = _utf8mb4'CREATE_DECISION') and (`before_attribute_snapshot` is null) and (`impact_result` = _utf8mb4'NOT_APPLICABLE') and (`decision_mode` is not null)) or ((`trigger_type` in (_utf8mb4'SOURCE_CORRECTION',_utf8mb4'MANUAL_ADJUSTMENT')) and (`record_purpose` = _utf8mb4'IMPACT_EVALUATION') and (`before_attribute_snapshot` is not null) and (`decision_mode` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PM-07模板匹配决策与影响评估永久历史（业务字段只插入不更新）';

CREATE TABLE `proj_project_template_milestone_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '里程碑定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `milestone_code` varchar(64) NOT NULL COMMENT '里程碑码（版本内唯一）',
  `name` varchar(128) NOT NULL COMMENT '里程碑名称',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `timing` varchar(64) DEFAULT NULL COMMENT '时点说明',
  `criteria` varchar(500) DEFAULT NULL COMMENT '达成标准',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_milestone` (`template_revision_id`,`milestone_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板里程碑定义';

CREATE TABLE `proj_project_template_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '版本ID',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `revision_no` int NOT NULL DEFAULT '0' COMMENT '版本号（0=草稿工作副本，发布时递增冻结）',
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT草稿/PUBLISHED已发布',
  `signing_method` varchar(64) DEFAULT NULL COMMENT '签约方式（字典 pms_signing_method，NULL=不限）',
  `project_category` varchar(64) DEFAULT NULL COMMENT '项目类别（字典 pms_project_category，NULL=不限）',
  `implementation_method` varchar(64) DEFAULT NULL COMMENT '实施方式（字典 pms_implementation_method，NULL=不限）',
  `major_project_level` varchar(64) DEFAULT NULL COMMENT '重大项目级别（CRM来源属性映射，NULL=不限）',
  `process_definition_key` varchar(64) DEFAULT NULL COMMENT '模板级流程定义引用（仅存引用，不校验流程内部）',
  `process_definition_version` varchar(32) DEFAULT NULL COMMENT '流程定义版本引用',
  `validation_summary` varchar(1000) DEFAULT NULL COMMENT '最近一次发布校验结果摘要（留痕）',
  `published_by` varchar(64) DEFAULT NULL COMMENT '发布人',
  `published_time` datetime DEFAULT NULL COMMENT '发布时间',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_snapshot` json DEFAULT NULL,
  `designer_schema_version` int unsigned DEFAULT NULL,
  `designer_document` json DEFAULT NULL,
  `execution_schema_version` int unsigned DEFAULT NULL,
  `execution_snapshot` json DEFAULT NULL,
  `compiler_version` varchar(64) DEFAULT NULL,
  `snapshot_hash` char(64) DEFAULT NULL,
  `closure_policy` json DEFAULT NULL COMMENT 'Explicit NORMAL policy frozen at template publication',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_template_revision` (`tenant_id`,`template_id`,`revision_no`),
  KEY `idx_template_status_revision` (`template_id`,`status`,`revision_no`),
  CONSTRAINT `ck_project_template_revision_designer_v2` CHECK ((((`designer_document` is null) and (`designer_schema_version` is null)) or ((`designer_document` is not null) and (`designer_schema_version` > 0)))),
  CONSTRAINT `ck_project_template_revision_execution_v2` CHECK ((((`execution_snapshot` is null) and (`execution_schema_version` is null) and (`compiler_version` is null) and (`snapshot_hash` is null)) or ((`execution_snapshot` is not null) and (`execution_schema_version` > 0) and (`compiler_version` is not null) and regexp_like(`snapshot_hash`,_utf8mb4'^[0-9a-f]{64}$'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板版本（四维条件+流程引用，发布后只读）';

CREATE TABLE `proj_project_template_stage_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `stage_code` varchar(32) NOT NULL COMMENT '阶段码（S0～S6）',
  `name` varchar(128) NOT NULL COMMENT '阶段名称',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '阶段顺序',
  `entry_criteria` varchar(500) DEFAULT NULL COMMENT '准入条件说明',
  `exit_criteria` varchar(500) DEFAULT NULL COMMENT '准出条件说明',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  `start_node` bit(1) DEFAULT NULL,
  `terminal_node` bit(1) DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_stage` (`template_revision_id`,`stage_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板阶段定义';

CREATE TABLE `proj_project_template_task_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `template_revision_id` bigint NOT NULL COMMENT '项目模板发布版本逻辑引用',
  `stage_definition_key` varchar(128) NOT NULL,
  `task_definition_key` varchar(128) NOT NULL,
  `parent_task_definition_key` varchar(128) DEFAULT NULL,
  `task_code` varchar(64) NOT NULL COMMENT '任务码（版本内唯一）',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务定义名称',
  `parent_task_code` varchar(64) DEFAULT NULL COMMENT '父任务码（NULL=顶层）',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `priority` int NOT NULL DEFAULT '2' COMMENT '优先级',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `estimated_hours` decimal(6,1) DEFAULT NULL COMMENT '预估工时',
  `satisfaction_timing` varchar(32) DEFAULT NULL COMMENT '满意度适用时点（NULL=不适用，由ACC-02消费）',
  `description` varchar(500) DEFAULT NULL COMMENT '任务说明',
  `work_binding_type_code` varchar(32) NOT NULL,
  `target_context_code` varchar(32) DEFAULT NULL,
  `target_object_type` varchar(64) DEFAULT NULL,
  `target_object_key` varchar(128) DEFAULT NULL,
  `component_key` varchar(128) DEFAULT NULL,
  `dynamic_form_revision_id` bigint DEFAULT NULL,
  `approval_definition_key` varchar(128) DEFAULT NULL,
  `binding_config` json NOT NULL COMMENT '受控绑定参数与Schema版本',
  `permission_policy_ref` varchar(512) NOT NULL,
  `completion_rule_type_code` varchar(32) NOT NULL,
  `completion_rule_config` json NOT NULL COMMENT '完成规则配置与Schema版本',
  `gate_ref` varchar(512) DEFAULT NULL,
  `definition_version` int unsigned NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `definition_revision_id` bigint DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_task` (`template_revision_id`,`task_code`),
  UNIQUE KEY `uk_project_template_task_definition_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_project_template_task_definition_v18` (`tenant_id`,`template_revision_id`,`task_definition_key`),
  KEY `idx_revision` (`template_revision_id`),
  KEY `idx_project_template_task_definition_tree_v18` (`tenant_id`,`template_revision_id`,`stage_definition_key`,`parent_task_definition_key`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目模板任务定义';

CREATE TABLE `proj_project_tree_change` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目树变更编号',
  `change_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` bigint NOT NULL,
  `parent_id_before` bigint DEFAULT NULL,
  `parent_id_after` bigint DEFAULT NULL,
  `base_tree_version` bigint NOT NULL,
  `new_tree_version` bigint NOT NULL,
  `actor_id` bigint NOT NULL,
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_tree_change_batch` (`tenant_id`,`change_batch_id`,`project_id`),
  KEY `idx_proj_tree_change_project` (`tenant_id`,`project_id`,`occurred_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目树追加变更';

CREATE TABLE `proj_project_tree_path` (
  `id` bigint NOT NULL,
  `tree_version` bigint NOT NULL,
  `root_project_id` bigint NOT NULL,
  `ancestor_project_id` bigint NOT NULL,
  `descendant_project_id` bigint NOT NULL,
  `distance` int NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_tree_path` (`tenant_id`,`root_project_id`,`tree_version`,`ancestor_project_id`,`descendant_project_id`),
  KEY `idx_proj_tree_path_ancestor` (`tenant_id`,`root_project_id`,`tree_version`,`ancestor_project_id`,`distance`,`descendant_project_id`),
  KEY `idx_proj_tree_path_descendant` (`tenant_id`,`root_project_id`,`tree_version`,`descendant_project_id`,`ancestor_project_id`),
  CONSTRAINT `ck_proj_tree_path_distance` CHECK ((`distance` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目树祖先路径投影';

CREATE TABLE `proj_project_tree_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目树版本编号',
  `root_project_id` bigint NOT NULL,
  `tree_version` bigint NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `change_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_count` int NOT NULL DEFAULT '0',
  `path_count` int NOT NULL DEFAULT '0',
  `activated_at` datetime DEFAULT NULL,
  `failed_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_tree_version` (`tenant_id`,`root_project_id`,`tree_version`),
  KEY `idx_proj_tree_version_active` (`tenant_id`,`root_project_id`,`status`,`tree_version`),
  KEY `proj_project_tree_version_tenant_id_IDX` (`tenant_id`,`deleted`,`status`,`root_project_id`,`tree_version`) USING BTREE,
  CONSTRAINT `ck_proj_tree_version_status` CHECK ((`status` in (_utf8mb4'BUILDING',_utf8mb4'ACTIVE',_utf8mb4'FAILED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目树完整版本';

CREATE TABLE `proj_result_evidence_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `scan_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `result_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `formation_sequence` bigint DEFAULT NULL,
  `eligibility` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `observation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_evidence_candidate` (`tenant_id`,`scan_id`,`candidate_id`),
  KEY `ix_evidence_item_page` (`tenant_id`,`project_id`,`scan_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `proj_result_evidence_scan` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `subscription_id` bigint NOT NULL,
  `subscription_version` int NOT NULL,
  `through_sequence` bigint NOT NULL,
  `after_candidate_id` bigint NOT NULL,
  `accumulator` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `version` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_evidence_scan` (`tenant_id`,`subscription_id`,`subscription_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `proj_result_subscription` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `plan_version_id` bigint NOT NULL,
  `execution_id` bigint NOT NULL,
  `node_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `node_id` bigint NOT NULL,
  `node_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `contract_id` bigint NOT NULL,
  `subscription_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `channel_id` bigint NOT NULL,
  `configuration` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `baseline_sequence` bigint NOT NULL,
  `phase` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `inventory_cursor` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `processed_sequence` bigint NOT NULL,
  `through_sequence` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_result_subscription_round` (`tenant_id`,`plan_version_id`,`execution_id`,`subscription_key`),
  KEY `ix_result_subscription_channel` (`tenant_id`,`channel_id`,`id`),
  KEY `ix_result_subscription_execution` (`tenant_id`,`project_id`,`execution_id`,`subscription_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `proj_result_subscription_candidate` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `subscription_id` bigint NOT NULL,
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `result_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `formation_sequence` bigint DEFAULT NULL,
  `observed_sequence` bigint NOT NULL,
  `observation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_subscription_candidate` (`tenant_id`,`subscription_id`,`object_id`,`result_id`),
  KEY `ix_subscription_candidate_page` (`tenant_id`,`project_id`,`subscription_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `proj_stage_suggestion_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段建议规则编号',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '行版本（乐观锁）',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `stage_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参与计划的阶段编码',
  `signing_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签约方式（字典 pms_signing_method）；空=全部签约方式',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议来源：PMS_IMPORTED 带入自身计划验收时间 / DURATION_REQUIRE 锚工期要求 / STAGE_PLAN 参照阶段',
  `reference_stage_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参照阶段编码（STAGE_PLAN 时必填，须晚于自身阶段）',
  `offset_months` int NOT NULL DEFAULT '0' COMMENT '参照时间偏移月数（负=提前）',
  `offset_days` int NOT NULL DEFAULT '0' COMMENT '参照时间偏移天数（负=提前，如 -14=2周）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注（需求原文与映射说明）',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_stage_variant` (`tenant_id`,`stage_code`,`signing_method`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='3.1 工期建议计划时间规则（Demo 页面9 / Excel 3.1；建议最迟完成 = 参照时间 - 偏移）';

CREATE TABLE `proj_stage_transition_definition` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `template_revision_id` bigint NOT NULL,
  `transition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `from_stage_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `to_stage_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `condition_rule_revision_id` bigint DEFAULT NULL,
  `priority` int NOT NULL,
  `is_default` tinyint unsigned NOT NULL DEFAULT '0',
  `default_marker` tinyint GENERATED ALWAYS AS ((case when (`is_default` = 1) then 1 else NULL end)) STORED,
  `revision_no` bigint unsigned NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_std_code` (`tenant_id`,`template_revision_id`,`transition_code`),
  UNIQUE KEY `uk_std_default` (`tenant_id`,`template_revision_id`,`from_stage_code`,`default_marker`),
  KEY `idx_std_out` (`tenant_id`,`template_revision_id`,`from_stage_code`,`priority`),
  CONSTRAINT `ck_std_flags` CHECK (((`is_default` in (0,1)) and (`revision_no` > 0))),
  CONSTRAINT `ck_std_self` CHECK ((`from_stage_code` <> `to_stage_code`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `proj_task_business_link` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `task_id` bigint DEFAULT NULL,
  `execution_contract_id` bigint NOT NULL,
  `contract_version` int NOT NULL,
  `owner_context` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `object_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `fact_version` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `linked_by` bigint NOT NULL,
  `linked_at` datetime(6) NOT NULL,
  `unlinked_by` bigint DEFAULT NULL,
  `unlinked_at` datetime(6) DEFAULT NULL,
  `active_marker` tinyint GENERATED ALWAYS AS (if((`unlinked_at` is null),1,NULL)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `node_execution_id` bigint DEFAULT NULL COMMENT '自动关联接收方：当前节点执行实例',
  `stage_id` bigint DEFAULT NULL COMMENT '阶段实例；与任务实例身份互斥',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_business_active` (`tenant_id`,`task_id`,`owner_context`,`object_type`,`object_id`,`active_marker`),
  UNIQUE KEY `uk_stage_business_active` (`tenant_id`,`stage_id`,`owner_context`,`object_type`,`object_id`,`active_marker`),
  KEY `idx_task_business_history` (`tenant_id`,`project_id`,`task_id`,`linked_at`,`id`),
  KEY `idx_task_business_execution` (`tenant_id`,`project_id`,`task_id`,`node_execution_id`),
  KEY `idx_stage_business_execution` (`tenant_id`,`project_id`,`stage_id`,`node_execution_id`),
  CONSTRAINT `ck_business_link_node` CHECK ((((`task_id` is not null) and (`stage_id` is null)) or ((`task_id` is null) and (`stage_id` is not null)))),
  CONSTRAINT `ck_task_business_interval` CHECK ((((`unlinked_at` is null) and (`unlinked_by` is null)) or ((`unlinked_at` is not null) and (`unlinked_by` is not null) and (`unlinked_at` >= `linked_at`)))),
  CONSTRAINT `ck_task_business_versions` CHECK (((`contract_version` > 0) and (`version` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task to Owner business object relationship history';

CREATE TABLE `proj_task_dependency` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务依赖ID',
  `project_id` bigint NOT NULL COMMENT '所属项目ID',
  `predecessor_task_id` bigint NOT NULL COMMENT '前置任务ID',
  `successor_task_id` bigint NOT NULL COMMENT '后置任务ID',
  `dependency_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '依赖类型编码',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_dependency` (`tenant_id`,`predecessor_task_id`,`successor_task_id`,`dependency_type_code`),
  KEY `idx_proj_task_dependency_successor` (`tenant_id`,`project_id`,`successor_task_id`,`predecessor_task_id`),
  KEY `fk_proj_task_dependency_predecessor` (`tenant_id`,`project_id`,`predecessor_task_id`),
  CONSTRAINT `fk_proj_task_dependency_predecessor` FOREIGN KEY (`tenant_id`, `project_id`, `predecessor_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `fk_proj_task_dependency_successor` FOREIGN KEY (`tenant_id`, `project_id`, `successor_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `chk_proj_task_dependency_distinct` CHECK ((`predecessor_task_id` <> `successor_task_id`)),
  CONSTRAINT `chk_proj_task_dependency_type` CHECK ((`dependency_type_code` in (_utf8mb4'FINISH_TO_START',_utf8mb4'START_TO_START',_utf8mb4'FINISH_TO_FINISH',_utf8mb4'START_TO_FINISH')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务基础依赖';

CREATE TABLE `proj_task_state_machine_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务状态机版本ID',
  `revision_no` int unsigned NOT NULL COMMENT '租户内版本号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DRAFT/PUBLISHED',
  `effective_from` datetime(3) NOT NULL COMMENT '生效时间',
  `published_by` bigint DEFAULT NULL COMMENT '发布人用户ID',
  `published_at` datetime(3) DEFAULT NULL COMMENT '发布时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_state_revision_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_proj_task_state_revision_no` (`tenant_id`,`revision_no`),
  KEY `idx_proj_task_state_revision_published` (`tenant_id`,`status`,`revision_no`),
  CONSTRAINT `chk_proj_task_state_revision_publish_time` CHECK ((((`status` = _utf8mb4'PUBLISHED') and (`published_at` is not null)) or ((`status` = _utf8mb4'DRAFT') and (`published_at` is null)))),
  CONSTRAINT `chk_proj_task_state_revision_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'PUBLISHED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='租户级项目任务状态机版本';

CREATE TABLE `proj_task_state_transition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务状态迁移ID',
  `revision_id` bigint NOT NULL COMMENT '状态机版本ID',
  `from_status_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源状态编码',
  `action_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作编码',
  `to_status_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标状态编码',
  `standard_status_mapping` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标状态的核心标准映射',
  `allowed_role_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用主体约束编码',
  `entry_condition` json NOT NULL COMMENT '进入条件',
  `exit_condition` json NOT NULL COMMENT '退出条件',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_state_transition` (`tenant_id`,`revision_id`,`from_status_code`,`action_code`),
  KEY `idx_proj_task_state_transition_target` (`tenant_id`,`revision_id`,`to_status_code`,`action_code`),
  CONSTRAINT `fk_proj_task_state_transition_revision` FOREIGN KEY (`tenant_id`, `revision_id`) REFERENCES `proj_task_state_machine_revision` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务状态机合法迁移';

CREATE TABLE `proj_task_tree_path` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务闭包路径ID',
  `project_id` bigint NOT NULL COMMENT '所属项目ID',
  `ancestor_task_id` bigint NOT NULL COMMENT '祖先任务ID',
  `descendant_task_id` bigint NOT NULL COMMENT '后代任务ID',
  `distance` int unsigned NOT NULL COMMENT '路径距离，自反路径为0',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_tree_path` (`tenant_id`,`project_id`,`ancestor_task_id`,`descendant_task_id`),
  KEY `idx_proj_task_tree_path_ancestor` (`tenant_id`,`project_id`,`ancestor_task_id`,`distance`,`descendant_task_id`),
  KEY `idx_proj_task_tree_path_descendant` (`tenant_id`,`project_id`,`descendant_task_id`,`ancestor_task_id`),
  CONSTRAINT `fk_proj_task_tree_path_ancestor` FOREIGN KEY (`tenant_id`, `project_id`, `ancestor_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `fk_proj_task_tree_path_descendant` FOREIGN KEY (`tenant_id`, `project_id`, `descendant_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务树祖先闭包当前投影';

CREATE TABLE `proj_team_batch_change` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批次编号，全局唯一',
  `source_user_id` bigint NOT NULL COMMENT '源用户编号',
  `target_user_id` bigint NOT NULL COMMENT '目标用户编号',
  `scope_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SELECTED' COMMENT '范围类型 ALL 全部项目 / SELECTED 指定项目',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更原因',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0处理中 1成功 2部分成功 3失败',
  `total_count` int NOT NULL DEFAULT '0' COMMENT '总条数',
  `success_count` int NOT NULL DEFAULT '0' COMMENT '成功条数',
  `failure_count` int NOT NULL DEFAULT '0' COMMENT '失败条数',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_team_batch_change_no` (`batch_no`),
  KEY `idx_pms_team_batch_change_source` (`source_user_id`),
  KEY `idx_pms_team_batch_change_target` (`target_user_id`),
  KEY `idx_pms_team_batch_change_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 团队批量变更批次';

CREATE TABLE `proj_team_batch_change_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `batch_id` bigint NOT NULL COMMENT '批次编号',
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `project_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称（冗余）',
  `team_member_id` bigint NOT NULL COMMENT '团队成员编号',
  `before_role` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更前角色编码',
  `after_role` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更后角色编码',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待处理 1成功 2失败',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_team_batch_item_batch` (`batch_id`),
  KEY `idx_pms_team_batch_item_project` (`project_id`),
  KEY `idx_pms_team_batch_item_member` (`team_member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 团队批量变更明细';

CREATE TABLE `res_outsource_request` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '外包单号，全局唯一',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '外包名称',
  `outsource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LABOR' COMMENT '外包类型 LABOR 劳务 / SERVICE 服务 / PROJECT_SUBPROJ 子项目',
  `work_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工作内容（富文本）',
  `work_quantity` decimal(12,2) DEFAULT NULL COMMENT '工作量',
  `work_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作量单位',
  `planned_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `planned_end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `estimated_cost` decimal(14,2) DEFAULT NULL COMMENT '预估费用',
  `actual_cost` decimal(14,2) DEFAULT NULL COMMENT '实际费用',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CNY' COMMENT '币种',
  `vendor_id` bigint DEFAULT NULL COMMENT '服务商编号',
  `vendor_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务商名称',
  `contact_user_id` bigint DEFAULT NULL COMMENT '联系人编号',
  `contact_phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `attachment_files` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件URL列表（JSON数组）',
  `trigger_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发来源 MANUAL 手动 / RESOURCE_READY 资源就绪 / SOLUTION 实施方案',
  `trigger_ref_id` bigint DEFAULT NULL COMMENT '触发来源业务编号',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人编号',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人编号',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `approve_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批动作 PASS/REJECT/RETURN/TRANSFER/COUNTERSIGN',
  `bpm_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPM流程实例ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2审批中 3已通过 4已驳回 5已撤回 6已终止',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_outsource_code` (`code`),
  KEY `idx_pms_eng_outsource_project` (`project_id`),
  KEY `idx_pms_eng_outsource_status` (`status`),
  KEY `idx_pms_eng_outsource_applicant` (`applicant_user_id`),
  KEY `idx_pms_eng_outsource_trigger` (`trigger_source`,`trigger_ref_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 外包申请单（FR-ENG-002）';

CREATE TABLE `sol_construction_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '施工计划根ID',
  `project_id` bigint NOT NULL COMMENT 'PROJ项目ID',
  `current_duration_revision_id` bigint DEFAULT NULL COMMENT '当前生效工期版本ID',
  `pending_change_id` bigint DEFAULT NULL COMMENT '当前在途工期变更ID',
  `plan_recalculation_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划重算影响状态',
  `plan_recalculation_source_revision_id` bigint DEFAULT NULL COMMENT '触发计划待重算的工期版本ID',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_construction_plan_project` (`tenant_id`,`project_id`),
  UNIQUE KEY `uk_sol_construction_plan_tenant_row` (`tenant_id`,`id`),
  KEY `idx_sol_construction_plan_current_revision` (`tenant_id`,`current_duration_revision_id`),
  KEY `idx_sol_construction_plan_pending_change` (`tenant_id`,`pending_change_id`),
  KEY `idx_sol_construction_plan_recalculation` (`tenant_id`,`plan_recalculation_status_code`,`project_id`),
  KEY `fk_sol_construction_plan_recalculation_revision` (`tenant_id`,`plan_recalculation_source_revision_id`),
  CONSTRAINT `fk_sol_construction_plan_current_revision` FOREIGN KEY (`tenant_id`, `current_duration_revision_id`) REFERENCES `sol_construction_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_construction_plan_pending_change` FOREIGN KEY (`tenant_id`, `pending_change_id`) REFERENCES `sol_construction_plan_change` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_construction_plan_recalculation_revision` FOREIGN KEY (`tenant_id`, `plan_recalculation_source_revision_id`) REFERENCES `sol_construction_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_construction_plan_recalculation_status` CHECK ((`plan_recalculation_status_code` in (_utf8mb4'PENDING_RECALCULATION',_utf8mb4'RECALCULATED',_utf8mb4'RECALCULATION_FAILED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL施工计划根与当前工期指针';

CREATE TABLE `sol_construction_plan_change` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工期变更ID',
  `plan_id` bigint NOT NULL COMMENT '施工计划根ID',
  `base_revision_id` bigint NOT NULL COMMENT '变更基准工期版本ID',
  `candidate_revision_id` bigint NOT NULL COMMENT '候选工期版本ID',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '变更审批生命周期状态',
  `reason_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '变更原因字典值',
  `reason_detail` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '变更原因说明',
  `customer_evidence_required` bit(1) NOT NULL COMMENT '是否要求客户依据',
  `customer_evidence_file_id` bigint DEFAULT NULL COMMENT '客户依据FileArtifact稳定ID',
  `customer_evidence_file_version` int unsigned DEFAULT NULL COMMENT '客户依据文件版本',
  `customer_evidence_reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户依据FileReference稳定槽位键',
  `customer_evidence_artifact_version` int unsigned DEFAULT NULL COMMENT '冻结FileArtifact事实版本',
  `customer_evidence_reference_version` int unsigned DEFAULT NULL COMMENT '冻结FileReference事实版本',
  `customer_evidence_availability_version` int unsigned DEFAULT NULL COMMENT '冻结FileVersion可用性事实版本',
  `customer_evidence_scope_version` bigint DEFAULT NULL COMMENT '冻结业务对象授权范围版本',
  `process_definition_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冻结BPM流程定义键',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冻结BPM流程实例ID',
  `submitted_at` datetime(3) DEFAULT NULL COMMENT '提交审批时间',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人用户ID',
  `approver_user_id` bigint DEFAULT NULL COMMENT '冻结审批人用户ID',
  `approved_at` datetime(3) DEFAULT NULL COMMENT '审批终态时间',
  `approval_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `created_at` datetime(3) NOT NULL COMMENT '创建时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_construction_plan_change_candidate` (`tenant_id`,`plan_id`,`candidate_revision_id`),
  UNIQUE KEY `uk_sol_construction_plan_change_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_sol_construction_plan_change_process` (`tenant_id`,`process_instance_id`),
  KEY `idx_sol_construction_plan_change_status` (`tenant_id`,`plan_id`,`status_code`,`id`),
  KEY `idx_sol_construction_plan_change_applicant` (`tenant_id`,`applicant_user_id`,`created_at`,`id`),
  KEY `idx_sol_construction_plan_change_approver` (`tenant_id`,`approver_user_id`,`approved_at`,`id`),
  KEY `fk_sol_construction_plan_change_base_revision` (`tenant_id`,`base_revision_id`),
  KEY `fk_sol_construction_plan_change_candidate_revision` (`tenant_id`,`candidate_revision_id`),
  CONSTRAINT `fk_sol_construction_plan_change_base_revision` FOREIGN KEY (`tenant_id`, `base_revision_id`) REFERENCES `sol_construction_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_construction_plan_change_candidate_revision` FOREIGN KEY (`tenant_id`, `candidate_revision_id`) REFERENCES `sol_construction_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_construction_plan_change_plan` FOREIGN KEY (`tenant_id`, `plan_id`) REFERENCES `sol_construction_plan` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_construction_plan_change_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PENDING_APPROVAL',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'WITHDRAWN'))),
  CONSTRAINT `chk_sol_construction_plan_change_workflow` CHECK (((`status_code` <> _utf8mb4'PENDING_APPROVAL') or ((`process_definition_key` is not null) and (`process_instance_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL项目工期变更与审批关联';

CREATE TABLE `sol_construction_plan_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工期版本ID',
  `plan_id` bigint NOT NULL COMMENT '施工计划根ID',
  `revision_no` int unsigned NOT NULL COMMENT '项目内工期版本号',
  `calculation_basis_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工期计算口径',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `duration_days` int unsigned NOT NULL COMMENT '自然日工期',
  `source_change_id` bigint DEFAULT NULL COMMENT '来源工期变更ID',
  `frozen_at` datetime(3) DEFAULT NULL COMMENT '提交冻结时间',
  `effective_at` datetime(3) DEFAULT NULL COMMENT '生效时间',
  `created_by` bigint NOT NULL COMMENT '创建人用户ID',
  `created_at` datetime(3) NOT NULL COMMENT '创建时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_construction_plan_revision_no` (`tenant_id`,`plan_id`,`revision_no`),
  UNIQUE KEY `uk_sol_construction_plan_revision_tenant_row` (`tenant_id`,`id`),
  CONSTRAINT `fk_sol_construction_plan_revision_plan` FOREIGN KEY (`tenant_id`, `plan_id`) REFERENCES `sol_construction_plan` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_construction_plan_revision_basis` CHECK ((`calculation_basis_code` in (_utf8mb4'DATE_RANGE',_utf8mb4'DURATION_FROM_START'))),
  CONSTRAINT `chk_sol_construction_plan_revision_dates` CHECK (((`end_date` >= `start_date`) and (((to_days(`end_date`) - to_days(`start_date`)) + 1) = `duration_days`))),
  CONSTRAINT `chk_sol_construction_plan_revision_duration` CHECK ((`duration_days` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL项目工期版本';

CREATE TABLE `sol_dynamic_form_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '固定表单实例ID',
  `preparation_id` bigint NOT NULL COMMENT '准备业务版本ID',
  `item_id` bigint NOT NULL COMMENT '工勘项ID',
  `form_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '固定表单编码',
  `form_version` int unsigned NOT NULL COMMENT '固定表单版本',
  `schema_snapshot` json NOT NULL COMMENT '固定表单Schema快照',
  `value_snapshot` json NOT NULL COMMENT '表单值快照',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单状态',
  `frozen_at` datetime(3) DEFAULT NULL COMMENT '冻结时间',
  `frozen_by` bigint DEFAULT NULL COMMENT '冻结操作者',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_dynamic_form_instance` (`tenant_id`,`preparation_id`,`item_id`,`form_code`),
  UNIQUE KEY `uk_sol_dynamic_form_instance_tenant_row` (`tenant_id`,`id`),
  KEY `fk_sol_dynamic_form_instance_item` (`tenant_id`,`item_id`),
  CONSTRAINT `fk_sol_dynamic_form_instance_item` FOREIGN KEY (`tenant_id`, `item_id`) REFERENCES `sol_preparation_item` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_dynamic_form_instance_preparation` FOREIGN KEY (`tenant_id`, `preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_dynamic_form_instance_frozen` CHECK (((`status_code` <> _utf8mb4'FROZEN') or ((`frozen_at` is not null) and (`frozen_by` is not null)))),
  CONSTRAINT `chk_sol_dynamic_form_instance_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'FROZEN'))),
  CONSTRAINT `chk_sol_dynamic_form_instance_version` CHECK ((`form_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02固定表单实例';

CREATE TABLE `sol_eng_briefing` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交底书编号（如 BR-2026-001）',
  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交底书名称',
  `briefing_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STANDARD' COMMENT '交底类型：STANDARD标准/EMERGENCY紧急/CUSTOM自定义',
  `template_id` bigint DEFAULT NULL COMMENT '关联交底书模板ID',
  `template_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '模板快照JSON（模板版本固定到实例）',
  `source_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '前序基线数据快照JSON（需求/方案/工勘聚合）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '交底内容富文本',
  `file_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成的文件URL',
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `file_checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件校验值',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已生成/2已审核/3已发布/4已作废',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `generate_time` datetime DEFAULT NULL COMMENT '生成时间',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审核人',
  `approve_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核意见',
  `approve_time` datetime DEFAULT NULL COMMENT '审核时间',
  `creator_user_id` bigint DEFAULT NULL COMMENT '编制人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_briefing_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_briefing_project` (`project_id`),
  KEY `idx_pms_eng_briefing_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工程交底书';

CREATE TABLE `sol_eng_requirement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '需求编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '需求名称',
  `requirement_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BUSINESS' COMMENT 'BUSINESS 业务需求 / INTERFACE 接口规划',
  `template_id` bigint DEFAULT NULL COMMENT '关联文档模板ID',
  `template_version_id` bigint DEFAULT NULL COMMENT '关联模板版本ID',
  `template_snapshot` json DEFAULT NULL COMMENT '模板快照JSON（创建时的模板结构，不可变）',
  `section_data` json DEFAULT NULL COMMENT '章节填写数据JSON（key=章节编码，value=章节内容）',
  `background` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '项目背景目标',
  `topology` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '拓扑',
  `transmission` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '传输',
  `traffic` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '流量',
  `business` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '业务',
  `ip_plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'IP 规划',
  `redundancy` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '冗余',
  `protection` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '防护',
  `o_and_m` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '运维',
  `log_retention` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '日志留存',
  `interface_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '接口关系内容（type=INTERFACE 时使用）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2已生效 3已归档',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_requirement_code` (`project_id`,`code`),
  KEY `idx_pms_eng_requirement_project` (`project_id`),
  KEY `idx_pms_eng_requirement_type` (`project_id`,`requirement_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='需求分析与接口规划';

CREATE TABLE `sol_eng_resource_ready` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '就绪编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源名称',
  `resource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PEOPLE 备件 / SPARE 物料 / TOOL 工具 / TEST_ENV 测试环境 / WINDOW 时间窗口 / APPROVAL 客户批准',
  `equipment_id` bigint DEFAULT NULL COMMENT '关联设备编号',
  `quantity` int DEFAULT NULL COMMENT '数量',
  `ready_status` tinyint NOT NULL DEFAULT '0' COMMENT '0未就绪 1已就绪 2异常',
  `ready_time` datetime DEFAULT NULL COMMENT '就绪时间',
  `ready_user_id` bigint DEFAULT NULL COMMENT '就绪确认人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_resource_ready_code` (`project_id`,`code`),
  KEY `idx_pms_eng_resource_ready_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资源与备件就绪';

CREATE TABLE `sol_eng_site_survey` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工勘编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工勘名称',
  `survey_date` date DEFAULT NULL COMMENT '工勘日期',
  `surveyor_user_id` bigint DEFAULT NULL COMMENT '工勘责任人',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工勘地点',
  `address_id` bigint DEFAULT NULL,
  `address_version` int unsigned DEFAULT NULL,
  `site_id` bigint DEFAULT NULL,
  `site_version` int unsigned DEFAULT NULL,
  `site_location_id` bigint DEFAULT NULL,
  `site_location_version` int unsigned DEFAULT NULL,
  `location_resolution_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED',
  `address_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `location_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `power_supply` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供电条件',
  `cabinet` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机柜条件',
  `network_port` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网口条件',
  `fiber` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '光纤条件',
  `module` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模块条件',
  `cable` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线缆条件',
  `ground` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接地条件',
  `construction_resource` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '施工资源条件',
  `conclusion` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '工勘结论（富文本）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已确认 2已驳回 3已归档',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `form_revision_id` bigint DEFAULT NULL,
  `form_revision_version` int DEFAULT NULL,
  `form_extra_values` json DEFAULT NULL,
  `outsource_required` bit(1) NOT NULL DEFAULT b'0' COMMENT '整单是否需要转包',
  `outsource_request_id` bigint DEFAULT NULL COMMENT '关联转包申请ID，不代表审批完成',
  `confirmed_at` datetime(3) DEFAULT NULL COMMENT '正式确认时间；历史未知不回填',
  `archived_at` datetime(3) DEFAULT NULL COMMENT '正式归档时间；历史未知不回填',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_site_survey_code` (`project_id`,`code`),
  KEY `idx_pms_eng_site_survey_project` (`project_id`),
  CONSTRAINT `chk_pms_eng_site_survey_location_resolution` CHECK ((`location_resolution_status` in (_utf8mb4'UNRESOLVED',_utf8mb4'RESOLVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='现场工勘主表';

CREATE TABLE `sol_eng_solution` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案名称',
  `solution_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'IMPLEMENTATION' COMMENT '方案类型',
  `template_id` bigint DEFAULT NULL COMMENT '关联文档模板ID',
  `template_version_id` bigint DEFAULT NULL COMMENT '关联模板版本ID',
  `template_snapshot` json DEFAULT NULL COMMENT '模板快照JSON',
  `section_data` json DEFAULT NULL COMMENT '章节填写数据JSON',
  `background` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '背景',
  `target` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '目标',
  `team` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '团队',
  `inventory` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '清单',
  `plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '计划',
  `topology` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '拓扑',
  `interface_plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '接口',
  `ip_plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'IP',
  `version_label` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本标签',
  `script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '脚本',
  `quality` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '质量',
  `risk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '风险',
  `o_and_m` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '运维',
  `review_level` tinyint NOT NULL DEFAULT '0' COMMENT '审核级别 0 普通 1 重大',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2审批中 3已通过 4已驳回 5已撤回 6已终止',
  `approved_by` bigint DEFAULT NULL COMMENT '审核人',
  `approved_time` datetime DEFAULT NULL COMMENT '审核时间',
  `approval_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核意见',
  `baseline_version` int DEFAULT NULL COMMENT '基线版本号（审核通过后冻结）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_solution_code` (`project_id`,`code`),
  KEY `idx_pms_eng_solution_project` (`project_id`),
  KEY `idx_pms_eng_solution_status` (`project_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实施方案';

CREATE TABLE `sol_eng_solution_source` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `solution_id` bigint NOT NULL COMMENT '方案编号',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SURVEY 工勘 / REQUIREMENT 需求',
  `source_id` bigint NOT NULL COMMENT '来源业务编号',
  `source_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源业务编码',
  `source_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '带入时的来源快照（JSON）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_solution_source` (`solution_id`,`source_type`,`source_id`),
  KEY `idx_pms_eng_solution_source_solution` (`solution_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='方案来源追溯';

CREATE TABLE `sol_engineering_briefing_retired` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键；承接对象保留原主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户内唯一交底书编号',
  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交底书名称',
  `briefing_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STANDARD',
  `template_id` bigint DEFAULT NULL,
  `template_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '固定模板快照JSON',
  `source_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '前序基线数据快照JSON',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '交底内容富文本',
  `file_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_size` bigint DEFAULT NULL,
  `file_checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿/1已生成/2已审核/3已发布/4已作废',
  `version` int NOT NULL DEFAULT '0',
  `generate_time` datetime DEFAULT NULL,
  `publish_time` datetime DEFAULT NULL,
  `approver_user_id` bigint DEFAULT NULL,
  `approve_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approve_time` datetime DEFAULT NULL,
  `creator_user_id` bigint DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `legacy_source_id` bigint DEFAULT NULL COMMENT '原交底主键；仅专用承接写入',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_briefing_code` (`code`,`tenant_id`),
  UNIQUE KEY `uk_sol_briefing_source` (`tenant_id`,`legacy_source_id`),
  KEY `idx_sol_briefing_project` (`project_id`),
  KEY `idx_sol_briefing_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='独立工程交底';

CREATE TABLE `sol_preparation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '准备业务版本ID',
  `project_id` bigint NOT NULL COMMENT 'PROJ项目ID',
  `preparation_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '准备类型，V1固定PRE_02_SITE_SURVEY',
  `business_version` int unsigned NOT NULL COMMENT '项目内准备业务版本',
  `current_marker` tinyint DEFAULT NULL COMMENT '当前版本标记：当前=1，历史=NULL',
  `source_preparation_id` bigint DEFAULT NULL COMMENT 'PRE-04修订来源完成版ID',
  `dynamic_form_instance_id` bigint DEFAULT NULL COMMENT 'PLATFORM动态表单实例逻辑ID',
  `draft_marker` tinyint DEFAULT NULL COMMENT 'PRE-04当前草稿标记：当前=1，其余=NULL',
  `effective_marker` tinyint DEFAULT NULL COMMENT 'PRE-04当前有效完成版标记：当前=1，其余=NULL',
  `template_id` bigint NOT NULL COMMENT '冻结项目模板ID',
  `template_revision_id` bigint NOT NULL COMMENT '冻结项目模板修订ID',
  `template_snapshot` json NOT NULL COMMENT '冻结PRE-02模板及WorkBinding事实',
  `fixed_form_catalog_version` int unsigned NOT NULL COMMENT '固定表单目录版本',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '准备生命周期状态',
  `readiness_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前实施就绪状态',
  `latest_readiness_snapshot_id` bigint DEFAULT NULL COMMENT '最新不可变就绪快照ID',
  `input_version` int unsigned NOT NULL DEFAULT '0' COMMENT '就绪输入版本',
  `readiness_version` int unsigned NOT NULL DEFAULT '0' COMMENT '就绪事实版本',
  `snapshot_current` bit(1) NOT NULL DEFAULT b'0' COMMENT '最新快照是否仍对应当前输入',
  `content_version` int unsigned DEFAULT NULL COMMENT 'PRE-04正文与附件事实版本',
  `completed_by` bigint DEFAULT NULL COMMENT 'PRE-04完成人',
  `completed_at` datetime(3) DEFAULT NULL COMMENT 'PRE-04完成时间',
  `submitted_at` datetime(3) DEFAULT NULL COMMENT '提交确认时间',
  `confirmed_at` datetime(3) DEFAULT NULL COMMENT '全部确认时间',
  `returned_at` datetime(3) DEFAULT NULL COMMENT '退回时间',
  `return_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退回原因',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `entity_value_json` json DEFAULT NULL COMMENT 'PRE-04 entity-owned ordinary values',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_preparation_business_version` (`tenant_id`,`project_id`,`preparation_type_code`,`business_version`),
  UNIQUE KEY `uk_sol_preparation_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_sol_preparation_current` (`tenant_id`,`project_id`,`preparation_type_code`,`current_marker`),
  UNIQUE KEY `uk_sol_preparation_draft` (`tenant_id`,`project_id`,`preparation_type_code`,`draft_marker`),
  UNIQUE KEY `uk_sol_preparation_effective` (`tenant_id`,`project_id`,`preparation_type_code`,`effective_marker`),
  UNIQUE KEY `uk_sol_preparation_dynamic_form_instance` (`tenant_id`,`dynamic_form_instance_id`),
  KEY `idx_sol_preparation_project_status` (`tenant_id`,`project_id`,`status_code`,`business_version`),
  KEY `fk_sol_preparation_latest_snapshot` (`tenant_id`,`latest_readiness_snapshot_id`),
  KEY `idx_sol_preparation_source` (`tenant_id`,`source_preparation_id`),
  CONSTRAINT `fk_sol_preparation_latest_snapshot` FOREIGN KEY (`tenant_id`, `latest_readiness_snapshot_id`) REFERENCES `sol_preparation_readiness_snapshot` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_preparation_source` FOREIGN KEY (`tenant_id`, `source_preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_preparation_business_version` CHECK (((`business_version` > 0) and (`fixed_form_catalog_version` > 0))),
  CONSTRAINT `chk_sol_preparation_current_marker` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `chk_sol_preparation_pre04_marker_values` CHECK ((((`draft_marker` is null) or (`draft_marker` = 1)) and ((`effective_marker` is null) or (`effective_marker` = 1)))),
  CONSTRAINT `chk_sol_preparation_pre04_markers` CHECK ((((`preparation_type_code` = _utf8mb4'PRE_02_SITE_SURVEY') and (`dynamic_form_instance_id` is null) and (`draft_marker` is null) and (`effective_marker` is null) and (`source_preparation_id` is null) and (`content_version` is null) and (`completed_by` is null) and (`completed_at` is null)) or ((`preparation_type_code` = _utf8mb4'PRE_04_REQUIREMENT_ANALYSIS') and (`dynamic_form_instance_id` is not null) and (`current_marker` is null) and (`content_version` is not null) and (((`status_code` = _utf8mb4'DRAFT') and (`draft_marker` = 1) and (`effective_marker` is null) and (`completed_by` is null) and (`completed_at` is null)) or ((`status_code` = _utf8mb4'COMPLETED') and (`draft_marker` is null) and ((`effective_marker` is null) or (`effective_marker` = 1)) and (`completed_by` is not null) and (`completed_at` is not null)))))),
  CONSTRAINT `chk_sol_preparation_readiness_status` CHECK ((`readiness_status_code` in (_utf8mb4'NOT_READY',_utf8mb4'READY'))),
  CONSTRAINT `chk_sol_preparation_status` CHECK ((((`preparation_type_code` = _utf8mb4'PRE_02_SITE_SURVEY') and (`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PENDING_CONFIRMATION',_utf8mb4'CONFIRMED',_utf8mb4'RETURNED'))) or ((`preparation_type_code` = _utf8mb4'PRE_04_REQUIREMENT_ANALYSIS') and (`status_code` in (_utf8mb4'DRAFT',_utf8mb4'COMPLETED'))))),
  CONSTRAINT `chk_sol_preparation_type` CHECK ((`preparation_type_code` in (_utf8mb4'PRE_02_SITE_SURVEY',_utf8mb4'PRE_04_REQUIREMENT_ANALYSIS')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02准备聚合与当前就绪指针';

CREATE TABLE `sol_preparation_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工勘项ID',
  `preparation_id` bigint NOT NULL COMMENT '准备业务版本ID',
  `source_item_id` bigint DEFAULT NULL COMMENT '退回新版本的来源工勘项ID',
  `item_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结工勘项编码',
  `item_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结工勘项名称',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '冻结排序',
  `applicability_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用性状态',
  `confirmation_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '逐项确认状态',
  `form_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '固定表单编码',
  `form_version` int unsigned NOT NULL COMMENT '固定表单版本',
  `form_schema_snapshot` json NOT NULL COMMENT '固定表单Schema快照',
  `evidence_policy_snapshot` json NOT NULL COMMENT '证据策略快照',
  `source_policy_snapshot` json NOT NULL COMMENT '来源策略快照',
  `waiver_policy_snapshot` json NOT NULL COMMENT '豁免策略快照',
  `outsourced` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否外包',
  `assignee_user_id` bigint DEFAULT NULL COMMENT '当前负责人用户ID',
  `assignee_effective_from` datetime(3) DEFAULT NULL COMMENT '负责人开始生效时间',
  `site_result_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现场结论编码',
  `site_result_detail` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现场结论说明',
  `evidence_reference_snapshot` json DEFAULT NULL COMMENT '精确FileArtifact引用数组',
  `not_applicable_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '不适用原因',
  `not_applicable_confirmed_by` bigint DEFAULT NULL COMMENT '不适用确认人',
  `not_applicable_confirmed_at` datetime(3) DEFAULT NULL COMMENT '不适用确认时间',
  `confirmed_by` bigint DEFAULT NULL COMMENT '逐项确认人',
  `confirmed_at` datetime(3) DEFAULT NULL COMMENT '逐项确认时间',
  `returned_by` bigint DEFAULT NULL COMMENT '逐项退回人',
  `returned_at` datetime(3) DEFAULT NULL COMMENT '逐项退回时间',
  `return_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '逐项退回原因',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_preparation_item_code` (`tenant_id`,`preparation_id`,`item_code`),
  UNIQUE KEY `uk_sol_preparation_item_tenant_row` (`tenant_id`,`id`),
  KEY `idx_sol_preparation_item_order` (`tenant_id`,`preparation_id`,`sort_order`,`item_code`,`id`),
  KEY `idx_sol_preparation_item_assignee` (`tenant_id`,`assignee_user_id`,`confirmation_status_code`,`id`),
  KEY `fk_sol_preparation_item_source` (`tenant_id`,`source_item_id`),
  CONSTRAINT `fk_sol_preparation_item_preparation` FOREIGN KEY (`tenant_id`, `preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_preparation_item_source` FOREIGN KEY (`tenant_id`, `source_item_id`) REFERENCES `sol_preparation_item` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_preparation_item_applicability` CHECK ((`applicability_code` in (_utf8mb4'REQUIRED',_utf8mb4'NOT_APPLICABLE_PENDING',_utf8mb4'NOT_APPLICABLE_CONFIRMED'))),
  CONSTRAINT `chk_sol_preparation_item_confirmation` CHECK ((`confirmation_status_code` in (_utf8mb4'PENDING',_utf8mb4'CONFIRMED',_utf8mb4'RETURNED'))),
  CONSTRAINT `chk_sol_preparation_item_form_version` CHECK ((`form_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02冻结工勘项与逐项结果';

CREATE TABLE `sol_preparation_item_waiver` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '逐项豁免ID',
  `project_id` bigint NOT NULL COMMENT 'PROJ项目ID',
  `preparation_id` bigint NOT NULL COMMENT '准备业务版本ID',
  `item_id` bigint NOT NULL COMMENT '工勘项ID',
  `item_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结工勘项编码',
  `waiver_no` int unsigned NOT NULL COMMENT '项目工勘项内豁免序号',
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '豁免审批状态',
  `blocker_codes_snapshot` json NOT NULL COMMENT '允许替代的阻断码快照',
  `reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '豁免原因',
  `risk` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险说明',
  `compensation` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '补偿措施',
  `valid_from` datetime(3) NOT NULL COMMENT '生效时间',
  `valid_until` datetime(3) NOT NULL COMMENT '失效时间',
  `approval_role_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结审批角色',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人',
  `submitted_at` datetime(3) DEFAULT NULL COMMENT '提交时间',
  `decided_by` bigint DEFAULT NULL COMMENT '决策人',
  `decided_at` datetime(3) DEFAULT NULL COMMENT '决策时间',
  `decision_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '决策意见',
  `withdrawn_at` datetime(3) DEFAULT NULL COMMENT '撤回时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_preparation_item_waiver` (`tenant_id`,`project_id`,`item_code`,`waiver_no`),
  UNIQUE KEY `uk_sol_preparation_waiver_tenant_row` (`tenant_id`,`id`),
  KEY `idx_sol_preparation_waiver_status` (`tenant_id`,`preparation_id`,`item_id`,`status_code`,`valid_until`,`id`),
  KEY `fk_sol_preparation_waiver_item` (`tenant_id`,`item_id`),
  CONSTRAINT `fk_sol_preparation_waiver_item` FOREIGN KEY (`tenant_id`, `item_id`) REFERENCES `sol_preparation_item` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_preparation_waiver_preparation` FOREIGN KEY (`tenant_id`, `preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_preparation_waiver_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PENDING_APPROVAL',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'WITHDRAWN'))),
  CONSTRAINT `chk_sol_preparation_waiver_window` CHECK ((`valid_until` >= `valid_from`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02逐项豁免审批历史';

CREATE TABLE `sol_preparation_readiness_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '就绪快照ID',
  `preparation_id` bigint NOT NULL COMMENT '准备业务版本ID',
  `snapshot_no` int unsigned NOT NULL COMMENT '准备版本内快照序号',
  `result_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估结果',
  `rule_version` int unsigned NOT NULL COMMENT '就绪规则版本',
  `project_scope_version` bigint NOT NULL COMMENT '冻结项目范围版本',
  `input_version` int unsigned NOT NULL COMMENT '冻结输入版本',
  `preparation_version` int unsigned NOT NULL COMMENT '冻结准备乐观锁版本',
  `readiness_version` int unsigned NOT NULL COMMENT '冻结就绪事实版本',
  `item_facts_snapshot` json NOT NULL COMMENT '逐项事实快照',
  `file_facts_snapshot` json NOT NULL COMMENT '文件事实快照',
  `source_facts_snapshot` json NOT NULL COMMENT '来源事实快照',
  `waiver_facts_snapshot` json NOT NULL COMMENT '豁免事实快照',
  `blockers_snapshot` json NOT NULL COMMENT '阻断清单快照',
  `evaluated_by` bigint NOT NULL COMMENT '评估操作者',
  `evaluated_at` datetime(3) NOT NULL COMMENT '评估时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_preparation_readiness_snapshot` (`tenant_id`,`preparation_id`,`snapshot_no`),
  UNIQUE KEY `uk_sol_preparation_snapshot_tenant_row` (`tenant_id`,`id`),
  KEY `idx_sol_preparation_snapshot_result` (`tenant_id`,`preparation_id`,`result_code`,`snapshot_no`,`id`),
  CONSTRAINT `fk_sol_preparation_snapshot_preparation` FOREIGN KEY (`tenant_id`, `preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_preparation_snapshot_no` CHECK (((`snapshot_no` > 0) and (`rule_version` > 0))),
  CONSTRAINT `chk_sol_preparation_snapshot_result` CHECK ((`result_code` in (_utf8mb4'NOT_READY',_utf8mb4'READY')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02不可变实施就绪快照';

CREATE TABLE `sol_preparation_source_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '权威来源引用ID',
  `preparation_id` bigint NOT NULL COMMENT '准备业务版本ID',
  `item_id` bigint NOT NULL COMMENT '工勘项ID',
  `source_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型，例OA',
  `source_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源对象类型',
  `source_object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源对象稳定ID',
  `source_reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源稳定引用键',
  `required_result_policy_snapshot` json NOT NULL COMMENT '来源终态策略快照',
  `normalized_result_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前权威归一结果',
  `source_fact_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前权威事实版本',
  `source_watermark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前权威水位',
  `sync_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步状态',
  `last_success_result_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近成功归一结果',
  `last_success_fact_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近成功事实版本',
  `last_success_watermark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近成功水位',
  `last_success_at` datetime(3) DEFAULT NULL COMMENT '最近成功时间',
  `last_synced_at` datetime(3) DEFAULT NULL COMMENT '最近同步尝试时间',
  `last_sync_error_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近同步错误码',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_preparation_source_reference` (`tenant_id`,`item_id`,`source_type_code`,`source_reference_key`),
  UNIQUE KEY `uk_sol_preparation_source_tenant_row` (`tenant_id`,`id`),
  KEY `idx_sol_preparation_source_status` (`tenant_id`,`preparation_id`,`sync_status_code`,`id`),
  CONSTRAINT `fk_sol_preparation_source_item` FOREIGN KEY (`tenant_id`, `item_id`) REFERENCES `sol_preparation_item` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_preparation_source_preparation` FOREIGN KEY (`tenant_id`, `preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_preparation_source_current_fact` CHECK (((`sync_status_code` <> _utf8mb4'SYNCED') or ((`normalized_result_code` is not null) and (`source_fact_version` is not null) and (`source_watermark` is not null)))),
  CONSTRAINT `chk_sol_preparation_source_status` CHECK ((`sync_status_code` in (_utf8mb4'SYNCED',_utf8mb4'ERROR',_utf8mb4'UNKNOWN')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02权威来源引用与同步事实';

CREATE TABLE `sol_requirement_analysis` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_background` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `project_objective` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `network_topology` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `transmission_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `traffic_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `business_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_planning` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `redundancy_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `security_protection` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `operations_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `logging_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `transmission_current_options` json DEFAULT NULL,
  `traffic_new_connections` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `traffic_concurrency` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `traffic_throughput` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `business_device_details` json DEFAULT NULL,
  `ip_management_resources` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_public_resources` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `operations_management_options` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ra_current_project` (`tenant_id`,`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sol_requirement_analysis_revision` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `entity_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `source_revision_id` bigint DEFAULT NULL,
  `base_effective_revision_id` bigint DEFAULT NULL,
  `base_entity_version` int DEFAULT NULL,
  `revision_state` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `draft_marker` tinyint DEFAULT NULL,
  `effective_marker` tinyint DEFAULT NULL,
  `change_reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `frozen_by` bigint DEFAULT NULL,
  `frozen_at` datetime(3) DEFAULT NULL,
  `project_template_id` bigint DEFAULT NULL,
  `project_template_revision_id` bigint DEFAULT NULL,
  `execution_snapshot` json DEFAULT NULL COMMENT 'Immutable project binding provenance; not form configuration or business content',
  `project_background` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `project_objective` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `network_topology` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `transmission_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `traffic_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `business_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_planning` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `redundancy_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `security_protection` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `operations_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `logging_requirement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `transmission_current_options` json DEFAULT NULL,
  `traffic_new_connections` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `traffic_concurrency` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `traffic_throughput` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `business_device_details` json DEFAULT NULL,
  `ip_management_resources` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_public_resources` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `operations_management_options` json DEFAULT NULL,
  `active_revision_no` int GENERATED ALWAYS AS ((case when (`deleted` = 0x00) then `revision_no` else NULL end)) STORED,
  `active_draft_marker` tinyint GENERATED ALWAYS AS ((case when (`deleted` = 0x00) then `draft_marker` else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ra_revision` (`tenant_id`,`entity_id`,`active_revision_no`),
  UNIQUE KEY `uk_ra_project_revision` (`tenant_id`,`project_id`,`active_revision_no`),
  UNIQUE KEY `uk_ra_draft` (`tenant_id`,`project_id`,`active_draft_marker`),
  UNIQUE KEY `uk_ra_effective` (`tenant_id`,`project_id`,`effective_marker`),
  CONSTRAINT `ck_ra_effective` CHECK (((`effective_marker` is null) or (`effective_marker` = 1))),
  CONSTRAINT `ck_ra_revision_no` CHECK ((`revision_no` > 0)),
  CONSTRAINT `ck_ra_revision_state` CHECK ((((`revision_state` = _utf8mb4'DRAFT') and (`draft_marker` = 1) and (`effective_marker` is null) and (`frozen_at` is null) and (`frozen_by` is null)) or ((`revision_state` = _utf8mb4'FROZEN') and (`draft_marker` is null) and (`frozen_at` is not null) and (`frozen_by` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sol_requirement_analysis_section` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '需求分析冻结章节ID',
  `preparation_id` bigint NOT NULL COMMENT 'PRE-04业务版本ID',
  `source_section_id` bigint DEFAULT NULL COMMENT '修订草稿的来源完成章节ID',
  `section_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结章节编码',
  `section_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结章节名称',
  `section_kind_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CORE或EXTENSION',
  `field_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结字段类型',
  `required_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否必填',
  `dictionary_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冻结选择字典类型',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '冻结排序',
  `schema_snapshot` json NOT NULL COMMENT '字段Schema与选项快照',
  `value_snapshot` json NOT NULL COMMENT '规范化字段值快照',
  `attachment_reference_snapshot` json NOT NULL COMMENT '精确FileArtifact引用数组',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '章节乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_requirement_section_code` (`tenant_id`,`preparation_id`,`section_code`),
  UNIQUE KEY `uk_sol_requirement_section_tenant_row` (`tenant_id`,`id`),
  KEY `idx_sol_requirement_section_order` (`tenant_id`,`preparation_id`,`sort_order`,`section_code`,`id`),
  KEY `idx_sol_requirement_section_source` (`tenant_id`,`source_section_id`),
  CONSTRAINT `fk_sol_requirement_section_preparation` FOREIGN KEY (`tenant_id`, `preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_requirement_section_source` FOREIGN KEY (`tenant_id`, `source_section_id`) REFERENCES `sol_requirement_analysis_section` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_requirement_section_dictionary` CHECK ((((`field_type_code` in (_utf8mb4'SINGLE_SELECT',_utf8mb4'MULTI_SELECT')) and (`dictionary_type` is not null)) or ((`field_type_code` not in (_utf8mb4'SINGLE_SELECT',_utf8mb4'MULTI_SELECT')) and (`dictionary_type` is null)))),
  CONSTRAINT `chk_sol_requirement_section_field_type` CHECK ((`field_type_code` in (_utf8mb4'RICH_TEXT',_utf8mb4'TEXT',_utf8mb4'NUMBER',_utf8mb4'BOOLEAN',_utf8mb4'SINGLE_SELECT',_utf8mb4'MULTI_SELECT'))),
  CONSTRAINT `chk_sol_requirement_section_kind` CHECK ((`section_kind_code` in (_utf8mb4'CORE',_utf8mb4'EXTENSION')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-04冻结章节、正文与精确附件事实';

CREATE TABLE `sol_schedule_backward` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `target_date` date NOT NULL COMMENT '目标完工日期',
  `project_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DIRECT' COMMENT '项目类型 DIRECT 直签 / INDIRECT 非直签',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已计算 2已应用 3已驳回',
  `conflict_summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冲突汇总',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_schedule_backward_project` (`project_id`),
  KEY `idx_pms_schedule_backward_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 工期倒排记录';

CREATE TABLE `sol_schedule_backward_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `backward_id` bigint NOT NULL COMMENT '倒排记录编号',
  `phase_id` bigint DEFAULT NULL COMMENT '项目阶段编号',
  `phase_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '阶段名称',
  `planned_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `planned_end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `recommended_latest_date` date DEFAULT NULL COMMENT '建议最晚日期',
  `has_conflict` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否存在冲突',
  `conflict_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冲突原因',
  `sort` int NOT NULL DEFAULT '0' COMMENT '阶段排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_schedule_backward_item_backward` (`backward_id`),
  KEY `idx_pms_schedule_backward_item_phase` (`phase_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 工期倒排阶段明细';

CREATE TABLE `sol_site_survey` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `survey_date` date DEFAULT NULL,
  `surveyor_user_id` bigint DEFAULT NULL,
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_id` bigint DEFAULT NULL,
  `address_version` int unsigned DEFAULT NULL,
  `site_id` bigint DEFAULT NULL,
  `site_version` int unsigned DEFAULT NULL,
  `site_location_id` bigint DEFAULT NULL,
  `site_location_version` int unsigned DEFAULT NULL,
  `location_resolution_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED',
  `address_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `location_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `power_supply` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cabinet` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `network_port` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fiber` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `module` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cable` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ground` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `construction_resource` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conclusion` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cabinet_ready` bit(1) DEFAULT NULL,
  `cable_ready` bit(1) DEFAULT NULL,
  `module_ready` bit(1) DEFAULT NULL,
  `original_module` bit(1) DEFAULT NULL,
  `manufacturer_installation` bit(1) DEFAULT NULL,
  `rail_tray_required` bit(1) DEFAULT NULL,
  `material_matches` bit(1) DEFAULT NULL,
  `required_end_date` date DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '0',
  `confirmed_at` datetime(3) DEFAULT NULL,
  `archived_at` datetime(3) DEFAULT NULL,
  `outsource_required` bit(1) NOT NULL DEFAULT b'0',
  `outsource_request_id` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_survey_code` (`tenant_id`,`project_id`,`code`),
  CONSTRAINT `chk_sol_survey_location` CHECK ((`location_resolution_status` in (_utf8mb4'UNRESOLVED',_utf8mb4'RESOLVED'))),
  CONSTRAINT `chk_sol_survey_status` CHECK ((`status` in (0,1,2,3)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sol_site_survey_condition` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `survey_id` bigint NOT NULL,
  `condition_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `condition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_survey_condition_order` (`tenant_id`,`survey_id`,`condition_type`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sol_site_survey_material` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `survey_id` bigint NOT NULL,
  `device_id` bigint DEFAULT NULL,
  `project_id` bigint NOT NULL,
  `sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_model` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `sort_order` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_survey_material` (`tenant_id`,`survey_id`,`sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sol_solution_review` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `solution_id` bigint NOT NULL,
  `source_version` int NOT NULL,
  `request_version` int NOT NULL,
  `process_definition_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `candidates_json` json NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reviews_json` json DEFAULT NULL,
  `submitted_by` bigint NOT NULL,
  `submitted_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  `approved_version` int DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_review_solution` (`tenant_id`,`solution_id`),
  UNIQUE KEY `uk_sol_review_instance` (`tenant_id`,`process_instance_id`),
  CONSTRAINT `ck_sol_review_status` CHECK ((`status` in (_utf8mb4'RUNNING',_utf8mb4'APPROVE',_utf8mb4'REJECT',_utf8mb4'CANCEL')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实施方案分级审批版本关联';

CREATE TABLE `sol_solution_review_policy` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `solution_id` bigint NOT NULL,
  `source_version` int NOT NULL,
  `review_level` int NOT NULL,
  `evidence_json` json NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_review_policy` (`tenant_id`,`solution_id`),
  CONSTRAINT `ck_sol_review_policy_level` CHECK ((`review_level` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='方案提交时的审核规则判定快照';

CREATE TABLE `sol_stage_plan_batch` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段施工计划批次ID',
  `project_id` bigint NOT NULL COMMENT 'PROJ项目ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1审批中 2已生效 3已驳回',
  `duration_revision_id` bigint DEFAULT NULL COMMENT '推算基准工期版本ID（空=按阶段建议时间）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `bpm_process_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批流程定义Key',
  `bpm_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批流程实例ID',
  `submitted_at` datetime(3) DEFAULT NULL COMMENT '提交时间',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `effective_at` datetime(3) DEFAULT NULL COMMENT '审批生效时间',
  `effective_by` bigint DEFAULT NULL COMMENT '生效执行人（BPM回调）',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `calculated_start` date DEFAULT NULL COMMENT '本版本计算开始日期',
  `calculated_end` date DEFAULT NULL COMMENT '本版本计算结束日期',
  `task_plans_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '本版本阶段内任务计划快照',
  `input_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '冻结计划及回款节点计划验收时间输入快照',
  PRIMARY KEY (`id`),
  KEY `idx_sol_stage_plan_batch_project` (`project_id`),
  KEY `idx_sol_stage_plan_batch_status` (`project_id`,`status`),
  KEY `idx_sol_stage_plan_batch_bpm` (`bpm_process_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段施工计划批次（PLN-01/04）';

CREATE TABLE `sol_stage_plan_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段计划明细ID',
  `batch_id` bigint NOT NULL COMMENT '批次ID',
  `phase_id` bigint NOT NULL COMMENT '项目阶段ID（pms_project_phase）',
  `phase_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '阶段编码快照',
  `phase_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阶段名称快照',
  `sort` int NOT NULL DEFAULT '0' COMMENT '阶段顺序',
  `suggested_start` date DEFAULT NULL COMMENT '建议开始时间快照',
  `suggested_end` date DEFAULT NULL COMMENT '建议结束时间快照',
  `plan_start` date DEFAULT NULL COMMENT '计划开始时间（草稿可空，提交时必填）',
  `plan_end` date DEFAULT NULL COMMENT '计划结束时间（草稿可空，提交时必填）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_sol_stage_plan_item_batch` (`batch_id`),
  KEY `idx_sol_stage_plan_item_phase` (`phase_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段施工计划明细';

CREATE TABLE `srv_inspection_annotation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `report_id` bigint NOT NULL,
  `result_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `kind` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `change_reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsible_user_id` bigint DEFAULT NULL,
  `due_at` datetime(3) DEFAULT NULL,
  `annotated_by` bigint NOT NULL,
  `annotated_at` datetime(3) NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_annotation_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_inspection_annotation` (`tenant_id`,`report_id`,`result_id`,`revision_no`),
  UNIQUE KEY `uk_ins_annotation_task` (`tenant_id`,`task_id`,`id`),
  UNIQUE KEY `uk_ins_annotation_result` (`tenant_id`,`task_id`,`report_id`,`result_id`,`id`),
  CONSTRAINT `fk_ins_annotation_input` FOREIGN KEY (`tenant_id`, `task_id`, `report_id`, `result_id`) REFERENCES `srv_inspection_report_result` (`tenant_id`, `task_id`, `report_id`, `result_id`),
  CONSTRAINT `ck_ins_annotation_revision` CHECK ((`revision_no` > 0)),
  CONSTRAINT `ck_ins_annotation_track` CHECK (((`kind` <> _utf8mb4'TRACK') or ((`responsible_user_id` is not null) and (`due_at` is not null)))),
  CONSTRAINT `ck_inspection_annotation_kind` CHECK ((`kind` in (_utf8mb4'FALSE_POSITIVE',_utf8mb4'IGNORE',_utf8mb4'TRACK')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_inspection_attempt` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `attempt_no` int NOT NULL,
  `mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `started_by` bigint NOT NULL,
  `started_at` datetime(3) NOT NULL,
  `finished_at` datetime(3) DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `provider_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLATFORM' COMMENT 'Frozen judgement provider',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_attempt_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_inspection_attempt` (`tenant_id`,`task_id`,`attempt_no`),
  UNIQUE KEY `uk_ins_attempt_task` (`tenant_id`,`task_id`,`id`),
  CONSTRAINT `fk_ins_attempt_task` FOREIGN KEY (`tenant_id`, `task_id`) REFERENCES `srv_inspection_task` (`tenant_id`, `id`),
  CONSTRAINT `ck_ins_attempt_provider` CHECK ((`provider_code` in (_utf8mb4'PLATFORM',_utf8mb4'UMC'))),
  CONSTRAINT `ck_ins_attempt_status` CHECK ((`status_code` in (_utf8mb4'ACTIVE',_utf8mb4'COMPLETED',_utf8mb4'SUPERSEDED',_utf8mb4'CANCELLED',_utf8mb4'FAILED'))),
  CONSTRAINT `ck_inspection_attempt_mode` CHECK ((`mode` in (_utf8mb4'ONLINE',_utf8mb4'OFFLINE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_inspection_collection_receipt` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `execution_id` bigint NOT NULL,
  `collection_execution_id` bigint NOT NULL,
  `collection_task_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `result_version` bigint NOT NULL,
  `file_version_id` bigint NOT NULL,
  `external_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `failure_category` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actor_id` bigint NOT NULL,
  `received_at` datetime(3) NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inspection_receipt_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_inspection_collection_receipt` (`tenant_id`,`execution_id`,`result_version`),
  KEY `idx_inspection_receipt_task` (`tenant_id`,`task_id`,`id`),
  KEY `fk_ins_receipt_execution` (`tenant_id`,`task_id`,`execution_id`),
  CONSTRAINT `fk_ins_receipt_execution` FOREIGN KEY (`tenant_id`, `task_id`, `execution_id`) REFERENCES `srv_inspection_execution` (`tenant_id`, `task_id`, `id`),
  CONSTRAINT `ck_inspection_receipt_version` CHECK ((`result_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_inspection_detection_result` (
  `id` bigint NOT NULL AUTO_INCREMENT,
