  `current_only` bit(1) NOT NULL DEFAULT b'0',
  `include_details` bit(1) NOT NULL DEFAULT b'0',
  `result_count` int NOT NULL,
  `artifact_id` bigint DEFAULT NULL,
  `file_version_no` int DEFAULT NULL,
  `reference_key` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failure_message` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `generated_at` datetime(3) DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inspection_export_tenant` (`tenant_id`,`id`),
  KEY `idx_inspection_export_actor` (`tenant_id`,`exported_by`,`id`),
  CONSTRAINT `ck_ins_export_file` CHECK (((`status_code` <> _utf8mb4'AVAILABLE') or ((`artifact_id` is not null) and (`file_version_no` is not null) and (`file_version_no` > 0) and (`reference_key` is not null) and (`reference_key` <> _utf8mb4'') and (`file_name` is not null) and (`sha256` is not null) and (char_length(`sha256`) = 64)))),
  CONSTRAINT `ck_ins_export_result_count` CHECK ((`result_count` >= 0)),
  CONSTRAINT `ck_inspection_export_available` CHECK (((`status_code` <> _utf8mb4'AVAILABLE') or ((`artifact_id` is not null) and (`file_version_no` > 0) and (`reference_key` is not null) and (`sha256` is not null) and (`generated_at` is not null)))),
  CONSTRAINT `ck_inspection_export_format` CHECK ((`format_code` in (_utf8mb4'XLSX',_utf8mb4'CSV'))),
  CONSTRAINT `ck_inspection_export_status` CHECK ((`status_code` in (_utf8mb4'REQUESTED',_utf8mb4'GENERATING',_utf8mb4'AVAILABLE',_utf8mb4'FAILED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

