  CONSTRAINT `ck_ins_report_revision` CHECK (((`revision_no` > 0) and (char_length(`input_digest`) = 64))),
  CONSTRAINT `ck_ins_report_source` CHECK ((`source_code` in (_utf8mb4'PLATFORM',_utf8mb4'MANUAL',_utf8mb4'UMC'))),
  CONSTRAINT `ck_ins_report_status` CHECK ((`status_code` in (_utf8mb4'GENERATING',_utf8mb4'AVAILABLE',_utf8mb4'FAILED')))
