  `revision_no` int unsigned NOT NULL,
  `status_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `rule_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `inspection_item` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity_name_snapshot` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int DEFAULT NULL,
  `expected_result_regex` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `threshold_data_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `threshold_operator` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `threshold_value` decimal(20,6) DEFAULT NULL,
  `threshold_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `published_by` bigint DEFAULT NULL,
  `published_at` datetime(3) DEFAULT NULL,
  `disabled_by` bigint DEFAULT NULL,
  `disabled_at` datetime(3) DEFAULT NULL,
  `current_published_marker` tinyint GENERATED ALWAYS AS ((case when (`status_code` = _utf8mb4'PUBLISHED') then 1 else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_revision_rule_no` (`tenant_id`,`rule_id`,`revision_no`),
  UNIQUE KEY `uk_srv_inspection_revision_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_srv_inspection_revision_current` (`tenant_id`,`rule_id`,`current_published_marker`),
  KEY `idx_srv_inspection_revision_filter` (`tenant_id`,`status_code`,`category_code`,`severity_code`,`sort_order`,`id`),
  KEY `fk_srv_inspection_revision_rule` (`tenant_id`,`rule_id`,`rule_name_snapshot`),
  CONSTRAINT `fk_srv_inspection_revision_rule` FOREIGN KEY (`tenant_id`, `rule_id`, `rule_name_snapshot`) REFERENCES `srv_inspection_rule` (`tenant_id`, `id`, `rule_name`),
  CONSTRAINT `chk_srv_inspection_revision_category` CHECK (((`category_code` is null) or (`category_code` in (_utf8mb4'BASIC',_utf8mb4'OPERATING_STATUS',_utf8mb4'LOG',_utf8mb4'BUSINESS_STATUS',_utf8mb4'REDUNDANCY',_utf8mb4'ROUTING',_utf8mb4'SECURITY',_utf8mb4'FORWARDING_CHANNEL',_utf8mb4'LOAD_BALANCING',_utf8mb4'TRAFFIC_CLEANING')))),
  CONSTRAINT `chk_srv_inspection_revision_no` CHECK ((`revision_no` > 0)),
  CONSTRAINT `chk_srv_inspection_revision_publish_complete` CHECK (((`status_code` = _utf8mb4'DRAFT') or ((`rule_name_snapshot` is not null) and (`rule_name_snapshot` <> _utf8mb4'') and (`inspection_item` is not null) and (`inspection_item` <> _utf8mb4'') and (`description` is not null) and (`description` <> _utf8mb4'') and (`category_code` is not null) and (`category_name_snapshot` is not null) and (`category_name_snapshot` <> _utf8mb4'') and (`severity_code` is not null) and (`severity_name_snapshot` is not null) and (`severity_name_snapshot` <> _utf8mb4'') and (`sort_order` is not null) and (`expected_result_regex` is not null) and (`expected_result_regex` <> _utf8mb4'') and (`threshold_data_type` = _utf8mb4'NUMBER') and (`threshold_operator` is not null) and (`threshold_value` is not null) and (`threshold_unit` is not null) and (`threshold_unit` <> _utf8mb4'')))),
  CONSTRAINT `chk_srv_inspection_revision_severity` CHECK (((`severity_code` is null) or (`severity_code` in (_utf8mb4'GENERAL',_utf8mb4'SEVERE',_utf8mb4'FATAL')))),
  CONSTRAINT `chk_srv_inspection_revision_state_facts` CHECK ((((`status_code` = _utf8mb4'DRAFT') and (`published_by` is null) and (`published_at` is null) and (`disabled_by` is null) and (`disabled_at` is null)) or ((`status_code` = _utf8mb4'PUBLISHED') and (`published_by` is not null) and (`published_at` is not null) and (`disabled_by` is null) and (`disabled_at` is null)) or ((`status_code` = _utf8mb4'DISABLED') and (`published_by` is not null) and (`published_at` is not null) and (`disabled_by` is not null) and (`disabled_at` is not null)))),
  CONSTRAINT `chk_srv_inspection_revision_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PUBLISHED',_utf8mb4'DISABLED'))),
  CONSTRAINT `chk_srv_inspection_revision_threshold_operator` CHECK (((`threshold_operator` is null) or (`threshold_operator` in (_utf8mb4'>',_utf8mb4'<',_utf8mb4'≥',_utf8mb4'≤',_utf8mb4'=',_utf8mb4'≠')))),
  CONSTRAINT `chk_srv_inspection_revision_threshold_type` CHECK (((`threshold_data_type` is null) or (`threshold_data_type` = _utf8mb4'NUMBER')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

