  `background` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `planned_at` datetime(3) DEFAULT NULL,
  `mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `current_attempt_id` bigint DEFAULT NULL,
  `current_report_id` bigint DEFAULT NULL,
  `archive_requested_by` bigint DEFAULT NULL,
  `archive_requested_at` datetime(3) DEFAULT NULL,
  `archived_by` bigint DEFAULT NULL,
  `archived_at` datetime(3) DEFAULT NULL,
  `customer_archive_id` bigint DEFAULT NULL,
  `cancellation_reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_task_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_inspection_task_code` (`tenant_id`,`task_code`),
  KEY `idx_inspection_task_project` (`tenant_id`,`project_id`,`status_code`),
  KEY `idx_inspection_task_owner` (`tenant_id`,`owner_user_id`,`status_code`),
  KEY `fk_ins_task_attempt` (`tenant_id`,`id`,`current_attempt_id`),
  KEY `fk_ins_task_report` (`tenant_id`,`id`,`current_report_id`),
  CONSTRAINT `fk_ins_task_attempt` FOREIGN KEY (`tenant_id`, `id`, `current_attempt_id`) REFERENCES `srv_inspection_attempt` (`tenant_id`, `task_id`, `id`),
  CONSTRAINT `fk_ins_task_report` FOREIGN KEY (`tenant_id`, `id`, `current_report_id`) REFERENCES `srv_inspection_report_revision` (`tenant_id`, `task_id`, `id`),
  CONSTRAINT `ck_ins_task_archive` CHECK (((`status_code` <> _utf8mb4'ARCHIVED') or ((`archive_requested_by` is not null) and (`archive_requested_at` is not null) and (`archived_by` is not null) and (`archived_at` is not null) and (`customer_archive_id` is not null) and (`current_report_id` is not null)))),
  CONSTRAINT `ck_inspection_task_mode` CHECK ((`mode` in (_utf8mb4'ONLINE',_utf8mb4'OFFLINE'))),
  CONSTRAINT `ck_inspection_task_status` CHECK ((`status_code` in (_utf8mb4'PREPARING',_utf8mb4'PRECHECK_PENDING',_utf8mb4'EXECUTING',_utf8mb4'REPORT_PENDING',_utf8mb4'ANNOTATION_PENDING',_utf8mb4'TRACKING',_utf8mb4'CLOSED',_utf8mb4'ARCHIVED',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_inspection_task_device` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `device_id` bigint NOT NULL,
  `serial_number` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_type_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_type_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_model` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_task_device_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_inspection_task_device` (`tenant_id`,`task_id`,`device_id`),
  CONSTRAINT `fk_ins_device_task` FOREIGN KEY (`tenant_id`, `task_id`) REFERENCES `srv_inspection_task` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_inspection_task_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `action_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `actor_id` bigint NOT NULL,
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occurred_at` datetime(3) NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_task_event_tenant` (`tenant_id`,`id`),
  KEY `idx_inspection_task_event` (`tenant_id`,`task_id`,`id`),
  CONSTRAINT `fk_ins_event_task` FOREIGN KEY (`tenant_id`, `task_id`) REFERENCES `srv_inspection_task` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_inspection_task_rule_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `attempt_id` bigint NOT NULL,
  `device_id` bigint NOT NULL,
  `rule_revision_id` bigint NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_task_rule_snapshot_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_inspection_frozen_rule` (`tenant_id`,`attempt_id`,`device_id`,`rule_revision_id`),
  UNIQUE KEY `uk_ins_snapshot_scope` (`tenant_id`,`task_id`,`attempt_id`,`device_id`,`id`,`rule_revision_id`),
  KEY `fk_ins_snapshot_device` (`tenant_id`,`task_id`,`device_id`),
  KEY `fk_ins_snapshot_revision` (`tenant_id`,`rule_revision_id`),
  CONSTRAINT `fk_ins_snapshot_attempt` FOREIGN KEY (`tenant_id`, `task_id`, `attempt_id`) REFERENCES `srv_inspection_attempt` (`tenant_id`, `task_id`, `id`),
  CONSTRAINT `fk_ins_snapshot_device` FOREIGN KEY (`tenant_id`, `task_id`, `device_id`) REFERENCES `srv_inspection_task_device` (`tenant_id`, `task_id`, `device_id`),
  CONSTRAINT `fk_ins_snapshot_revision` FOREIGN KEY (`tenant_id`, `rule_revision_id`) REFERENCES `srv_inspection_rule_revision` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_service_issue` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `report_id` bigint NOT NULL,
  `result_id` bigint NOT NULL,
  `annotation_id` bigint NOT NULL,
  `responsible_user_id` bigint NOT NULL,
  `due_at` datetime(3) NOT NULL,
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `closure_requested_by` bigint DEFAULT NULL,
  `closure_requested_at` datetime(3) DEFAULT NULL,
  `closure_description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `closed_by` bigint DEFAULT NULL,
  `closed_at` datetime(3) DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_service_issue_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_service_issue_result` (`tenant_id`,`report_id`,`result_id`),
  UNIQUE KEY `uk_ins_issue_task` (`tenant_id`,`task_id`,`id`),
  KEY `idx_service_issue_task` (`tenant_id`,`task_id`,`status_code`),
  KEY `fk_ins_issue_annotation` (`tenant_id`,`task_id`,`report_id`,`result_id`,`annotation_id`),
  CONSTRAINT `fk_ins_issue_annotation` FOREIGN KEY (`tenant_id`, `task_id`, `report_id`, `result_id`, `annotation_id`) REFERENCES `srv_inspection_annotation` (`tenant_id`, `task_id`, `report_id`, `result_id`, `id`),
  CONSTRAINT `ck_ins_issue_closed` CHECK (((`status_code` <> _utf8mb4'CLOSED') or ((`closed_by` is not null) and (`closed_at` is not null)))),
  CONSTRAINT `ck_service_issue_status` CHECK ((`status_code` in (_utf8mb4'PENDING',_utf8mb4'PROCESSING',_utf8mb4'CLOSURE_PENDING',_utf8mb4'CLOSED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `srv_service_issue_remediation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `issue_id` bigint NOT NULL,
  `action_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `actor_id` bigint NOT NULL,
  `action_at` datetime(3) NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_service_issue_remediation_tenant` (`tenant_id`,`id`),
  UNIQUE KEY `uk_ins_remediation_task` (`tenant_id`,`task_id`,`id`),
  KEY `idx_service_issue_remediation` (`tenant_id`,`issue_id`,`id`),
  KEY `fk_ins_remediation_issue` (`tenant_id`,`task_id`,`issue_id`),
