INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020187,996610195020086,'DUAL_SILENT_DUAL_R033_2',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','静默双机状态维持时间是否符合预期','双机状态是否符合预期，状态维持时间是否符合预期\n来源：0807设计表，3.2双机部署规范性检查表，第33行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',630,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020188,996610195020086,'DUAL_SILENT_DUAL_R034_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否所有业务接口都配置静默接口（不包含管理口、心跳口、配置同步接口）','1、备机需要将静默接口列表中的接口静默，否则会出现IP地址冲突以及流量继续转发至备机的情况，特别是新扩容的接口，容易出现遗漏的情况。\n2、静默接口中不能配置管理口、心跳口以及配置同步接口，否则会导致备机无法管理、双机状态异常、配置同步异常等情况\n来源：0807设计表，3.2双机部署规范性检查表，第34行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',640,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020189,996610195020086,'DUAL_SILENT_DUAL_R035_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否所有业务接口都配置监听接口（包含聚合接口）','要求所有业务接口都配置监听接口，包含bond口，防止bond口down物理口up情况下双机无法切换而影响业务\n来源：0807设计表，3.2双机部署规范性检查表，第35行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',650,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

