INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020191,996610195020086,'DUAL_SILENT_DUAL_R037_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机管理协议http/https/telnet/ssh开启状态是否一致','配置同步使用的是http/https/telnet/ssh协议，必须保证静默双机两端设备http/https/telnet/ssh配置一致\n来源：0807设计表，3.2双机部署规范性检查表，第37行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',670,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020192,996610195020086,'DUAL_SILENT_DUAL_R038_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','配置同步功能检查','检查主备配置同步禁用开关是否关闭，默认开关关闭，此情况下配置同步才可正常。（功能位于 高可靠性--双机热备--配置同步参数 模块高级配置）\n来源：0807设计表，3.2双机部署规范性检查表，第38行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',680,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020193,996610195020086,'DUAL_SILENT_DUAL_R039_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机会话同步功能是否均开启','主备机会话同步配置必须一致。若会话同步未开启，则主备切换会导致部分长连接业务持续异常，此情况下需让客户手动重新拉起业务。\n来源：0807设计表，3.2双机部署规范性检查表，第39行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',690,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020194,996610195020086,'DUAL_SILENT_DUAL_R040_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否开启双机回切延时（ hotbackup shrp delay time xxx）','主备回切若配置延时，则回切会按照配置的时间延时后再回切，在部分场景下不能配置该功能，例如割接过程中出现问题快速回退，如果配置了该功能，就无法迅速回切来达到恢复业务的目的（可以通过直接修改初始优先级来实现主备迅速回切）备注：神七D035开局版本及之后版本都支持\n来源：0807设计表，3.2双机部署规范性检查表，第40行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',700,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020195,996610195020086,'DUAL_SILENT_DUAL_R041_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置接口延迟up','主要用于框式设备，以防备机在重启过程中因业务板未重启完成的情况接口短暂up影响业务。页面高可靠性--接口延迟配置查看是否有配置，或者命令行show run | in linkup-delay查看是否存在接口延迟up配置，然后再确定是哪些接口有此配置\n来源：0807设计表，3.2双机部署规范性检查表，第41行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',710,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020196,996610195020086,'DUAL_SILENT_DUAL_R042_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置静默双机监听业务板cpu（hotbackup shrp monitor-board slot x priority n）','主要用于框式设备，防止在单业务板场景下，主设备业务板重启，主备状态未切换而影响业务。备注：神七D035开局版本及之后版本都支持\n来源：0807设计表，3.2双机部署规范性检查表，第42行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',720,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020197,996610195020086,'DUAL_SILENT_DUAL_R043_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查是否需要配置Track ip','设备静默双机环境，上下行对接二层交换机或透明部署设备，仅通过接口 UP/DOWN 状态无法判断业务实际连通性，需配置 Track IP。Track ip联动静默双机必须在双机初始优先级一样的场景下使用，优先级不一致会导致Track ip联动切换失效。\nFW 整机纯透明、上下行直连三层设备：链路断裂、对端设备断电、接口Down会直接造成防火墙接口 Down，依靠静默双机接口监控就能正常切主备，无需配置 Track IP。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第43行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',730,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020198,996610195020086,'DUAL_SILENT_DUAL_R044_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查IP是否可以配置为Track ip','探测 IP 需保证主、备两台防火墙路由均可正常可达、网络稳定性高，优先沿着业务转发路径选取。1）首选：对端三层互联的 IP地址；2）备选：其他内网核心网关/固定业务服务器IP。\nTrack IP 禁止选用：1）仅主防火墙可达、备防火墙路由不通的IP；2）频繁离线、在线状态波动较大的终端IP。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第44行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',740,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020199,996610195020086,'DUAL_SILENT_DUAL_R045_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否配置有trackip\n（trackip name xxxx icmp track-address x.x.x.x output-interface  vlan-if20(出接口) next-hop x.x.x.x src-ip x.x.x.x）','用于链路健康检查，对链路状态进行监听。此配置会双机同步，output-interface（出接口）、next-hop（下一条）属于可选参数，可不配置。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第45行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',750,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020200,996610195020086,'DUAL_SILENT_DUAL_R046_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置静默双机监听trackip\n（hotbackup shrp trackip xxxx）','引用链路健康检查，达到在主机接口状态UP，但是网络不通的情况下进行双机切换，快速恢复业务的目的，此配置不能同步，每一台设备都需要手动配置调用Track ip策略。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第46行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',760,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020201,996610195020086,'DUAL_SILENT_DUAL_R047_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查上下游设备是否有配置静态ARP/ND、MAC/IP绑定','如果上下游设备配置静态ARP/ND或MAC/IP绑定功能，主备机切换后会导致业务不通（部分组网中会开启主备机接口的MAC地址同步，同样也需要检查上下游设备静态ARP/ND或MAC/IP绑定是否有绑定接口）\n来源：0807设计表，3.2双机部署规范性检查表，第47行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',770,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020202,996610195020086,'DUAL_SILENT_DUAL_R048_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查上下游设备是否有开启学习免费ARP','部分厂商默认不开启免费ARP学习或者关闭了免费ARP学习功能，会导致备机切为主机后需要等ARP老化后重新学习流量才能通，影响双机的收敛时间\n来源：0807设计表，3.2双机部署规范性检查表，第48行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'SILENT_DUAL','ENABLED',780,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

