INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020205,996610195020086,'DUAL_DRP_DUAL_R058_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口接口计数统计检查','命令：dev_cfg eth sw show all查看，对应心跳物理口如果存在crc丢包、rxdrop丢包或txdrop丢包持续增长。错包多会影响心跳状态及同步配置情况。\n来源：0807设计表，3.2双机部署规范性检查表，第58行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',810,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020206,996610195020086,'DUAL_DRP_DUAL_R059_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口ip是否为私网ip','心跳接口ip一定要配置私网ip（10.0.0.0/8，172.16.0.0/16，192.168.0.0/24，且不允许与现网地址冲突），尽量不要配置公网ip，否则在开启地域访问控制策略场景可能会影响会话及配置同步功能。\n来源：0807设计表，3.2双机部署规范性检查表，第59行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',820,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

