INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020211,996610195020086,'DUAL_DRP_DUAL_R064_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','双机动态路由cost值是否正常','1：查看设备发布出去的ospf路由cost值是否符合设备状态，通过show ip ospf database self-originate 命令查看本设备adv-router,下一步通过命令show ip ospf （进程号）database external adv-router XXX.XXX.XXX.XXX（本设备路由器id值）  查看该adv-router的 metric值来判断是否符合预期。\n2:查看设备发布出去的bgp路由cost值是否符合设备状态，通过show ip bgp ipv4 unicast 查看metric值来判断是否符合预期。\n来源：0807设计表，3.2双机部署规范性检查表，第64行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',870,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020212,996610195020086,'DUAL_DRP_DUAL_R065_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','配置同步功能检查','检查主备配置同步禁用开关是否关闭，默认开关关闭，此情况下配置同步才可正常。（功能位于 高可靠性--普通双机-禁用所有配置同步模块）\n来源：0807设计表，3.2双机部署规范性检查表，第65行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',880,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020213,996610195020086,'DUAL_DRP_DUAL_R066_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否开启drp抢占延迟，drp preempt delay X','drp延迟抢占配置180S，应用场景：当主设备（fw1）重启后，备（fw2）接替了主，在旧主（fw1）重启完成后保证fw1的所有表项准备完成后再接替主的状态，随后再引流量到设备处理。\n来源：0807设计表，3.2双机部署规范性检查表，第66行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',890,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020214,996610195020086,'DUAL_DRP_DUAL_R067_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','interface 接口（tengigeX_X） linkup-delay 180','业务接口延迟UP配置180S，所有业务口都需要配置，保证设备重启时OSPF进程先于DRP进程启动后，OSPF先切为主。\n来源：0807设计表，3.2双机部署规范性检查表，第67行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',900,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020215,996610195020086,'DUAL_DRP_DUAL_R068_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置drp监听业务板drp track board slotX reduced 10','主要用于框式设备，防止在单业务板场景下，主设备业务板重启，主备状态未切换而影响业务。业务板卡要监听所有的。每个业务板推荐值是10，按实际情况调整。假设该设备业务板坏了，导致设备状态切换，此时业务流量将不会走这台设备。\n来源：0807设计表，3.2双机部署规范性检查表，第68行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',910,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020216,996610195020086,'DUAL_DRP_DUAL_R069_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置监听接口drp track interface 接口 reduced 10','用于所有设备，防止在接口出现异常时未及时切换状态，导致影响业务。通常配置：监听上下行所有业务接口。推荐配置每个接口优先级为10,假设一台设备接口down了，导致设备状态切换到备的话，此时业务流量不会走这台设备。\n来源：0807设计表，3.2双机部署规范性检查表，第69行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',920,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020217,996610195020086,'DUAL_DRP_DUAL_R070_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','drp虚拟ip配置一致性','drp虚拟ip配置保持一致。否则会出现主备协商异常的风险。\n来源：0807设计表，3.2双机部署规范性检查表，第70行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',930,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020218,996610195020086,'DUAL_DRP_DUAL_R071_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP监听接口优先级是否符合设计','根据现网设计需求配置主备优先级差异，满足客户主备切换需求。监听接口(板卡)/监听IP/BFD，优先级默认值 10（1-255)。\n来源：0807设计表，3.2双机部署规范性检查表，第71行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'DRP_DUAL','ENABLED',940,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

