INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020226,996610195020086,'DUAL_NORMAL_DUAL_R084_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','配置双机前设备是否清库','1、全新入网设备：组建双机前必须执行清库重启操作，彻底清除设备出厂残留配置，避免因残留配置影响后续业务。\n2、在网设备扩容组建双机：先对现网运行设备完成双机基础配置，并导出完整整机配置文件；将配置文件导入新增备机后，针对性修改备机专属双机参数，再完成双机组网。\n来源：0807设计表，3.2双机部署规范性检查表，第84行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1020,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020227,996610195020086,'DUAL_NORMAL_DUAL_R085_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','心跳口接口配置，三层物理口还是access口','心跳口若是二层口，则禁止使用trunk模式，必须是access模式，对于框式设备禁止使用三层物理口做心跳接口及同步接口\n来源：0807设计表，3.2双机部署规范性检查表，第85行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1030,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

