INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (996610195020233,996610195020086,'DUAL_NORMAL_DUAL_R091_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','同步接口互ping是否通','双机状态维护为组播报文，配置同步为tcp报文，如果双机同步接口ping不通，则可能存在配置同步功能不好使的情况\n来源：0807设计表，3.2双机部署规范性检查表，第91行。','TABLE',NULL,'BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1090,0,'migration-v502-59299-config','2026-11-01 08:49:46','migration-v502-59299-config','2026-11-01 08:49:46',0x00,1,NULL,NULL);

