INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442151,970000000000442001,'DUAL_VSM_R015_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','双主控分裂检测的四个主控管理口是否连接到同一交换机','如果四个主控的HA口/管理口没有连接到同一交换机且二层可通则设备发生双主控切换后会导致分裂检测功能失效\n来源：0807设计表，3.2双机部署规范性检查表，第15行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 15, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": true, \"originalName\": \"双主控环境下选择主控HA口/管理口作为分裂检测口时是否将四个主控的管理口连接到了同一个交换机上且二层可通\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'VSM','ENABLED',500,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

