INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442206,970000000000442001,'DUAL_NORMAL_DUAL_R087_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','同步接口光模块收发光检查','若存在成员口光模块收发光异常，需要及时更换光模块\n来源：0807设计表，3.2双机部署规范性检查表，第87行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 87, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"同步接口光模块收发光检查\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1050,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442207,970000000000442001,'DUAL_NORMAL_DUAL_R088_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','同步接口计数统计检查','dev_cfg eth sw show all查看，对应心跳物理口如果存在crc丢包、rxdrop丢包或txdrop丢包持续增长。错包多会影响心跳状态及同步配置情况。\n来源：0807设计表，3.2双机部署规范性检查表，第88行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 88, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"同步接口计数统计检查\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1060,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442208,970000000000442001,'DUAL_NORMAL_DUAL_R089_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','同步接口ip是否为私网ip','同步接口ip一定要配置私网ip（10.0.0.0/8，172.16.0.0/16，192.168.0.0/24，且不允许与现网地址冲突），尽量不要配置公网ip，否则在开启地域访问控制策略场景可能会影响会话及配置同步功能。\n来源：0807设计表，3.2双机部署规范性检查表，第89行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 89, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"同步接口ip是否为私网ip\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1070,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442209,970000000000442001,'DUAL_NORMAL_DUAL_R090_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机同步接口是否配置接口服务限制','同步接口禁止配置接口服务限制\n来源：0807设计表，3.2双机部署规范性检查表，第90行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 90, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"主备机同步接口是否配置接口服务限制\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1080,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442210,970000000000442001,'DUAL_NORMAL_DUAL_R091_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','同步接口互ping是否通','双机状态维护为组播报文，配置同步为tcp报文，如果双机同步接口ping不通，则可能存在配置同步功能不好使的情况\n来源：0807设计表，3.2双机部署规范性检查表，第91行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 91, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"同步接口互ping是否通\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1090,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

