INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442212,970000000000442001,'DUAL_NORMAL_DUAL_R093_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备设备VRID是否一致','VRID 取值为 1-255，同组虚拟路由器 VRID 保持一致，同组VRRP虚拟ip配置一致。\n来源：0807设计表，3.2双机部署规范性检查表，第93行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 93, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": true, \"originalName\": \"VRRP配置一致性：主备设备是否配置了相同的VRID和虚拟IP地址？\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1110,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

