INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442214,970000000000442001,'DUAL_NORMAL_DUAL_R094_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','物理接口IP与优先级：检查主备设备对应接口的物理IP，并确认优先级配置符合设计，监听接口/监听IP/BFD','根据现网设计需求定制主备优先级差异，满足客户主备切换需求。监听接口(板卡)/监听IP/BFD，优先级默认值 10（1-255)。\n缺省情况下，监视 IP Down 之后减少的优先级为 10。\n监视 IP，监视 BFD 不支持 IPv6。\n来源：0807设计表，3.2双机部署规范性检查表，第94行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 94, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"物理接口IP与优先级：检查主备设备对应接口的物理IP，并确认优先级配置符合设计，监听接口/监听IP/BFD\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1130,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442215,970000000000442001,'DUAL_NORMAL_DUAL_R095_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','Master/Backup状态验证：查看双机当前状态，确认与设计预期一致（例如，预期的设备是否为Master）','无非对称业务要求的场景，要保证正反向流量在同一台设备处理\n来源：0807设计表，3.2双机部署规范性检查表，第95行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 95, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"Master/Backup状态验证：查看双机当前状态，确认与设计预期一致（例如，预期的设备是否为Master）\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1140,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442216,970000000000442001,'DUAL_NORMAL_DUAL_R096_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机管理协议http/https/telnet/ssh开启状态是否一致','配置同步使用的是http/https/telnet/ssh协议，必须保证静默双机两端设备http/https/telnet/ssh配置一致\n来源：0807设计表，3.2双机部署规范性检查表，第96行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 96, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"主备机管理协议http/https/telnet/ssh开启状态是否一致\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1150,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442217,970000000000442001,'DUAL_NORMAL_DUAL_R097_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','配置同步功能检查','检查主备配置同步禁用开关是否关闭，默认开关关闭，此情况下配置同步才可正常。（功能位于 高可靠性--双机热备--配置同步参数 模块高级配置）\n来源：0807设计表，3.2双机部署规范性检查表，第97行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 97, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"配置同步功能检查\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1160,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442218,970000000000442001,'DUAL_NORMAL_DUAL_R098_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机会话同步功能是否均开启','主备机会话同步配置必须一致。若会话同步未开启，则主备切换会导致部分长连接业务持续异常，此情况下需让客户手动重新拉起业务。\n来源：0807设计表，3.2双机部署规范性检查表，第98行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 98, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"主备机会话同步功能是否均开启\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1170,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442219,970000000000442001,'DUAL_NORMAL_DUAL_R099_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否存在非对称业务，非对称业务必须要开启会话同步非对称模','请根据现网情况决定是否需要开启非对称模式，非对称流量必须开启非对称模式，若现网流量不是非对称流量，请关闭非对称模式，否则非对称模式下备机会话会老化，若流量切到备机，因没有会话会造成断网问题。\n来源：0807设计表，3.2双机部署规范性检查表，第99行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 99, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"是否存在非对称业务，非对称业务必须要开启会话同步非对称模\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1180,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442220,970000000000442001,'DUAL_NORMAL_DUAL_R100_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置接口延迟up','主要用于框式设备，以防备机在重启过程中因业务板未重启完成的情况接口短暂up影响业务。页面高可靠性--接口延迟配置查看是否有配置，或者命令行show run | in linkup-delay查看是否存在接口延迟up配置，然后再确定是哪些接口有此配置\n来源：0807设计表，3.2双机部署规范性检查表，第100行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 100, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"是否有配置接口延迟up\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1190,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442221,970000000000442001,'DUAL_NORMAL_DUAL_R101_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置监听业务板','主要用于框式设备，防止在单业务板场景下，主设备业务板重启，主备状态未切换而影响业务，默认需要配置\nvrrp track board string [reduced 1-255]，业务板卡要监听所有的。每个业务板推荐值是10，按实际情况调整。假设该设备业务板坏了，导致设备状态切换，此时业务流量将不会走这台设备。\n来源：0807设计表，3.2双机部署规范性检查表，第101行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 101, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"是否有配置监听业务板\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1200,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442222,970000000000442001,'DUAL_NORMAL_DUAL_R102_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查上下游设备是否有配置静态ARP/ND、MAC/IP绑定','如果上下游设备配置静态ARP/ND或MAC/IP绑定功能，主备机切换后会导致业务不通（部分组网中会开启主备机接口的MAC地址同步，同样也需要检查上下游设备静态ARP/ND或MAC/IP绑定是否有绑定接口）\n来源：0807设计表，3.2双机部署规范性检查表，第102行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 102, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"检查上下游设备是否有配置静态ARP/ND、MAC/IP绑定\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1210,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442223,970000000000442001,'DUAL_NORMAL_DUAL_R103_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查上下游设备是否有开启学习免费ARP','部分厂商默认不开启免费ARP学习或者关闭了免费ARP学习功能，会导致备机切为主机后需要等ARP老化后重新学习流量才能通，影响双机的收敛时间\n来源：0807设计表，3.2双机部署规范性检查表，第103行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 103, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"检查上下游设备是否有开启学习免费ARP\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1220,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442224,970000000000442001,'DUAL_NORMAL_DUAL_R104_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','抢占模式检查：确认抢占模式（Preempt）的配置是否符合业务需求','抢占模式（抢占、非抢占）抢占延时:0-360000*10ms，根据客户需求配置抢占模式以及延时。主备回切若配置延时，则回切会按照配置的时间延时后再回切，在部分场景下不能配置该功能，例如割接过程中出现问题快速回退，如果配置了该功能，就无法迅速回切来达到恢复业务的目的（可以通过直接修改初始优先级来实现主备迅速回切）\n来源：0807设计表，3.2双机部署规范性检查表，第104行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 104, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"抢占模式检查：确认抢占模式（Preempt）的配置是否符合业务需求\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1230,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442225,970000000000442001,'DUAL_NORMAL_DUAL_R105_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否配置VRRP状态同步组','在对称业务场景，确保上下行的VRRP主备一致，默认需要配置\nvrrp-sync-group string\nmaster-vrrp interface 接口 vrid [reduced 1-255]\n来源：0807设计表，3.2双机部署规范性检查表，第105行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 105, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"是否配置VRRP状态同步组\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'NORMAL_DUAL','ENABLED',1240,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

