INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442229,970000000000442001,'DUAL_CLUSTER_R116_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','确认设备组网是否为三层组网、虚服务IP与接口IP是否同网段','集群三层组网模式下，虚服务IP与接口IP、交换机互连IP不同网段，需要配置IP集群\n来源：0807设计表，3.2双机部署规范性检查表，第116行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 116, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"确认设备组网是否为三层组网、虚服务IP与接口IP是否同网段\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'CLUSTER','ENABLED',1280,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442230,970000000000442001,'DUAL_CLUSTER_R117_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','虚服务是否关联集群','虚服务若未关联集群，发生主备切换时虚服务不会发送免费arp，可能导致对端交换机arp无法切换影响业务\n来源：0807设计表，3.2双机部署规范性检查表，第117行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 117, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"虚服务是否关联集群\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'CLUSTER','ENABLED',1290,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`, `configuration_revision_id`, `stable_item_key`, `item_definition_version`, `item_type_code`, `business_category_code`, `item_name`, `item_description`, `interface_format_code`, `interface_schema`, `feedback_format_code`, `required_flag`, `work_mode_code`, `external_source_config`, `subtable_code`, `status_code`, `sort_order`, `version`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`, `external_interface_code`, `external_manual_fallback_flag`) VALUES (970000000000442231,970000000000442001,'DUAL_CLUSTER_R118_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','SNAT若使用地址池，是否关联集群','SNAT地址池若未关联集群，发生主备切换时地址池地址不会发送免费arp，可能导致对端交换机arp无法切换影响业务\n来源：0807设计表，3.2双机部署规范性检查表，第118行。','TABLE','{\"fields\": [{\"code\": \"executed\", \"type\": \"BOOLEAN\", \"label\": \"是否已核查\", \"required\": true}, {\"code\": \"normal\", \"type\": \"BOOLEAN\", \"label\": \"是否符合本次部署要求\", \"required\": true}, {\"code\": \"remark\", \"type\": \"TEXT\", \"label\": \"事实说明及特殊情况备注\", \"required\": true, \"visibleWhen\": {\"field\": \"normal\", \"equals\": false}}], \"source\": {\"row\": 118, \"file\": \"4、割接平台设计-数据整理（0807).xlsx\", \"part\": 1, \"sheet\": \"3.2双机部署规范性检查表\", \"split\": false, \"originalName\": \"SNAT若使用地址池，是否关联集群\"}}','BOOLEAN_REMARK',0x01,'DIRECT',NULL,'CLUSTER','ENABLED',1300,0,'cut-special-20261012','2026-10-17 17:41:21','cut-special-20261012','2026-10-17 17:41:21',0x00,1,NULL,NULL);

