SET SESSION sql_mode='IGNORE_SPACE,ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER $$
CREATE TRIGGER `trg_cut_assessment_level_source_u` BEFORE UPDATE ON `cut_assessment` FOR EACH ROW BEGIN
    IF OLD.assessment_status_code <> 'DRAFT' AND (
        NOT (NEW.service_level_source_record_id <=> OLD.service_level_source_record_id)
        OR NOT (CAST(NEW.manual_customer_service_level_code AS BINARY) <=> CAST(OLD.manual_customer_service_level_code AS BINARY))
        OR NOT (NEW.manual_customer_service_level_selected_by <=> OLD.manual_customer_service_level_selected_by)
        OR NOT (NEW.manual_customer_service_level_selected_at <=> OLD.manual_customer_service_level_selected_at)
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CUT_IMMUTABLE_HISTORY: assessment customer level selection';
    END IF;
END$$
DELIMITER ;

SET SESSION sql_mode='ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER $$
CREATE TRIGGER `trg_cut_plan_scheduled_time_immutable` BEFORE UPDATE ON `cut_plan_revision` FOR EACH ROW BEGIN
  IF OLD.status_code <> 'DRAFT' AND NOT (NEW.scheduled_time <=> OLD.scheduled_time) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CUT_IMMUTABLE_HISTORY: cut_plan_revision.scheduled_time';
  END IF;
END$$
DELIMITER ;

SET SESSION sql_mode='IGNORE_SPACE,ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER $$
CREATE TRIGGER `trg_cut_plan_support_submit` BEFORE UPDATE ON `cut_plan_revision` FOR EACH ROW BEGIN
  IF NEW.status_code='SUBMITTED' AND OLD.status_code='DRAFT' AND NEW.edit_mode_code='ONLINE_TEMPLATE_STANDARD' THEN
    IF (SELECT COUNT(DISTINCT role_code) FROM cut_cutover_support_arrangement
        WHERE tenant_id=NEW.tenant_id AND plan_revision_id=NEW.id AND deleted=b'0'
          AND role_code IN ('CUSTOMER','DP_FIRST_LINE')) <> 2
      OR EXISTS (SELECT 1 FROM cut_cutover_support_arrangement
        WHERE tenant_id=NEW.tenant_id AND plan_revision_id=NEW.id AND deleted=b'0'
          AND (CHAR_LENGTH(TRIM(person_name))=0 OR CHAR_LENGTH(TRIM(duty_description))=0
            OR CHAR_LENGTH(TRIM(phone))=0 OR arrive_time IS NULL
            OR (role_code<>'CUSTOMER' AND (person_source_code IS NULL OR person_source_code<>'SYSTEM_USER' OR person_source_id IS NULL)))) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CUT_SUPPORT_INCOMPLETE';
    END IF;
  END IF;
END$$
DELIMITER ;

SET SESSION sql_mode='ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER $$
CREATE TRIGGER `trg_cut_structured_10_d` BEFORE DELETE ON `cut_checklist_field_option` FOR EACH ROW BEGIN
  IF NOT EXISTS(SELECT 1 FROM cut_checklist_field_definition f
 LEFT JOIN cut_cutover_checklist_item_definition_revision d ON d.tenant_id=f.tenant_id AND d.id=f.item_definition_revision_id
 LEFT JOIN cut_cutover_configuration_revision p ON p.tenant_id=d.tenant_id AND p.id=d.configuration_revision_id
 LEFT JOIN cut_cutover_checklist_item i ON i.tenant_id=f.tenant_id AND i.id=f.custom_checklist_item_id
 LEFT JOIN cut_cutover_checklist c ON c.tenant_id=i.tenant_id AND c.id=i.checklist_id WHERE f.tenant_id=OLD.tenant_id AND f.id=OLD.field_definition_id AND ((p.id IS NOT NULL AND p.status_code='DRAFT' AND p.deleted=b'0') OR (c.id IS NOT NULL AND c.status_code='DRAFT' AND c.deleted=b'0'))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CUT_PARENT_FROZEN: cut_checklist_field_option';
  END IF;
END$$
DELIMITER ;

