DELIMITER $$
CREATE TRIGGER `trg_cut_support_draft_insert` BEFORE INSERT ON `cut_cutover_support_arrangement` FOR EACH ROW BEGIN
  IF NOT EXISTS (SELECT 1 FROM cut_plan_revision plan
    WHERE plan.id=NEW.plan_revision_id AND plan.tenant_id=NEW.tenant_id
      AND plan.status_code='DRAFT' AND plan.current_marker=1 AND plan.deleted=b'0') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CUT_PARENT_FROZEN: cut_cutover_support_arrangement';
  END IF;
END$$
DELIMITER ;

SET SESSION sql_mode='IGNORE_SPACE,ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER $$
CREATE TRIGGER `trg_cut_support_person_history` BEFORE UPDATE ON `cut_cutover_support_arrangement` FOR EACH ROW BEGIN
  IF EXISTS (SELECT 1 FROM cut_plan_revision p WHERE p.id=OLD.plan_revision_id AND p.tenant_id=OLD.tenant_id AND p.status_code<>'DRAFT')
    AND (NOT (NEW.person_source_code <=> OLD.person_source_code) OR NOT (NEW.person_source_id <=> OLD.person_source_id)
      OR NOT (NEW.person_source_version <=> OLD.person_source_version)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CUT_IMMUTABLE_HISTORY: support person source';
  END IF;
END$$
DELIMITER ;

SET SESSION sql_mode='ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER $$
CREATE TRIGGER `trg_cut_support_reference_update` BEFORE UPDATE ON `cut_cutover_support_arrangement` FOR EACH ROW BEGIN
  IF EXISTS (SELECT 1 FROM cut_plan_revision plan
    WHERE plan.id=OLD.plan_revision_id AND plan.tenant_id=OLD.tenant_id AND plan.status_code<>'DRAFT')
    AND (NOT (NEW.customer_contact_id <=> OLD.customer_contact_id)
      OR NOT (NEW.customer_contact_version <=> OLD.customer_contact_version)
      OR NOT (NEW.sort_order <=> OLD.sort_order)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CUT_IMMUTABLE_HISTORY: cut_cutover_support_arrangement';
  END IF;
  IF (NOT (NEW.plan_revision_id <=> OLD.plan_revision_id) OR NOT (NEW.tenant_id <=> OLD.tenant_id))
    AND NOT EXISTS (SELECT 1 FROM cut_plan_revision plan
      WHERE plan.id=NEW.plan_revision_id AND plan.tenant_id=NEW.tenant_id
        AND plan.status_code='DRAFT' AND plan.current_marker=1 AND plan.deleted=b'0') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CUT_PARENT_FROZEN: cut_cutover_support_arrangement';
  END IF;
END$$
DELIMITER ;

